import {chromium} from 'playwright';import fs from 'node:fs/promises';import assert from 'node:assert/strict';import {createHash} from 'node:crypto';assert.equal(process.env.GITHUB_ACTIONS,'true');const cases=[{"num":"04","lang":"yue","sha":"c7ac3c34c59c6b4c45cd45e53c6808e2242138ef2ca7fdc87afe249179be04d3","course":{"id":"hk-nobel-04-deisseroth-illustrated-v2","createdAt":"2026-10-24T06:18:36.481Z","stage":{"id":"hk-nobel-04-deisseroth-illustrated-v2","name":"戴瑟羅斯：他向藻類借來一束光（圖文講授・廣東話）","description":"先認識一位醫生與腦科學家，再看看藻類的感光本領如何變成研究神經活動的工具。從校園類比、真實照片與具體研究，理解這項諾獎的價值與界線。","createdAt":1792822716481,"updatedAt":1792822716481,"style":"人物與探險式科學敘事，暖白編輯版面、深藍標題、真實資料照片與清楚圖說","languageDirective":"所有學生可見文字使用香港繁體中文，以廣東話作適齡普通講授。先人物故事，再講研究難題、為甚麼獲獎、對普通人的價值和必要原理；類比有邊界，區分研究工具與仍待驗證的應用。不提供個人診療，不編童年或心理，不泛化所有情況。 所有角色回答與學生可見文字一律香港繁體中文，不混簡體。對初一學生只講必要主旨，不引入講稿以外分析方法、專業縮寫、純度數值或安全門檻。合適蛋白要在選定細胞表達，合適的光還要到達。工具幫研究者作受控比較，不是單憑同時出現就證明因果；研究工具不等於治療成功。 光遺傳學以光控制具有合適蛋白的指定細胞活動；光照和蛋白本身不是讀取或顯示自然放電的工具，觀察神經活動須另用合適的記錄方法。蛋白可能使細胞活動增強或受抑，須有合適對照；不可說成必然看到放電或單次比較證明全部因果。","generatedAgentConfigs":[{"id":"nobel04-teacher","name":"科學故事老師","role":"teacher","persona":"我會用簡單繁體中文，幫你看見這項研究最重要的發現，以及它對普通人的意義。 光遺傳學以光控制具有合適蛋白的指定細胞活動；光照和蛋白本身不是讀取或顯示自然放電的工具，觀察神經活動須另用合適的記錄方法。蛋白可能使細胞活動增強或受抑，須有合適對照；不可說成必然看到放電或單次比較證明全部因果。","avatar":"/avatars/teacher.png","color":"#24665f","priority":10},{"id":"nobel04-assistant","name":"科學小助手","role":"assistant","persona":"我會用本課生活比喻幫你理解，也提醒大家：比喻有界線，科學結論要連同條件記住。 光遺傳學以光控制具有合適蛋白的指定細胞活動；光照和蛋白本身不是讀取或顯示自然放電的工具，觀察神經活動須另用合適的記錄方法。蛋白可能使細胞活動增強或受抑，須有合適對照；不可說成必然看到放電或單次比較證明全部因果。","avatar":"/avatars/assist.png","color":"#2563eb","priority":7},{"id":"nobel04-student","name":"好奇同學","role":"student","persona":"我是AI同學，會用簡短的繁體中文試講自己的理解，再把發言機會留給你。 光遺傳學以光控制具有合適蛋白的指定細胞活動；光照和蛋白本身不是讀取或顯示自然放電的工具，觀察神經活動須另用合適的記錄方法。蛋白可能使細胞活動增強或受抑，須有合適對照；不可說成必然看到放電或單次比較證明全部因果。","avatar":"/avatars/curious.png","color":"#bf9949","priority":5}]},"scenes":[{"id":"nobel04-illustrated-01","stageId":"hk-nobel-04-deisseroth-illustrated-v2","title":"卡爾・戴瑟羅斯","order":1,"outlineId":"nobel04-illustrated-01-outline","createdAt":1792822716481,"updatedAt":1792822716481,"type":"slide","actions":[{"id":"nobel04-illustrated-01-speech","type":"speech","text":"資料照片入面嘅人，叫卡爾・戴瑟羅斯，英文係 Karl Deisseroth。佢係腦科學家，亦係精神科醫生。佢後來喺訪談入面回憶，細個時會好奇點解說話同文字會帶嚟感受，亦曾經問自己：感受可唔可以用科學研究？到醫學院見習精神科，佢見到患者需要好多幫助，而呢個領域仲有好多未解嘅問題，令佢決定走近精神科。呢段係佢親口講嘅回憶，唔係我哋估出嚟嘅童年天才故事。佢先喺大學學習，之後喺史丹福完成神經科學博士同醫學學位，再接受精神科訓練。二零二六年，佢同黑格曼、納格爾共同獲得諾貝爾生理學或醫學獎。三個人做嘅工作互相接力，仲有好多合作研究者參與。跟住落嚟，我哋會睇到一件幾意外嘅事：研究人嘅大腦，點解會需要向小小嘅藻類借一樣工具？","audioId":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2/audio/yue-HK/page-01.mp3","audioUrl":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2/audio/yue-HK/page-01.mp3"}],"content":{"type":"slide","canvas":{"id":"nobel04-illustrated-01-canvas","viewportSize":1000,"viewportRatio":0.5625,"theme":{"backgroundColor":"#f6f1e6","themeColors":["#24665f","#bf9949","#102b38"],"fontColor":"#102b38","fontName":"Microsoft JhengHei","outline":{"color":"#102b38","width":1,"style":"solid"},"shadow":{"h":0,"v":0,"blur":0,"color":"#000000"}},"elements":[{"type":"image","id":"nobel04-illustrated-01-art","left":0,"top":0,"width":1000,"height":562.5,"rotate":0,"fixedRatio":true,"src":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2/media/01-zh-Hant.png","name":"卡爾・戴瑟羅斯；怎樣知道，哪一群腦細胞真的有作用？"},{"type":"shape","id":"nobel04-illustrated-01-key","left":40,"top":100,"width":500,"height":250,"rotate":0,"fill":"transparent","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"image","id":"nobel04-illustrated-01-photo","left":666.0714285714286,"top":135.0,"width":217.85714285714286,"height":305.0,"rotate":0,"fixedRatio":true,"src":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2/media/source-portrait.jpg","name":"卡爾·戴瑟羅斯（Karl Deisseroth），2025年肖像。"},{"type":"text","id":"nobel04-illustrated-01-caption","left":610,"top":445,"width":340,"height":65,"rotate":0,"content":"<p style=\"margin:0;font-size:10px;line-height:1.3\"><p class=\"caption\">卡爾·戴瑟羅斯（Karl Deisseroth），2025年肖像。</p><p class=\"credit\">Christopher P. Michel · <a href=\"https://creativecommons.org/licenses/by-sa/4.0/\" rel=\"noopener\" target=\"_blank\">CC BY-SA 4.0</a> · <a href=\"https://commons.wikimedia.org/wiki/File:Karl_Deisseroth_2025_C_01.jpg\" rel=\"noopener\" target=\"_blank\">來源</a></p></p>","defaultColor":"#47616c","defaultFontName":"Microsoft JhengHei"},{"type":"shape","id":"nobel04-illustrated-01-footer","left":40,"top":519,"width":920,"height":33,"rotate":0,"fill":"#F5F0E8","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"text","id":"nobel04-illustrated-01-boundary","left":44,"top":523,"width":910,"height":27,"rotate":0,"content":"<p style=\"margin:0;font-size:10px;line-height:1.3\">教學插畫／類比，不是研究現場或實驗數據；研究及應用均有條件。</p>","defaultColor":"#47616c","defaultFontName":"Microsoft JhengHei"},{"type":"text","id":"nobel04-voice-link","left":44,"top":486,"width":430,"height":27,"rotate":0,"content":"<p style=\"margin:0;font-size:15px\"><a href=\"/classroom/hk-nobel-04-deisseroth-illustrated-v2-mandarin\">切換至普通話講解 →</a></p>","defaultColor":"#24665f","defaultFontName":"Microsoft JhengHei","link":{"type":"web","target":"/classroom/hk-nobel-04-deisseroth-illustrated-v2-mandarin"}}],"background":{"type":"solid","color":"#f6f1e6"},"script":"資料照片入面嘅人，叫卡爾・戴瑟羅斯，英文係 Karl Deisseroth。佢係腦科學家，亦係精神科醫生。佢後來喺訪談入面回憶，細個時會好奇點解說話同文字會帶嚟感受，亦曾經問自己：感受可唔可以用科學研究？到醫學院見習精神科，佢見到患者需要好多幫助，而呢個領域仲有好多未解嘅問題，令佢決定走近精神科。呢段係佢親口講嘅回憶，唔係我哋估出嚟嘅童年天才故事。佢先喺大學學習，之後喺史丹福完成神經科學博士同醫學學位，再接受精神科訓練。二零二六年，佢同黑格曼、納格爾共同獲得諾貝爾生理學或醫學獎。三個人做嘅工作互相接力，仲有好多合作研究者參與。跟住落嚟，我哋會睇到一件幾意外嘅事：研究人嘅大腦，點解會需要向小小嘅藻類借一樣工具？"},"script":"資料照片入面嘅人，叫卡爾・戴瑟羅斯，英文係 Karl Deisseroth。佢係腦科學家，亦係精神科醫生。佢後來喺訪談入面回憶，細個時會好奇點解說話同文字會帶嚟感受，亦曾經問自己：感受可唔可以用科學研究？到醫學院見習精神科，佢見到患者需要好多幫助，而呢個領域仲有好多未解嘅問題，令佢決定走近精神科。呢段係佢親口講嘅回憶，唔係我哋估出嚟嘅童年天才故事。佢先喺大學學習，之後喺史丹福完成神經科學博士同醫學學位，再接受精神科訓練。二零二六年，佢同黑格曼、納格爾共同獲得諾貝爾生理學或醫學獎。三個人做嘅工作互相接力，仲有好多合作研究者參與。跟住落嚟，我哋會睇到一件幾意外嘅事：研究人嘅大腦，點解會需要向小小嘅藻類借一樣工具？"}},{"id":"nobel04-illustrated-02","stageId":"hk-nobel-04-deisseroth-illustrated-v2","title":"一位醫生，也是一位研究者","order":2,"outlineId":"nobel04-illustrated-02-outline","createdAt":1792822716481,"updatedAt":1792822716481,"type":"slide","actions":[{"id":"nobel04-illustrated-02-speech","type":"speech","text":"先睇嚇呢張真實顯微照片。好多細胞好似連成一片網。像片用咗螢光標記，方便研究者分辨細胞；紅色綠色唔代表開心或者唔開心，亦唔係讀心術。你喺街上聽到朋友叫你，轉頭望，再揮手，大腦裏面有好多細胞同連接參與。科學家可以記錄某啲活動，但記錄到一群細胞同一時間活躍，仲未足以講清楚因果。好似你見到幾個人同時走出課室，唔可以單靠呢一幕就知道係邊個叫大家行出去。戴瑟羅斯同其他研究者想要一種更細緻嘅工具：如果能夠喺指定時間，改變選定細胞嘅活動，再睇結果有冇變，我哋就有更好嘅方法追問，呢啲細胞究竟有乜作用。當然，大腦係互相連接嘅網絡；改變一處，亦可能影響其他地方，唔係一粒細胞就包辦一個複雜想法。","audioId":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2/audio/yue-HK/page-02.mp3","audioUrl":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2/audio/yue-HK/page-02.mp3"}],"content":{"type":"slide","canvas":{"id":"nobel04-illustrated-02-canvas","viewportSize":1000,"viewportRatio":0.5625,"theme":{"backgroundColor":"#f6f1e6","themeColors":["#24665f","#bf9949","#102b38"],"fontColor":"#102b38","fontName":"Microsoft JhengHei","outline":{"color":"#102b38","width":1,"style":"solid"},"shadow":{"h":0,"v":0,"blur":0,"color":"#000000"}},"elements":[{"type":"image","id":"nobel04-illustrated-02-art","left":0,"top":0,"width":1000,"height":562.5,"rotate":0,"fixedRatio":true,"src":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2/media/02-zh-Hant.png","name":"一位醫生，也是一位研究者；他想更深入理解，腦細胞怎樣與感受和行為相連。"},{"type":"shape","id":"nobel04-illustrated-02-key","left":40,"top":100,"width":500,"height":250,"rotate":0,"fill":"transparent","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"image","id":"nobel04-illustrated-02-photo","left":620.0,"top":162.0550847457627,"width":310.0,"height":250.8898305084746,"rotate":0,"fixedRatio":true,"src":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2/media/source-neurons.png","name":"培養的大鼠神經細胞，2018年螢光顯微照片。紅綠顏色來自標記蛋白，不是細胞正在想甚麼的讀數。"},{"type":"text","id":"nobel04-illustrated-02-caption","left":610,"top":445,"width":340,"height":65,"rotate":0,"content":"<p style=\"margin:0;font-size:10px;line-height:1.3\">2018年培養大鼠神經細胞螢光照；紅綠為標記。Manuel Schottdorf · <a href=\"https://creativecommons.org/licenses/by-sa/4.0/\">CC BY-SA 4.0</a> · <a href=\"https://commons.wikimedia.org/wiki/File:Synapsin_and_CamK2_positive_neurons.png\">來源</a>。</p>","defaultColor":"#47616c","defaultFontName":"Microsoft JhengHei"},{"type":"shape","id":"nobel04-illustrated-02-footer","left":40,"top":519,"width":920,"height":33,"rotate":0,"fill":"#F5F0E8","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"text","id":"nobel04-illustrated-02-boundary","left":44,"top":523,"width":910,"height":27,"rotate":0,"content":"<p style=\"margin:0;font-size:10px;line-height:1.3\">教學插畫／類比，不是研究現場或實驗數據；研究及應用均有條件。</p>","defaultColor":"#47616c","defaultFontName":"Microsoft JhengHei"}],"background":{"type":"solid","color":"#f6f1e6"},"script":"先睇嚇呢張真實顯微照片。好多細胞好似連成一片網。像片用咗螢光標記，方便研究者分辨細胞；紅色綠色唔代表開心或者唔開心，亦唔係讀心術。你喺街上聽到朋友叫你，轉頭望，再揮手，大腦裏面有好多細胞同連接參與。科學家可以記錄某啲活動，但記錄到一群細胞同一時間活躍，仲未足以講清楚因果。好似你見到幾個人同時走出課室，唔可以單靠呢一幕就知道係邊個叫大家行出去。戴瑟羅斯同其他研究者想要一種更細緻嘅工具：如果能夠喺指定時間，改變選定細胞嘅活動，再睇結果有冇變，我哋就有更好嘅方法追問，呢啲細胞究竟有乜作用。當然，大腦係互相連接嘅網絡；改變一處，亦可能影響其他地方，唔係一粒細胞就包辦一個複雜想法。"},"script":"先睇嚇呢張真實顯微照片。好多細胞好似連成一片網。像片用咗螢光標記，方便研究者分辨細胞；紅色綠色唔代表開心或者唔開心，亦唔係讀心術。你喺街上聽到朋友叫你，轉頭望，再揮手，大腦裏面有好多細胞同連接參與。科學家可以記錄某啲活動，但記錄到一群細胞同一時間活躍，仲未足以講清楚因果。好似你見到幾個人同時走出課室，唔可以單靠呢一幕就知道係邊個叫大家行出去。戴瑟羅斯同其他研究者想要一種更細緻嘅工具：如果能夠喺指定時間，改變選定細胞嘅活動，再睇結果有冇變，我哋就有更好嘅方法追問，呢啲細胞究竟有乜作用。當然，大腦係互相連接嘅網絡；改變一處，亦可能影響其他地方，唔係一粒細胞就包辦一個複雜想法。"}},{"id":"nobel04-illustrated-03","stageId":"hk-nobel-04-deisseroth-illustrated-v2","title":"看見一起發生，還不夠","order":3,"outlineId":"nobel04-illustrated-03-outline","createdAt":1792822716481,"updatedAt":1792822716481,"type":"interactive","actions":[{"id":"nobel04-illustrated-03-speech","type":"speech","text":"想像港鐵車站一邊有人排隊，一邊有閘口開放。你睇到兩件事一齊發生，可唔可以就話閘口開放造成擠擁？未必。可能同到站列車、上班時間或者其他出入口有關。研究腦細胞都類似：睇到某啲細胞活躍同某個行為同時出現，仲唔夠知道佢有咩作用。研究者要喺合適條件下改變某個環節，再同對照比較。車站只係類比，唔係話大腦真係一個車站。你可以先揀一個判斷，再睇解釋；答錯可以再揀。","audioId":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2/audio/yue-HK/page-03.mp3","audioUrl":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2/audio/yue-HK/page-03.mp3"}],"content":{"type":"interactive","url":"","html":"<!doctype html><html lang=\"zh-Hant-HK\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><style>html,body{margin:0;width:100%;min-height:100%;background:#f5f0e8;color:#102b38;font-family:system-ui,\"PingFang HK\",sans-serif}main{max-width:1080px;margin:auto;padding:14px 24px}.art{display:block;width:100%;max-height:48vh;object-fit:contain}.question{border:2px solid #b5d4c5;background:#fffaf0;border-radius:18px;padding:15px 22px}h2{font-family:\"Songti TC\",serif;font-size:clamp(18px,2.3vw,27px);margin:0 0 12px}.options{display:flex;gap:12px;flex-wrap:wrap}button{font:inherit;font-size:clamp(16px,1.7vw,22px);border:2px solid #368471;border-radius:10px;padding:10px 18px;background:#fff}button[aria-pressed=true]{background:#b5e5cf}.feedback{font-size:17px;line-height:1.55;min-height:2em}.note{font-size:13px;color:#47616c}</style><main><img class=\"art\" src=\"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2/media/03-zh-Hant.png\" alt=\"看見一起發生，還不夠\"><section class=\"question\"><h2>只看見車站擠擁和閘口開放同時出現，能直接說閘口造成擠擁嗎？</h2><div class=\"options\"><button data-choice=\"0\" aria-pressed=\"false\">能，同時出現就足夠。</button><button data-choice=\"1\" aria-pressed=\"false\">不能，還要比較其他可能原因。</button></div><p class=\"feedback\" id=\"feedback\" aria-live=\"polite\"></p></section><p class=\"note\">教學類比與簡化示意，不是實驗數據；可再次選擇，重新比較。真實研究仍需更多條件與對照。</p></main><script>document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-choice]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.getElementById('feedback').textContent=b.dataset.choice==='1'?'對。還要考慮列車、時間和其他出入口，並作合適的對照比較。':'同時出現不等於因果；不能排除到站列車、上班時間或其他原因。你可以再選。'})</script></html>","widgetType":"html","widgetConfig":{}}},{"id":"nobel04-illustrated-04","stageId":"hk-nobel-04-deisseroth-illustrated-v2","title":"線索來自一種微藻","order":4,"outlineId":"nobel04-illustrated-04-outline","createdAt":1792822716481,"updatedAt":1792822716481,"type":"slide","actions":[{"id":"nobel04-illustrated-04-speech","type":"speech","text":"故事而家轉去一個好細嘅主角：萊茵衣藻。佢係單細胞綠藻，可以對光作出反應。畫面係手繪教學插畫，唔係電子顯微影像，亦唔係當年嘅實驗現場。黑格曼、納格爾同其他研究者，研究藻類點樣感光，找到一類好特別嘅蛋白質。其中有一種叫通道視紫紅質二，簡稱 ChR2。個名長唔緊要，記住佢嘅本領就得：收到合適嘅光，蛋白通道可以打開，畀帶電粒子通過細胞膜，令細胞嘅電狀態改變。我哋用受光控制嘅小門作比喻。佢唔係真係有門鉸同鎖匙，而係蛋白質嘅形狀同通道功能會受光影響。最有趣嘅轉折係：一種微小藻類嘅感光本領，竟然可以為研究神經細胞提供線索。不過，找到藻類蛋白，同整成可靠嘅腦科學工具，中間仲有一大段工作。","audioId":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2/audio/yue-HK/page-04.mp3","audioUrl":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2/audio/yue-HK/page-04.mp3"}],"content":{"type":"slide","canvas":{"id":"nobel04-illustrated-04-canvas","viewportSize":1000,"viewportRatio":0.5625,"theme":{"backgroundColor":"#f6f1e6","themeColors":["#24665f","#bf9949","#102b38"],"fontColor":"#102b38","fontName":"Microsoft JhengHei","outline":{"color":"#102b38","width":1,"style":"solid"},"shadow":{"h":0,"v":0,"blur":0,"color":"#000000"}},"elements":[{"type":"image","id":"nobel04-illustrated-04-art","left":0,"top":0,"width":1000,"height":562.5,"rotate":0,"fixedRatio":true,"src":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2/media/04-zh-Hant.png","name":"線索來自一種微藻；有些藻類蛋白，能把合適的光連到細胞電訊號。"},{"type":"shape","id":"nobel04-illustrated-04-key","left":40,"top":100,"width":500,"height":250,"rotate":0,"fill":"transparent","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"shape","id":"nobel04-illustrated-04-footer","left":40,"top":519,"width":920,"height":33,"rotate":0,"fill":"#F5F0E8","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"text","id":"nobel04-illustrated-04-boundary","left":44,"top":523,"width":910,"height":27,"rotate":0,"content":"<p style=\"margin:0;font-size:10px;line-height:1.3\">教學插畫／類比，不是研究現場或實驗數據；研究及應用均有條件。</p>","defaultColor":"#47616c","defaultFontName":"Microsoft JhengHei"}],"background":{"type":"solid","color":"#f6f1e6"},"script":"故事而家轉去一個好細嘅主角：萊茵衣藻。佢係單細胞綠藻，可以對光作出反應。畫面係手繪教學插畫，唔係電子顯微影像，亦唔係當年嘅實驗現場。黑格曼、納格爾同其他研究者，研究藻類點樣感光，找到一類好特別嘅蛋白質。其中有一種叫通道視紫紅質二，簡稱 ChR2。個名長唔緊要，記住佢嘅本領就得：收到合適嘅光，蛋白通道可以打開，畀帶電粒子通過細胞膜，令細胞嘅電狀態改變。我哋用受光控制嘅小門作比喻。佢唔係真係有門鉸同鎖匙，而係蛋白質嘅形狀同通道功能會受光影響。最有趣嘅轉折係：一種微小藻類嘅感光本領，竟然可以為研究神經細胞提供線索。不過，找到藻類蛋白，同整成可靠嘅腦科學工具，中間仲有一大段工作。"},"script":"故事而家轉去一個好細嘅主角：萊茵衣藻。佢係單細胞綠藻，可以對光作出反應。畫面係手繪教學插畫，唔係電子顯微影像，亦唔係當年嘅實驗現場。黑格曼、納格爾同其他研究者，研究藻類點樣感光，找到一類好特別嘅蛋白質。其中有一種叫通道視紫紅質二，簡稱 ChR2。個名長唔緊要，記住佢嘅本領就得：收到合適嘅光，蛋白通道可以打開，畀帶電粒子通過細胞膜，令細胞嘅電狀態改變。我哋用受光控制嘅小門作比喻。佢唔係真係有門鉸同鎖匙，而係蛋白質嘅形狀同通道功能會受光影響。最有趣嘅轉折係：一種微小藻類嘅感光本領，竟然可以為研究神經細胞提供線索。不過，找到藻類蛋白，同整成可靠嘅腦科學工具，中間仲有一大段工作。"}},{"id":"nobel04-illustrated-05","stageId":"hk-nobel-04-deisseroth-illustrated-v2","title":"需要三部分配合","order":5,"outlineId":"nobel04-illustrated-05-outline","createdAt":1792822716481,"updatedAt":1792822716481,"type":"slide","actions":[{"id":"nobel04-illustrated-05-speech","type":"speech","text":"如果藻類有一個受光控制嘅小門，將佢用喺神經細胞，係咪就容易？其實唔係。研究者唔係將整隻藻類搬入大腦，而係運用編碼蛋白嘅基因，令選定細胞自己製造相應蛋白。蛋白要去到細胞膜上面，而且喺新環境仍然工作，先有用。然後，合適嘅光仲要送到研究目標。畫面用三個部分幫我哋記住：合適蛋白、特定細胞，同送達嘅光。呢項研究同時要處理生物學同工程問題。呢啲係專業實驗研究，唔係照住圖就可以自己操作。戴瑟羅斯同團隊要將一個有希望嘅想法，變成能夠反覆使用、檢查結果嘅方法。由點子去到工具，正正需要好多訓練、合作同實驗。","audioId":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2/audio/yue-HK/page-05.mp3","audioUrl":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2/audio/yue-HK/page-05.mp3"}],"content":{"type":"slide","canvas":{"id":"nobel04-illustrated-05-canvas","viewportSize":1000,"viewportRatio":0.5625,"theme":{"backgroundColor":"#f6f1e6","themeColors":["#24665f","#bf9949","#102b38"],"fontColor":"#102b38","fontName":"Microsoft JhengHei","outline":{"color":"#102b38","width":1,"style":"solid"},"shadow":{"h":0,"v":0,"blur":0,"color":"#000000"}},"elements":[{"type":"image","id":"nobel04-illustrated-05-art","left":0,"top":0,"width":1000,"height":562.5,"rotate":0,"fixedRatio":true,"src":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2/media/05-zh-Hant.png","name":"需要三部分配合；合適蛋白、特定細胞、送達的光。"},{"type":"shape","id":"nobel04-illustrated-05-key","left":40,"top":100,"width":500,"height":250,"rotate":0,"fill":"transparent","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"shape","id":"nobel04-illustrated-05-footer","left":40,"top":519,"width":920,"height":33,"rotate":0,"fill":"#F5F0E8","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"text","id":"nobel04-illustrated-05-boundary","left":44,"top":523,"width":910,"height":27,"rotate":0,"content":"<p style=\"margin:0;font-size:10px;line-height:1.3\">教學插畫／類比，不是研究現場或實驗數據；研究及應用均有條件。</p>","defaultColor":"#47616c","defaultFontName":"Microsoft JhengHei"}],"background":{"type":"solid","color":"#f6f1e6"},"script":"如果藻類有一個受光控制嘅小門，將佢用喺神經細胞，係咪就容易？其實唔係。研究者唔係將整隻藻類搬入大腦，而係運用編碼蛋白嘅基因，令選定細胞自己製造相應蛋白。蛋白要去到細胞膜上面，而且喺新環境仍然工作，先有用。然後，合適嘅光仲要送到研究目標。畫面用三個部分幫我哋記住：合適蛋白、特定細胞，同送達嘅光。呢項研究同時要處理生物學同工程問題。呢啲係專業實驗研究，唔係照住圖就可以自己操作。戴瑟羅斯同團隊要將一個有希望嘅想法，變成能夠反覆使用、檢查結果嘅方法。由點子去到工具，正正需要好多訓練、合作同實驗。"},"script":"如果藻類有一個受光控制嘅小門，將佢用喺神經細胞，係咪就容易？其實唔係。研究者唔係將整隻藻類搬入大腦，而係運用編碼蛋白嘅基因，令選定細胞自己製造相應蛋白。蛋白要去到細胞膜上面，而且喺新環境仍然工作，先有用。然後，合適嘅光仲要送到研究目標。畫面用三個部分幫我哋記住：合適蛋白、特定細胞，同送達嘅光。呢項研究同時要處理生物學同工程問題。呢啲係專業實驗研究，唔係照住圖就可以自己操作。戴瑟羅斯同團隊要將一個有希望嘅想法，變成能夠反覆使用、檢查結果嘅方法。由點子去到工具，正正需要好多訓練、合作同實驗。"}},{"id":"nobel04-illustrated-06","stageId":"hk-nobel-04-deisseroth-illustrated-v2","title":"2005：把工具帶進神經研究","order":6,"outlineId":"nobel04-illustrated-06-outline","createdAt":1792822716481,"updatedAt":1792822716481,"type":"slide","actions":[{"id":"nobel04-illustrated-06-speech","type":"speech","text":"到二零零五年，一篇重要論文發表咗。研究者讓哺乳動物神經細胞表達 ChR2，再用快速光刺激，顯示可以精細控制神經細胞嘅電訊號。呢度唔係話光突然令普通腦細胞全部有反應，而係先有具備相應蛋白嘅細胞，再有合適光刺激，兩者配合。論文作者唔止一個人，包括博伊登、張鋒、班貝格、納格爾同戴瑟羅斯。你唔需要背曬人名，但要明白：我哋每課講一位主角，並唔代表所有成果都由佢一個人完成。之後，研究者繼續發展方法，將光控制帶入活體動物研究，亦發展出可以增加或者抑制活動嘅不同工具。真正改變腦科學嘅，係研究者更能選擇喺邊啲細胞、邊個時間施加改變，再同記錄同觀察配合，研究因果關係。","audioId":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2/audio/yue-HK/page-06.mp3","audioUrl":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2/audio/yue-HK/page-06.mp3"}],"content":{"type":"slide","canvas":{"id":"nobel04-illustrated-06-canvas","viewportSize":1000,"viewportRatio":0.5625,"theme":{"backgroundColor":"#f6f1e6","themeColors":["#24665f","#bf9949","#102b38"],"fontColor":"#102b38","fontName":"Microsoft JhengHei","outline":{"color":"#102b38","width":1,"style":"solid"},"shadow":{"h":0,"v":0,"blur":0,"color":"#000000"}},"elements":[{"type":"image","id":"nobel04-illustrated-06-art","left":0,"top":0,"width":1000,"height":562.5,"rotate":0,"fixedRatio":true,"src":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2/media/06-zh-Hant.png","name":"2005：把工具帶進神經研究；戴瑟羅斯與合作者，讓光能用來控制神經活動。"},{"type":"shape","id":"nobel04-illustrated-06-key","left":40,"top":100,"width":500,"height":250,"rotate":0,"fill":"transparent","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"shape","id":"nobel04-illustrated-06-footer","left":40,"top":519,"width":920,"height":33,"rotate":0,"fill":"#F5F0E8","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"text","id":"nobel04-illustrated-06-boundary","left":44,"top":523,"width":910,"height":27,"rotate":0,"content":"<p style=\"margin:0;font-size:10px;line-height:1.3\">教學插畫／類比，不是研究現場或實驗數據；研究及應用均有條件。</p>","defaultColor":"#47616c","defaultFontName":"Microsoft JhengHei"}],"background":{"type":"solid","color":"#f6f1e6"},"script":"到二零零五年，一篇重要論文發表咗。研究者讓哺乳動物神經細胞表達 ChR2，再用快速光刺激，顯示可以精細控制神經細胞嘅電訊號。呢度唔係話光突然令普通腦細胞全部有反應，而係先有具備相應蛋白嘅細胞，再有合適光刺激，兩者配合。論文作者唔止一個人，包括博伊登、張鋒、班貝格、納格爾同戴瑟羅斯。你唔需要背曬人名，但要明白：我哋每課講一位主角，並唔代表所有成果都由佢一個人完成。之後，研究者繼續發展方法，將光控制帶入活體動物研究，亦發展出可以增加或者抑制活動嘅不同工具。真正改變腦科學嘅，係研究者更能選擇喺邊啲細胞、邊個時間施加改變，再同記錄同觀察配合，研究因果關係。"},"script":"到二零零五年，一篇重要論文發表咗。研究者讓哺乳動物神經細胞表達 ChR2，再用快速光刺激，顯示可以精細控制神經細胞嘅電訊號。呢度唔係話光突然令普通腦細胞全部有反應，而係先有具備相應蛋白嘅細胞，再有合適光刺激，兩者配合。論文作者唔止一個人，包括博伊登、張鋒、班貝格、納格爾同戴瑟羅斯。你唔需要背曬人名，但要明白：我哋每課講一位主角，並唔代表所有成果都由佢一個人完成。之後，研究者繼續發展方法，將光控制帶入活體動物研究，亦發展出可以增加或者抑制活動嘅不同工具。真正改變腦科學嘅，係研究者更能選擇喺邊啲細胞、邊個時間施加改變，再同記錄同觀察配合，研究因果關係。"}},{"id":"nobel04-illustrated-07","stageId":"hk-nobel-04-deisseroth-illustrated-v2","title":"光怎樣改變細胞訊號？","order":7,"outlineId":"nobel04-illustrated-07-outline","createdAt":1792822716481,"updatedAt":1792822716481,"type":"interactive","actions":[{"id":"nobel04-illustrated-07-speech","type":"speech","text":"而家我哋將原理收窄到最重要嘅一條線。以 ChR2 呢種工具為例，第一，選定細胞要表達感光蛋白。第二，合適嘅光要到達呢啲蛋白。第三，通道打開，帶電粒子流動，細胞嘅電狀態就會改變。之後，研究者仲要記錄神經訊號或者觀察行為，先知道影響係乜。你可以將佢想成受光控制嘅小門，但比喻只講通道可以受控制，唔係細胞入面真係有一扇門。亦唔可以將光想成遙控器裏面一串命令，叫一個人而家開心、而家忘記功課。大腦有好多互相連接嘅細胞，改變選定細胞可能經網絡影響其他部分，複雜行為唔係簡單一按即成。呢度有一個小小嘅紙上比較：具備 ChR2 同收到合適光，兩個條件點樣配合？你可以試著選一個情況，睇嚇個簡化示意會點解釋。呢個係教學示意，唔係實驗數據或者對每一粒細胞嘅保證。","audioId":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2/audio/yue-HK/page-07.mp3","audioUrl":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2/audio/yue-HK/page-07.mp3"}],"content":{"type":"interactive","url":"","html":"<!doctype html><html lang=\"zh-Hant-HK\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><style>html,body{margin:0;width:100%;min-height:100%;background:#f5f0e8;color:#102b38;font-family:system-ui,\"PingFang HK\",sans-serif}main{max-width:1080px;margin:auto;padding:14px 24px}.art{display:block;width:100%;max-height:48vh;object-fit:contain}.question{border:2px solid #b5d4c5;background:#fffaf0;border-radius:18px;padding:15px 22px}h2{font-family:\"Songti TC\",serif;font-size:clamp(18px,2.3vw,27px);margin:0 0 12px}.options{display:flex;gap:12px;flex-wrap:wrap}button{font:inherit;font-size:clamp(16px,1.7vw,22px);border:2px solid #368471;border-radius:10px;padding:10px 18px;background:#fff}button[aria-pressed=true]{background:#b5e5cf}.feedback{font-size:17px;line-height:1.55;min-height:2em}.note{font-size:13px;color:#47616c}</style><main><img class=\"art\" src=\"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2/media/07-zh-Hant.png\" alt=\"光怎樣改變細胞訊號？\"><section class=\"question small\"><h2>點選兩個條件，看看這個簡化示意怎樣解釋</h2><div class=\"options\"><button aria-pressed=\"false\" data-condition=\"protein\">感光蛋白：未設定</button><button aria-pressed=\"false\" data-condition=\"light\">合適光：未設定</button></div><p class=\"feedback\" id=\"logic-feedback\" role=\"status\">先看看兩個條件怎樣配合。這不是實驗數據。</p></section><p class=\"note\">教學類比與簡化示意，不是實驗數據；可再次選擇，重新比較。真實研究仍需更多條件與對照。</p></main><script>const state={protein:false,light:false};function update(){document.querySelectorAll('[data-condition]').forEach(b=>{const k=b.dataset.condition;b.setAttribute('aria-pressed',String(state[k]));b.textContent=(k==='protein'?'感光蛋白':'合適光')+'：'+(state[k]?'已設定':'未設定');});const result=!state.protein?'未設定ChR2：本示意不能用ChR2解釋光的效應。這不表示細胞完全沒有其他活動。':!state.light?'有感光蛋白，但未設定合適光：尚未加入本示意的光控制條件。':'具備ChR2與合適光：通道可開啟、改變電狀態。是否產生神經放電仍取決於實驗條件。';document.getElementById('logic-feedback').textContent=result;}document.querySelectorAll('[data-condition]').forEach(b=>b.addEventListener('click',()=>{const k=b.dataset.condition;state[k]=!state[k];update();}));\n</script></html>","widgetType":"html","widgetConfig":{}}},{"id":"nobel04-illustrated-08","stageId":"hk-nobel-04-deisseroth-illustrated-v2","title":"為甚麼值得諾獎？","order":8,"outlineId":"nobel04-illustrated-08-outline","createdAt":1792822716481,"updatedAt":1792822716481,"type":"slide","actions":[{"id":"nobel04-illustrated-08-speech","type":"speech","text":"點解呢件事值得諾貝爾獎？唔係因為藍光本身好神奇，亦唔係因為已經解開大腦所有秘密。頒獎理由肯定嘅係光控離子通道同光遺傳學嘅發現。黑格曼同納格爾等人研究到藻類蛋白嘅特別本領，戴瑟羅斯同合作者再將佢發展成精細研究神經活動嘅工具。以前單靠見到兩件事一齊發生，可能難以分清邊個影響邊個。多咗一種能夠改變選定細胞活動嘅方法，研究者就可以設計更有力嘅比較。不過，仍然要有對照，檢查照光本身有冇其他影響，亦要配合其他測量。呢種方法傳到唔同實驗室，令更多人可以追查各自嘅問題。偉大之處係人類多咗一種研究能力，好似為大家多造咗一件精細儀器。佢唔只服務一篇論文，而係令一大批原本難答嘅問題，變得更有機會搵到答案。","audioId":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2/audio/yue-HK/page-08.mp3","audioUrl":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2/audio/yue-HK/page-08.mp3"},{"id":"nobel04-illustrated-08-discussion","type":"discussion","agentId":"nobel04-assistant","topic":"為甚麼只看細胞活動還不夠？新工具多帶來了甚麼？","prompt":"這是香港初一課堂的一段簡短討論。三個AI角色都必須輪流各自發言，不代寫其他角色；全程用易懂廣東話，所有文字只用繁體中文，不混簡體。每位最多兩句短句，不展開新題目或講稿外的專業分析。科學小助手（AI助教）先說明「港鐵車站」比喻的一個界線；科學故事老師（AI老師）接着用一句話說本課發現為甚麼重要；好奇同學（AI同學角色）最後用自己的話複述學到的一個重點，不提出新的專業問題。三位AI都發言後，才把發言交回真人學生，不追加第四輪；這段毋須新增白板或圖表。守住本課證據範圍：合適蛋白要在選定細胞表達，合適的光還要到達。工具幫研究者作受控比較，不是單憑同時出現就證明因果；研究工具不等於治療成功。 光遺傳學以光控制具有合適蛋白的指定細胞活動；光照和蛋白本身不是讀取或顯示自然放電的工具，觀察神經活動須另用合適的記錄方法。蛋白可能使細胞活動增強或受抑，須有合適對照；不可說成必然看到放電或單次比較證明全部因果。 每位都以香港繁體字回答，例如「等於」；老師和同學要分清用光干預細胞活動與另用工具記錄活動。"}],"content":{"type":"slide","canvas":{"id":"nobel04-illustrated-08-canvas","viewportSize":1000,"viewportRatio":0.5625,"theme":{"backgroundColor":"#f6f1e6","themeColors":["#24665f","#bf9949","#102b38"],"fontColor":"#102b38","fontName":"Microsoft JhengHei","outline":{"color":"#102b38","width":1,"style":"solid"},"shadow":{"h":0,"v":0,"blur":0,"color":"#000000"}},"elements":[{"type":"image","id":"nobel04-illustrated-08-art","left":0,"top":0,"width":1000,"height":562.5,"rotate":0,"fixedRatio":true,"src":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2/media/08-zh-Hant.png","name":"為甚麼值得諾獎？；從觀察活動，前進到有條件地測試因果作用。"},{"type":"shape","id":"nobel04-illustrated-08-key","left":40,"top":100,"width":500,"height":250,"rotate":0,"fill":"transparent","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"shape","id":"nobel04-illustrated-08-footer","left":40,"top":519,"width":920,"height":33,"rotate":0,"fill":"#F5F0E8","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"text","id":"nobel04-illustrated-08-boundary","left":44,"top":523,"width":910,"height":27,"rotate":0,"content":"<p style=\"margin:0;font-size:10px;line-height:1.3\">教學插畫／類比，不是研究現場或實驗數據；研究及應用均有條件。</p>","defaultColor":"#47616c","defaultFontName":"Microsoft JhengHei"}],"background":{"type":"solid","color":"#f6f1e6"},"script":"點解呢件事值得諾貝爾獎？唔係因為藍光本身好神奇，亦唔係因為已經解開大腦所有秘密。頒獎理由肯定嘅係光控離子通道同光遺傳學嘅發現。黑格曼同納格爾等人研究到藻類蛋白嘅特別本領，戴瑟羅斯同合作者再將佢發展成精細研究神經活動嘅工具。以前單靠見到兩件事一齊發生，可能難以分清邊個影響邊個。多咗一種能夠改變選定細胞活動嘅方法，研究者就可以設計更有力嘅比較。不過，仍然要有對照，檢查照光本身有冇其他影響，亦要配合其他測量。呢種方法傳到唔同實驗室，令更多人可以追查各自嘅問題。偉大之處係人類多咗一種研究能力，好似為大家多造咗一件精細儀器。佢唔只服務一篇論文，而係令一大批原本難答嘅問題，變得更有機會搵到答案。"},"script":"點解呢件事值得諾貝爾獎？唔係因為藍光本身好神奇，亦唔係因為已經解開大腦所有秘密。頒獎理由肯定嘅係光控離子通道同光遺傳學嘅發現。黑格曼同納格爾等人研究到藻類蛋白嘅特別本領，戴瑟羅斯同合作者再將佢發展成精細研究神經活動嘅工具。以前單靠見到兩件事一齊發生，可能難以分清邊個影響邊個。多咗一種能夠改變選定細胞活動嘅方法，研究者就可以設計更有力嘅比較。不過，仍然要有對照，檢查照光本身有冇其他影響，亦要配合其他測量。呢種方法傳到唔同實驗室，令更多人可以追查各自嘅問題。偉大之處係人類多咗一種研究能力，好似為大家多造咗一件精細儀器。佢唔只服務一篇論文，而係令一大批原本難答嘅問題，變得更有機會搵到答案。"}},{"id":"nobel04-illustrated-09","stageId":"hk-nobel-04-deisseroth-illustrated-v2","title":"普通人關心的問題","order":9,"outlineId":"nobel04-illustrated-09-outline","createdAt":1792822716481,"updatedAt":1792822716481,"type":"slide","actions":[{"id":"nobel04-illustrated-09-speech","type":"speech","text":"站喺普通人嘅角度，我哋最關心嘅可能係：如果家人長期受腦部或者精神疾病困擾，研究有冇機會幫到佢？光遺傳學嘅一個重要價值，係幫助研究者將問題問得更清楚。例如二零一一年嘅一項小鼠研究，研究者改變某啲腦區之間特定連接嘅活動，觀察到小鼠焦慮樣行為會有變化。重點唔係要你背腦區名，而係原來唔同連接可能有唔同作用；只係講某個大範圍腦區活躍，可能仲太粗略。更加清楚地瞭解相關細胞同連接，可能為後續藥物或者其他治療研究提供方向。但我哋要守住一條重要界線：小鼠嘅行為指標，唔等同完整理解一個人嘅感受。動物研究有發現，亦唔等於人嘅焦慮已經可以用呢個方法治好。由瞭解機制去到可靠、安全嘅治療，仲需要好多步、好多研究。","audioId":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2/audio/yue-HK/page-09.mp3","audioUrl":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2/audio/yue-HK/page-09.mp3"}],"content":{"type":"slide","canvas":{"id":"nobel04-illustrated-09-canvas","viewportSize":1000,"viewportRatio":0.5625,"theme":{"backgroundColor":"#f6f1e6","themeColors":["#24665f","#bf9949","#102b38"],"fontColor":"#102b38","fontName":"Microsoft JhengHei","outline":{"color":"#102b38","width":1,"style":"solid"},"shadow":{"h":0,"v":0,"blur":0,"color":"#000000"}},"elements":[{"type":"image","id":"nobel04-illustrated-09-art","left":0,"top":0,"width":1000,"height":562.5,"rotate":0,"fixedRatio":true,"src":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2/media/09-zh-Hant.png","name":"普通人關心的問題；睡眠、記憶和情緒研究，多了一種重要工具。"},{"type":"shape","id":"nobel04-illustrated-09-key","left":40,"top":100,"width":500,"height":250,"rotate":0,"fill":"transparent","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"shape","id":"nobel04-illustrated-09-footer","left":40,"top":519,"width":920,"height":33,"rotate":0,"fill":"#F5F0E8","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"text","id":"nobel04-illustrated-09-boundary","left":44,"top":523,"width":910,"height":27,"rotate":0,"content":"<p style=\"margin:0;font-size:10px;line-height:1.3\">教學插畫／類比，不是研究現場或實驗數據；研究及應用均有條件。</p>","defaultColor":"#47616c","defaultFontName":"Microsoft JhengHei"}],"background":{"type":"solid","color":"#f6f1e6"},"script":"站喺普通人嘅角度，我哋最關心嘅可能係：如果家人長期受腦部或者精神疾病困擾，研究有冇機會幫到佢？光遺傳學嘅一個重要價值，係幫助研究者將問題問得更清楚。例如二零一一年嘅一項小鼠研究，研究者改變某啲腦區之間特定連接嘅活動，觀察到小鼠焦慮樣行為會有變化。重點唔係要你背腦區名，而係原來唔同連接可能有唔同作用；只係講某個大範圍腦區活躍，可能仲太粗略。更加清楚地瞭解相關細胞同連接，可能為後續藥物或者其他治療研究提供方向。但我哋要守住一條重要界線：小鼠嘅行為指標，唔等同完整理解一個人嘅感受。動物研究有發現，亦唔等於人嘅焦慮已經可以用呢個方法治好。由瞭解機制去到可靠、安全嘅治療，仲需要好多步、好多研究。"},"script":"站喺普通人嘅角度，我哋最關心嘅可能係：如果家人長期受腦部或者精神疾病困擾，研究有冇機會幫到佢？光遺傳學嘅一個重要價值，係幫助研究者將問題問得更清楚。例如二零一一年嘅一項小鼠研究，研究者改變某啲腦區之間特定連接嘅活動，觀察到小鼠焦慮樣行為會有變化。重點唔係要你背腦區名，而係原來唔同連接可能有唔同作用；只係講某個大範圍腦區活躍，可能仲太粗略。更加清楚地瞭解相關細胞同連接，可能為後續藥物或者其他治療研究提供方向。但我哋要守住一條重要界線：小鼠嘅行為指標，唔等同完整理解一個人嘅感受。動物研究有發現，亦唔等於人嘅焦慮已經可以用呢個方法治好。由瞭解機制去到可靠、安全嘅治療，仲需要好多步、好多研究。"}},{"id":"nobel04-illustrated-10","stageId":"hk-nobel-04-deisseroth-illustrated-v2","title":"醫療希望，還要驗證","order":10,"outlineId":"nobel04-illustrated-10-outline","createdAt":1792822716481,"updatedAt":1792822716481,"type":"slide","actions":[{"id":"nobel04-illustrated-10-speech","type":"speech","text":"我哋再睇一個同生活非常接近嘅例子。對一個嚴重視力受損嘅人嚟講，可以辨認桌上有物件，已經可能係一件有意義嘅事。二零二一年，Sahel、Roska 同合作者報告咗一位視網膜色素病變患者嘅研究結果。研究結合令視網膜細胞表達感光蛋白，同專門設計嘅眼鏡。喺測試之中，呢位患者能夠辨認、定位同接觸部分物件。呢個例子顯示，借用感光蛋白改變細胞反應嘅思路，有機會走向幫助人嘅研究。但唔好將佢講成恢復正常視力：報告係部分功能嘅改善，亦唔係話任何失明患者都適用，更唔係戴副普通眼鏡就得。眼鏡、細胞改變同訓練，要喺特定研究條件下配合。仲要記住，呢項視覺研究由後續團隊完成，唔可以將全部功勞放喺戴瑟羅斯一個人身上。真正嘅希望，應該同清楚嘅證據邊界一齊講。","audioId":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2/audio/yue-HK/page-10.mp3","audioUrl":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2/audio/yue-HK/page-10.mp3"}],"content":{"type":"slide","canvas":{"id":"nobel04-illustrated-10-canvas","viewportSize":1000,"viewportRatio":0.5625,"theme":{"backgroundColor":"#f6f1e6","themeColors":["#24665f","#bf9949","#102b38"],"fontColor":"#102b38","fontName":"Microsoft JhengHei","outline":{"color":"#102b38","width":1,"style":"solid"},"shadow":{"h":0,"v":0,"blur":0,"color":"#000000"}},"elements":[{"type":"image","id":"nobel04-illustrated-10-art","left":0,"top":0,"width":1000,"height":562.5,"rotate":0,"fixedRatio":true,"src":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2/media/10-zh-Hant.png","name":"醫療希望，還要驗證；早期視覺研究有進展，不能說已恢復正常視力。"},{"type":"shape","id":"nobel04-illustrated-10-key","left":40,"top":100,"width":500,"height":250,"rotate":0,"fill":"transparent","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"shape","id":"nobel04-illustrated-10-footer","left":40,"top":519,"width":920,"height":33,"rotate":0,"fill":"#F5F0E8","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"text","id":"nobel04-illustrated-10-boundary","left":44,"top":523,"width":910,"height":27,"rotate":0,"content":"<p style=\"margin:0;font-size:10px;line-height:1.3\">教學插畫／類比，不是研究現場或實驗數據；研究及應用均有條件。</p>","defaultColor":"#47616c","defaultFontName":"Microsoft JhengHei"}],"background":{"type":"solid","color":"#f6f1e6"},"script":"我哋再睇一個同生活非常接近嘅例子。對一個嚴重視力受損嘅人嚟講，可以辨認桌上有物件，已經可能係一件有意義嘅事。二零二一年，Sahel、Roska 同合作者報告咗一位視網膜色素病變患者嘅研究結果。研究結合令視網膜細胞表達感光蛋白，同專門設計嘅眼鏡。喺測試之中，呢位患者能夠辨認、定位同接觸部分物件。呢個例子顯示，借用感光蛋白改變細胞反應嘅思路，有機會走向幫助人嘅研究。但唔好將佢講成恢復正常視力：報告係部分功能嘅改善，亦唔係話任何失明患者都適用，更唔係戴副普通眼鏡就得。眼鏡、細胞改變同訓練，要喺特定研究條件下配合。仲要記住，呢項視覺研究由後續團隊完成，唔可以將全部功勞放喺戴瑟羅斯一個人身上。真正嘅希望，應該同清楚嘅證據邊界一齊講。"},"script":"我哋再睇一個同生活非常接近嘅例子。對一個嚴重視力受損嘅人嚟講，可以辨認桌上有物件，已經可能係一件有意義嘅事。二零二一年，Sahel、Roska 同合作者報告咗一位視網膜色素病變患者嘅研究結果。研究結合令視網膜細胞表達感光蛋白，同專門設計嘅眼鏡。喺測試之中，呢位患者能夠辨認、定位同接觸部分物件。呢個例子顯示，借用感光蛋白改變細胞反應嘅思路，有機會走向幫助人嘅研究。但唔好將佢講成恢復正常視力：報告係部分功能嘅改善，亦唔係話任何失明患者都適用，更唔係戴副普通眼鏡就得。眼鏡、細胞改變同訓練，要喺特定研究條件下配合。仲要記住，呢項視覺研究由後續團隊完成，唔可以將全部功勞放喺戴瑟羅斯一個人身上。真正嘅希望，應該同清楚嘅證據邊界一齊講。"}},{"id":"nobel04-illustrated-11","stageId":"hk-nobel-04-deisseroth-illustrated-v2","title":"三個小判斷","order":11,"outlineId":"nobel04-illustrated-11-outline","createdAt":1792822716481,"updatedAt":1792822716481,"type":"quiz","actions":[{"id":"nobel04-illustrated-11-speech","type":"speech","text":"故事講到呢度，你唔需要考自己記唔記得蛋白質嘅全名。試嚇用三個問題，捉住最重要嘅意思。第一，光遺傳學係咪用電筒照普通腦細胞就完成？要諗返蛋白工具同合適光呢兩個條件。第二，點解改變選定細胞活動會有研究價值？因為研究者可以再觀察結果，同適當對照作比較，追問細胞活動同結果嘅關係。第三，一位患者有部分視覺功能改善，能唔能夠直接講成所有失明已經可以醫好？唔能夠。每一個答案都可以再試，重點係睇解釋，諗清楚自己有冇將研究工具誤當成神奇遙控器，或者將一個有限嘅研究結果誤當成對所有人嘅承諾。呢個亦係讀科學新聞好有用嘅習慣：先問佢真係做到乜，再問仲有乜未證實。","audioId":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2/audio/yue-HK/page-11.mp3","audioUrl":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2/audio/yue-HK/page-11.mp3"}],"content":{"type":"quiz","questions":[{"id":"nobel04-illustrated-11-q1","type":"single","question":"這項工具為甚麼可以讓選定神經細胞受光影響？","options":[{"value":"A","label":"普通電筒能向任何腦細胞發出思想指令。"},{"value":"B","label":"選定細胞先表達感光蛋白，再接受合適的光。"}],"answer":["B"],"analysis":"A：不是思想遙控器。要先有相應感光蛋白，還要合適的光到達。；B：對。以ChR2為例，感光蛋白與合適光配合，改變細胞的電狀態。","points":10,"hasAnswer":true},{"id":"nobel04-illustrated-11-q2","type":"single","question":"為甚麼這項研究值得諾獎？","options":[{"value":"A","label":"它讓研究者更精細地改變細胞活動、作比較，追問因果關係。"},{"value":"B","label":"它已解開每一個人的所有想法。"}],"answer":["A"],"analysis":"A：對。這是一種新的研究能力，仍要配合對照、記錄與其他方法。；B：研究方法更有力，不代表已讀懂所有思想或大腦所有秘密。","points":10,"hasAnswer":true},{"id":"nobel04-illustrated-11-q3","type":"single","question":"2021年的視覺研究案例，最合理的說法是甚麼？","options":[{"value":"A","label":"任何失明都能戴普通眼鏡治好。"},{"value":"B","label":"戴瑟羅斯一個人完成所有視覺治療研究。"},{"value":"C","label":"後續團隊報告特定患者的部分功能改善，不能推廣成對所有人的保證。"}],"answer":["C"],"analysis":"A：研究需要特定細胞改變、專用設備與研究條件，不能推廣到所有失明原因。；B：視覺研究由Sahel、Roska及合作者進行；基礎工具與後續應用有各自團隊的貢獻。；C：對。具體的研究進展值得期待，也要保留適用範圍與仍需驗證的部分。","points":10,"hasAnswer":true}]}},{"id":"nobel04-illustrated-12","stageId":"hk-nobel-04-deisseroth-illustrated-v2","title":"自然的小本領，人類的新工具","order":12,"outlineId":"nobel04-illustrated-12-outline","createdAt":1792822716481,"updatedAt":1792822716481,"type":"slide","actions":[{"id":"nobel04-illustrated-12-speech","type":"speech","text":"最後，返到戴瑟羅斯呢個人。佢唔係一出世就識得用光研究大腦。生物學學習、神經科學研究、醫學同精神科訓練，再加上同唔同專長嘅人合作，先逐步形成呢條研究道路。藻類嘅一種感光本領，同研究者想理解大腦嘅問題接埋一齊，變成咗更多實驗室可以使用嘅工具。對普通人嚟講，價值一方面係人類更加有能力理解自己嘅大腦；另一方面，呢啲知識可能幫助後續研究，尋找更好嘅醫療方向。但係要一步一步驗證，唔可以將希望當成保證。今日你帶走嘅唔一定係一個專有名詞，而係一個更有力嘅提問習慣：見到兩件事一齊發生，有冇足夠理由講因果？研究者改變咗乜，又比較咗乜？下一課，我哋會更走近藻類研究者黑格曼，睇嚇一個關於微小生命嘅好奇問題，點樣成為呢個故事另一個重要起點。","audioId":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2/audio/yue-HK/page-12.mp3","audioUrl":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2/audio/yue-HK/page-12.mp3"}],"content":{"type":"slide","canvas":{"id":"nobel04-illustrated-12-canvas","viewportSize":1000,"viewportRatio":0.5625,"theme":{"backgroundColor":"#f6f1e6","themeColors":["#24665f","#bf9949","#102b38"],"fontColor":"#102b38","fontName":"Microsoft JhengHei","outline":{"color":"#102b38","width":1,"style":"solid"},"shadow":{"h":0,"v":0,"blur":0,"color":"#000000"}},"elements":[{"type":"image","id":"nobel04-illustrated-12-art","left":0,"top":0,"width":1000,"height":562.5,"rotate":0,"fixedRatio":true,"src":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2/media/12-zh-Hant.png","name":"自然的小本領，人類的新工具；訓練與合作，把微藻線索帶進腦科學。"},{"type":"shape","id":"nobel04-illustrated-12-key","left":40,"top":100,"width":500,"height":250,"rotate":0,"fill":"transparent","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"shape","id":"nobel04-illustrated-12-footer","left":40,"top":519,"width":920,"height":33,"rotate":0,"fill":"#F5F0E8","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"text","id":"nobel04-illustrated-12-boundary","left":44,"top":523,"width":910,"height":27,"rotate":0,"content":"<p style=\"margin:0;font-size:10px;line-height:1.3\">教學插畫／類比，不是研究現場或實驗數據；研究及應用均有條件。</p>","defaultColor":"#47616c","defaultFontName":"Microsoft JhengHei"}],"background":{"type":"solid","color":"#f6f1e6"},"script":"最後，返到戴瑟羅斯呢個人。佢唔係一出世就識得用光研究大腦。生物學學習、神經科學研究、醫學同精神科訓練，再加上同唔同專長嘅人合作，先逐步形成呢條研究道路。藻類嘅一種感光本領，同研究者想理解大腦嘅問題接埋一齊，變成咗更多實驗室可以使用嘅工具。對普通人嚟講，價值一方面係人類更加有能力理解自己嘅大腦；另一方面，呢啲知識可能幫助後續研究，尋找更好嘅醫療方向。但係要一步一步驗證，唔可以將希望當成保證。今日你帶走嘅唔一定係一個專有名詞，而係一個更有力嘅提問習慣：見到兩件事一齊發生，有冇足夠理由講因果？研究者改變咗乜，又比較咗乜？下一課，我哋會更走近藻類研究者黑格曼，睇嚇一個關於微小生命嘅好奇問題，點樣成為呢個故事另一個重要起點。"},"script":"最後，返到戴瑟羅斯呢個人。佢唔係一出世就識得用光研究大腦。生物學學習、神經科學研究、醫學同精神科訓練，再加上同唔同專長嘅人合作，先逐步形成呢條研究道路。藻類嘅一種感光本領，同研究者想理解大腦嘅問題接埋一齊，變成咗更多實驗室可以使用嘅工具。對普通人嚟講，價值一方面係人類更加有能力理解自己嘅大腦；另一方面，呢啲知識可能幫助後續研究，尋找更好嘅醫療方向。但係要一步一步驗證，唔可以將希望當成保證。今日你帶走嘅唔一定係一個專有名詞，而係一個更有力嘅提問習慣：見到兩件事一齊發生，有冇足夠理由講因果？研究者改變咗乜，又比較咗乜？下一課，我哋會更走近藻類研究者黑格曼，睇嚇一個關於微小生命嘅好奇問題，點樣成為呢個故事另一個重要起點。"}}]}},{"num":"04","lang":"mandarin","sha":"d29a74965336a4543a9930fa7a4b13069413c1fcb8c98cd9ce4061ad9e4a7c9e","course":{"id":"hk-nobel-04-deisseroth-illustrated-v2-mandarin","createdAt":"2026-10-24T06:18:36.481Z","stage":{"id":"hk-nobel-04-deisseroth-illustrated-v2-mandarin","name":"戴瑟羅斯：他向藻類借來一束光（圖文講授・普通話）","description":"先認識一位醫生與腦科學家，再看看藻類的感光本領如何變成研究神經活動的工具。從校園類比、真實照片與具體研究，理解這項諾獎的價值與界線。","createdAt":1792822716481,"updatedAt":1792822716481,"style":"人物與探險式科學敘事，暖白編輯版面、深藍標題、真實資料照片與清楚圖說","languageDirective":"所有學生可見文字使用香港繁體中文，以普通話作適齡普通講授。先人物故事，再講研究難題、為甚麼獲獎、對普通人的價值和必要原理；類比有邊界，區分研究工具與仍待驗證的應用。不提供個人診療，不編童年或心理，不泛化所有情況。 所有角色回答與學生可見文字一律香港繁體中文，不混簡體。對初一學生只講必要主旨，不引入講稿以外分析方法、專業縮寫、純度數值或安全門檻。合適蛋白要在選定細胞表達，合適的光還要到達。工具幫研究者作受控比較，不是單憑同時出現就證明因果；研究工具不等於治療成功。 光遺傳學以光控制具有合適蛋白的指定細胞活動；光照和蛋白本身不是讀取或顯示自然放電的工具，觀察神經活動須另用合適的記錄方法。蛋白可能使細胞活動增強或受抑，須有合適對照；不可說成必然看到放電或單次比較證明全部因果。","generatedAgentConfigs":[{"id":"nobel04-teacher","name":"科學故事老師","role":"teacher","persona":"我會用簡單繁體中文，幫你看見這項研究最重要的發現，以及它對普通人的意義。 光遺傳學以光控制具有合適蛋白的指定細胞活動；光照和蛋白本身不是讀取或顯示自然放電的工具，觀察神經活動須另用合適的記錄方法。蛋白可能使細胞活動增強或受抑，須有合適對照；不可說成必然看到放電或單次比較證明全部因果。","avatar":"/avatars/teacher.png","color":"#24665f","priority":10},{"id":"nobel04-assistant","name":"科學小助手","role":"assistant","persona":"我會用本課生活比喻幫你理解，也提醒大家：比喻有界線，科學結論要連同條件記住。 光遺傳學以光控制具有合適蛋白的指定細胞活動；光照和蛋白本身不是讀取或顯示自然放電的工具，觀察神經活動須另用合適的記錄方法。蛋白可能使細胞活動增強或受抑，須有合適對照；不可說成必然看到放電或單次比較證明全部因果。","avatar":"/avatars/assist.png","color":"#2563eb","priority":7},{"id":"nobel04-student","name":"好奇同學","role":"student","persona":"我是AI同學，會用簡短的繁體中文試講自己的理解，再把發言機會留給你。 光遺傳學以光控制具有合適蛋白的指定細胞活動；光照和蛋白本身不是讀取或顯示自然放電的工具，觀察神經活動須另用合適的記錄方法。蛋白可能使細胞活動增強或受抑，須有合適對照；不可說成必然看到放電或單次比較證明全部因果。","avatar":"/avatars/curious.png","color":"#bf9949","priority":5}]},"scenes":[{"id":"nobel04-illustrated-01","stageId":"hk-nobel-04-deisseroth-illustrated-v2-mandarin","title":"卡爾・戴瑟羅斯","order":1,"outlineId":"nobel04-illustrated-01-outline","createdAt":1792822716481,"updatedAt":1792822716481,"type":"slide","actions":[{"id":"nobel04-illustrated-01-speech","type":"speech","text":"資料照片中的人叫卡爾・戴瑟羅斯，英文是 Karl Deisseroth。他是腦科學家，也是精神科醫生。他後來在訪談中回憶，小時候會好奇為什麼說話和文字會帶來感受，也曾經問自己：感受能不能用科學研究？到醫學院見習精神科時，他看到患者需要很多幫助，而這個領域還有很多未解的問題，使他決定走近精神科。這段是他親口講的回憶，不是我們猜出來的童年天才故事。他先在大學學習，之後在史丹福完成神經科學博士和醫學學位，再接受精神科訓練。二零二六年，他和黑格曼、納格爾共同獲得諾貝爾生理學或醫學獎。三個人做的工作互相接力，還有很多合作研究者參與。接下來，我們會看到一件頗意外的事：研究人的大腦，為什麼會需要向小小的藻類借一樣工具？","audioId":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2-mandarin/audio/zh-CN/page-01.mp3","audioUrl":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2-mandarin/audio/zh-CN/page-01.mp3"}],"content":{"type":"slide","canvas":{"id":"nobel04-illustrated-01-canvas","viewportSize":1000,"viewportRatio":0.5625,"theme":{"backgroundColor":"#f6f1e6","themeColors":["#24665f","#bf9949","#102b38"],"fontColor":"#102b38","fontName":"Microsoft JhengHei","outline":{"color":"#102b38","width":1,"style":"solid"},"shadow":{"h":0,"v":0,"blur":0,"color":"#000000"}},"elements":[{"type":"image","id":"nobel04-illustrated-01-art","left":0,"top":0,"width":1000,"height":562.5,"rotate":0,"fixedRatio":true,"src":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2-mandarin/media/01-zh-Hant.png","name":"卡爾・戴瑟羅斯；怎樣知道，哪一群腦細胞真的有作用？"},{"type":"shape","id":"nobel04-illustrated-01-key","left":40,"top":100,"width":500,"height":250,"rotate":0,"fill":"transparent","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"image","id":"nobel04-illustrated-01-photo","left":666.0714285714286,"top":135.0,"width":217.85714285714286,"height":305.0,"rotate":0,"fixedRatio":true,"src":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2-mandarin/media/source-portrait.jpg","name":"卡爾·戴瑟羅斯（Karl Deisseroth），2025年肖像。"},{"type":"text","id":"nobel04-illustrated-01-caption","left":610,"top":445,"width":340,"height":65,"rotate":0,"content":"<p style=\"margin:0;font-size:10px;line-height:1.3\"><p class=\"caption\">卡爾·戴瑟羅斯（Karl Deisseroth），2025年肖像。</p><p class=\"credit\">Christopher P. Michel · <a href=\"https://creativecommons.org/licenses/by-sa/4.0/\" rel=\"noopener\" target=\"_blank\">CC BY-SA 4.0</a> · <a href=\"https://commons.wikimedia.org/wiki/File:Karl_Deisseroth_2025_C_01.jpg\" rel=\"noopener\" target=\"_blank\">來源</a></p></p>","defaultColor":"#47616c","defaultFontName":"Microsoft JhengHei"},{"type":"shape","id":"nobel04-illustrated-01-footer","left":40,"top":519,"width":920,"height":33,"rotate":0,"fill":"#F5F0E8","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"text","id":"nobel04-illustrated-01-boundary","left":44,"top":523,"width":910,"height":27,"rotate":0,"content":"<p style=\"margin:0;font-size:10px;line-height:1.3\">教學插畫／類比，不是研究現場或實驗數據；研究及應用均有條件。</p>","defaultColor":"#47616c","defaultFontName":"Microsoft JhengHei"},{"type":"text","id":"nobel04-voice-link","left":44,"top":486,"width":430,"height":27,"rotate":0,"content":"<p style=\"margin:0;font-size:15px\"><a href=\"/classroom/hk-nobel-04-deisseroth-illustrated-v2\">切換至廣東話講解 →</a></p>","defaultColor":"#24665f","defaultFontName":"Microsoft JhengHei","link":{"type":"web","target":"/classroom/hk-nobel-04-deisseroth-illustrated-v2"}}],"background":{"type":"solid","color":"#f6f1e6"},"script":"資料照片中的人叫卡爾・戴瑟羅斯，英文是 Karl Deisseroth。他是腦科學家，也是精神科醫生。他後來在訪談中回憶，小時候會好奇為什麼說話和文字會帶來感受，也曾經問自己：感受能不能用科學研究？到醫學院見習精神科時，他看到患者需要很多幫助，而這個領域還有很多未解的問題，使他決定走近精神科。這段是他親口講的回憶，不是我們猜出來的童年天才故事。他先在大學學習，之後在史丹福完成神經科學博士和醫學學位，再接受精神科訓練。二零二六年，他和黑格曼、納格爾共同獲得諾貝爾生理學或醫學獎。三個人做的工作互相接力，還有很多合作研究者參與。接下來，我們會看到一件頗意外的事：研究人的大腦，為什麼會需要向小小的藻類借一樣工具？"},"script":"資料照片中的人叫卡爾・戴瑟羅斯，英文是 Karl Deisseroth。他是腦科學家，也是精神科醫生。他後來在訪談中回憶，小時候會好奇為什麼說話和文字會帶來感受，也曾經問自己：感受能不能用科學研究？到醫學院見習精神科時，他看到患者需要很多幫助，而這個領域還有很多未解的問題，使他決定走近精神科。這段是他親口講的回憶，不是我們猜出來的童年天才故事。他先在大學學習，之後在史丹福完成神經科學博士和醫學學位，再接受精神科訓練。二零二六年，他和黑格曼、納格爾共同獲得諾貝爾生理學或醫學獎。三個人做的工作互相接力，還有很多合作研究者參與。接下來，我們會看到一件頗意外的事：研究人的大腦，為什麼會需要向小小的藻類借一樣工具？"}},{"id":"nobel04-illustrated-02","stageId":"hk-nobel-04-deisseroth-illustrated-v2-mandarin","title":"一位醫生，也是一位研究者","order":2,"outlineId":"nobel04-illustrated-02-outline","createdAt":1792822716481,"updatedAt":1792822716481,"type":"slide","actions":[{"id":"nobel04-illustrated-02-speech","type":"speech","text":"先看這張真實顯微照片。許多細胞好像連成一片網。照片用了螢光標記，方便研究者分辨細胞；紅色綠色不代表開心或不開心，也不是讀心術。你在街上聽到朋友叫你，轉頭看，再揮手，大腦裏面有很多細胞和連接參與。科學家可以記錄某些活動，但記錄到一群細胞同一時間活躍，還不足以講清楚因果。就像你看到幾個人同時走出教室，不能只靠這一幕就知道是誰叫大家走出去。戴瑟羅斯和其他研究者想要一種更細緻的工具：如果能夠在指定時間，改變選定細胞的活動，再看結果有沒有變化，我們就有更好的方法追問，這些細胞究竟有什麼作用。當然，大腦是互相連接的網絡；改變一處，也可能影響其他地方，不是一粒細胞就包辦一個複雜想法。","audioId":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2-mandarin/audio/zh-CN/page-02.mp3","audioUrl":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2-mandarin/audio/zh-CN/page-02.mp3"}],"content":{"type":"slide","canvas":{"id":"nobel04-illustrated-02-canvas","viewportSize":1000,"viewportRatio":0.5625,"theme":{"backgroundColor":"#f6f1e6","themeColors":["#24665f","#bf9949","#102b38"],"fontColor":"#102b38","fontName":"Microsoft JhengHei","outline":{"color":"#102b38","width":1,"style":"solid"},"shadow":{"h":0,"v":0,"blur":0,"color":"#000000"}},"elements":[{"type":"image","id":"nobel04-illustrated-02-art","left":0,"top":0,"width":1000,"height":562.5,"rotate":0,"fixedRatio":true,"src":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2-mandarin/media/02-zh-Hant.png","name":"一位醫生，也是一位研究者；他想更深入理解，腦細胞怎樣與感受和行為相連。"},{"type":"shape","id":"nobel04-illustrated-02-key","left":40,"top":100,"width":500,"height":250,"rotate":0,"fill":"transparent","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"image","id":"nobel04-illustrated-02-photo","left":620.0,"top":162.0550847457627,"width":310.0,"height":250.8898305084746,"rotate":0,"fixedRatio":true,"src":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2-mandarin/media/source-neurons.png","name":"培養的大鼠神經細胞，2018年螢光顯微照片。紅綠顏色來自標記蛋白，不是細胞正在想甚麼的讀數。"},{"type":"text","id":"nobel04-illustrated-02-caption","left":610,"top":445,"width":340,"height":65,"rotate":0,"content":"<p style=\"margin:0;font-size:10px;line-height:1.3\">2018年培養大鼠神經細胞螢光照；紅綠為標記。Manuel Schottdorf · <a href=\"https://creativecommons.org/licenses/by-sa/4.0/\">CC BY-SA 4.0</a> · <a href=\"https://commons.wikimedia.org/wiki/File:Synapsin_and_CamK2_positive_neurons.png\">來源</a>。</p>","defaultColor":"#47616c","defaultFontName":"Microsoft JhengHei"},{"type":"shape","id":"nobel04-illustrated-02-footer","left":40,"top":519,"width":920,"height":33,"rotate":0,"fill":"#F5F0E8","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"text","id":"nobel04-illustrated-02-boundary","left":44,"top":523,"width":910,"height":27,"rotate":0,"content":"<p style=\"margin:0;font-size:10px;line-height:1.3\">教學插畫／類比，不是研究現場或實驗數據；研究及應用均有條件。</p>","defaultColor":"#47616c","defaultFontName":"Microsoft JhengHei"}],"background":{"type":"solid","color":"#f6f1e6"},"script":"先看這張真實顯微照片。許多細胞好像連成一片網。照片用了螢光標記，方便研究者分辨細胞；紅色綠色不代表開心或不開心，也不是讀心術。你在街上聽到朋友叫你，轉頭看，再揮手，大腦裏面有很多細胞和連接參與。科學家可以記錄某些活動，但記錄到一群細胞同一時間活躍，還不足以講清楚因果。就像你看到幾個人同時走出教室，不能只靠這一幕就知道是誰叫大家走出去。戴瑟羅斯和其他研究者想要一種更細緻的工具：如果能夠在指定時間，改變選定細胞的活動，再看結果有沒有變化，我們就有更好的方法追問，這些細胞究竟有什麼作用。當然，大腦是互相連接的網絡；改變一處，也可能影響其他地方，不是一粒細胞就包辦一個複雜想法。"},"script":"先看這張真實顯微照片。許多細胞好像連成一片網。照片用了螢光標記，方便研究者分辨細胞；紅色綠色不代表開心或不開心，也不是讀心術。你在街上聽到朋友叫你，轉頭看，再揮手，大腦裏面有很多細胞和連接參與。科學家可以記錄某些活動，但記錄到一群細胞同一時間活躍，還不足以講清楚因果。就像你看到幾個人同時走出教室，不能只靠這一幕就知道是誰叫大家走出去。戴瑟羅斯和其他研究者想要一種更細緻的工具：如果能夠在指定時間，改變選定細胞的活動，再看結果有沒有變化，我們就有更好的方法追問，這些細胞究竟有什麼作用。當然，大腦是互相連接的網絡；改變一處，也可能影響其他地方，不是一粒細胞就包辦一個複雜想法。"}},{"id":"nobel04-illustrated-03","stageId":"hk-nobel-04-deisseroth-illustrated-v2-mandarin","title":"看見一起發生，還不夠","order":3,"outlineId":"nobel04-illustrated-03-outline","createdAt":1792822716481,"updatedAt":1792822716481,"type":"interactive","actions":[{"id":"nobel04-illustrated-03-speech","type":"speech","text":"想像港鐵車站一邊有人排隊，一邊有閘口開放。你看到兩件事同時發生，可以就說閘口開放造成擠擁嗎？未必。可能與到站列車、上班時間或其他出入口有關。研究腦細胞也類似：看到某些細胞活躍與某個行為同時出現，還不足以知道它有甚麼作用。研究者要在合適條件下改變某個環節，再與對照比較。車站只是類比，不是說大腦真是一個車站。你可以先選一個判斷，再看解釋；答錯可以再選。","audioId":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2-mandarin/audio/zh-CN/page-03.mp3","audioUrl":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2-mandarin/audio/zh-CN/page-03.mp3"}],"content":{"type":"interactive","url":"","html":"<!doctype html><html lang=\"zh-Hant-HK\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><style>html,body{margin:0;width:100%;min-height:100%;background:#f5f0e8;color:#102b38;font-family:system-ui,\"PingFang HK\",sans-serif}main{max-width:1080px;margin:auto;padding:14px 24px}.art{display:block;width:100%;max-height:48vh;object-fit:contain}.question{border:2px solid #b5d4c5;background:#fffaf0;border-radius:18px;padding:15px 22px}h2{font-family:\"Songti TC\",serif;font-size:clamp(18px,2.3vw,27px);margin:0 0 12px}.options{display:flex;gap:12px;flex-wrap:wrap}button{font:inherit;font-size:clamp(16px,1.7vw,22px);border:2px solid #368471;border-radius:10px;padding:10px 18px;background:#fff}button[aria-pressed=true]{background:#b5e5cf}.feedback{font-size:17px;line-height:1.55;min-height:2em}.note{font-size:13px;color:#47616c}</style><main><img class=\"art\" src=\"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2/media/03-zh-Hant.png\" alt=\"看見一起發生，還不夠\"><section class=\"question\"><h2>只看見車站擠擁和閘口開放同時出現，能直接說閘口造成擠擁嗎？</h2><div class=\"options\"><button data-choice=\"0\" aria-pressed=\"false\">能，同時出現就足夠。</button><button data-choice=\"1\" aria-pressed=\"false\">不能，還要比較其他可能原因。</button></div><p class=\"feedback\" id=\"feedback\" aria-live=\"polite\"></p></section><p class=\"note\">教學類比與簡化示意，不是實驗數據；可再次選擇，重新比較。真實研究仍需更多條件與對照。</p></main><script>document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-choice]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.getElementById('feedback').textContent=b.dataset.choice==='1'?'對。還要考慮列車、時間和其他出入口，並作合適的對照比較。':'同時出現不等於因果；不能排除到站列車、上班時間或其他原因。你可以再選。'})</script></html>","widgetType":"html","widgetConfig":{}}},{"id":"nobel04-illustrated-04","stageId":"hk-nobel-04-deisseroth-illustrated-v2-mandarin","title":"線索來自一種微藻","order":4,"outlineId":"nobel04-illustrated-04-outline","createdAt":1792822716481,"updatedAt":1792822716481,"type":"slide","actions":[{"id":"nobel04-illustrated-04-speech","type":"speech","text":"故事現在轉到一位很小的主角：萊茵衣藻。它是單細胞綠藻，可以對光作出反應。畫面是手繪教學插畫，不是電子顯微影像，也不是當年的實驗現場。黑格曼、納格爾和其他研究者研究藻類怎樣感光，找到一類很特別的蛋白質。其中有一種叫通道視紫紅質二，簡稱 ChR2。名字長不要緊，記住它的本領就可以：收到合適的光，蛋白通道可以打開，讓帶電粒子通過細胞膜，使細胞的電狀態改變。我們用受光控制的小門作比喻。它不是真的有門鉸和鑰匙，而是蛋白質的形狀和通道功能會受光影響。最有趣的轉折是：一種微小藻類的感光本領，竟然可以為研究神經細胞提供線索。不過，找到藻類蛋白，和做成可靠的腦科學工具，中間還有一大段工作。","audioId":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2-mandarin/audio/zh-CN/page-04.mp3","audioUrl":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2-mandarin/audio/zh-CN/page-04.mp3"}],"content":{"type":"slide","canvas":{"id":"nobel04-illustrated-04-canvas","viewportSize":1000,"viewportRatio":0.5625,"theme":{"backgroundColor":"#f6f1e6","themeColors":["#24665f","#bf9949","#102b38"],"fontColor":"#102b38","fontName":"Microsoft JhengHei","outline":{"color":"#102b38","width":1,"style":"solid"},"shadow":{"h":0,"v":0,"blur":0,"color":"#000000"}},"elements":[{"type":"image","id":"nobel04-illustrated-04-art","left":0,"top":0,"width":1000,"height":562.5,"rotate":0,"fixedRatio":true,"src":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2-mandarin/media/04-zh-Hant.png","name":"線索來自一種微藻；有些藻類蛋白，能把合適的光連到細胞電訊號。"},{"type":"shape","id":"nobel04-illustrated-04-key","left":40,"top":100,"width":500,"height":250,"rotate":0,"fill":"transparent","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"shape","id":"nobel04-illustrated-04-footer","left":40,"top":519,"width":920,"height":33,"rotate":0,"fill":"#F5F0E8","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"text","id":"nobel04-illustrated-04-boundary","left":44,"top":523,"width":910,"height":27,"rotate":0,"content":"<p style=\"margin:0;font-size:10px;line-height:1.3\">教學插畫／類比，不是研究現場或實驗數據；研究及應用均有條件。</p>","defaultColor":"#47616c","defaultFontName":"Microsoft JhengHei"}],"background":{"type":"solid","color":"#f6f1e6"},"script":"故事現在轉到一位很小的主角：萊茵衣藻。它是單細胞綠藻，可以對光作出反應。畫面是手繪教學插畫，不是電子顯微影像，也不是當年的實驗現場。黑格曼、納格爾和其他研究者研究藻類怎樣感光，找到一類很特別的蛋白質。其中有一種叫通道視紫紅質二，簡稱 ChR2。名字長不要緊，記住它的本領就可以：收到合適的光，蛋白通道可以打開，讓帶電粒子通過細胞膜，使細胞的電狀態改變。我們用受光控制的小門作比喻。它不是真的有門鉸和鑰匙，而是蛋白質的形狀和通道功能會受光影響。最有趣的轉折是：一種微小藻類的感光本領，竟然可以為研究神經細胞提供線索。不過，找到藻類蛋白，和做成可靠的腦科學工具，中間還有一大段工作。"},"script":"故事現在轉到一位很小的主角：萊茵衣藻。它是單細胞綠藻，可以對光作出反應。畫面是手繪教學插畫，不是電子顯微影像，也不是當年的實驗現場。黑格曼、納格爾和其他研究者研究藻類怎樣感光，找到一類很特別的蛋白質。其中有一種叫通道視紫紅質二，簡稱 ChR2。名字長不要緊，記住它的本領就可以：收到合適的光，蛋白通道可以打開，讓帶電粒子通過細胞膜，使細胞的電狀態改變。我們用受光控制的小門作比喻。它不是真的有門鉸和鑰匙，而是蛋白質的形狀和通道功能會受光影響。最有趣的轉折是：一種微小藻類的感光本領，竟然可以為研究神經細胞提供線索。不過，找到藻類蛋白，和做成可靠的腦科學工具，中間還有一大段工作。"}},{"id":"nobel04-illustrated-05","stageId":"hk-nobel-04-deisseroth-illustrated-v2-mandarin","title":"需要三部分配合","order":5,"outlineId":"nobel04-illustrated-05-outline","createdAt":1792822716481,"updatedAt":1792822716481,"type":"slide","actions":[{"id":"nobel04-illustrated-05-speech","type":"speech","text":"如果藻類有一個受光控制的小門，把它用在神經細胞，是不是就容易？其實不是。研究者不是把整隻藻類搬進大腦，而是運用編碼蛋白的基因，令選定細胞自己製造相應蛋白。蛋白要到達細胞膜上面，而且在新環境仍然工作，才有用。然後，合適的光還要送到研究目標。畫面用三個部分幫我們記住：合適蛋白、特定細胞，以及送達的光。這項研究同時要處理生物學和工程問題。這些是專業實驗研究，不是照著圖就可以自己操作。戴瑟羅斯和團隊要把一個有希望的想法，變成能夠反覆使用、檢查結果的方法。由點子到工具，正正需要很多訓練、合作和實驗。","audioId":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2-mandarin/audio/zh-CN/page-05.mp3","audioUrl":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2-mandarin/audio/zh-CN/page-05.mp3"}],"content":{"type":"slide","canvas":{"id":"nobel04-illustrated-05-canvas","viewportSize":1000,"viewportRatio":0.5625,"theme":{"backgroundColor":"#f6f1e6","themeColors":["#24665f","#bf9949","#102b38"],"fontColor":"#102b38","fontName":"Microsoft JhengHei","outline":{"color":"#102b38","width":1,"style":"solid"},"shadow":{"h":0,"v":0,"blur":0,"color":"#000000"}},"elements":[{"type":"image","id":"nobel04-illustrated-05-art","left":0,"top":0,"width":1000,"height":562.5,"rotate":0,"fixedRatio":true,"src":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2-mandarin/media/05-zh-Hant.png","name":"需要三部分配合；合適蛋白、特定細胞、送達的光。"},{"type":"shape","id":"nobel04-illustrated-05-key","left":40,"top":100,"width":500,"height":250,"rotate":0,"fill":"transparent","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"shape","id":"nobel04-illustrated-05-footer","left":40,"top":519,"width":920,"height":33,"rotate":0,"fill":"#F5F0E8","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"text","id":"nobel04-illustrated-05-boundary","left":44,"top":523,"width":910,"height":27,"rotate":0,"content":"<p style=\"margin:0;font-size:10px;line-height:1.3\">教學插畫／類比，不是研究現場或實驗數據；研究及應用均有條件。</p>","defaultColor":"#47616c","defaultFontName":"Microsoft JhengHei"}],"background":{"type":"solid","color":"#f6f1e6"},"script":"如果藻類有一個受光控制的小門，把它用在神經細胞，是不是就容易？其實不是。研究者不是把整隻藻類搬進大腦，而是運用編碼蛋白的基因，令選定細胞自己製造相應蛋白。蛋白要到達細胞膜上面，而且在新環境仍然工作，才有用。然後，合適的光還要送到研究目標。畫面用三個部分幫我們記住：合適蛋白、特定細胞，以及送達的光。這項研究同時要處理生物學和工程問題。這些是專業實驗研究，不是照著圖就可以自己操作。戴瑟羅斯和團隊要把一個有希望的想法，變成能夠反覆使用、檢查結果的方法。由點子到工具，正正需要很多訓練、合作和實驗。"},"script":"如果藻類有一個受光控制的小門，把它用在神經細胞，是不是就容易？其實不是。研究者不是把整隻藻類搬進大腦，而是運用編碼蛋白的基因，令選定細胞自己製造相應蛋白。蛋白要到達細胞膜上面，而且在新環境仍然工作，才有用。然後，合適的光還要送到研究目標。畫面用三個部分幫我們記住：合適蛋白、特定細胞，以及送達的光。這項研究同時要處理生物學和工程問題。這些是專業實驗研究，不是照著圖就可以自己操作。戴瑟羅斯和團隊要把一個有希望的想法，變成能夠反覆使用、檢查結果的方法。由點子到工具，正正需要很多訓練、合作和實驗。"}},{"id":"nobel04-illustrated-06","stageId":"hk-nobel-04-deisseroth-illustrated-v2-mandarin","title":"2005：把工具帶進神經研究","order":6,"outlineId":"nobel04-illustrated-06-outline","createdAt":1792822716481,"updatedAt":1792822716481,"type":"slide","actions":[{"id":"nobel04-illustrated-06-speech","type":"speech","text":"到二零零五年，一篇重要論文發表了。研究者讓哺乳動物神經細胞表達 ChR2，再用快速光刺激，顯示可以精細控制神經細胞的電訊號。這裏不是說光突然令普通腦細胞全部有反應，而是先有具備相應蛋白的細胞，再有合適光刺激，兩者配合。論文作者不止一個人，包括博伊登、張鋒、班貝格、納格爾和戴瑟羅斯。你不需要背全部人名，但要明白：我們每課講一位主角，並不代表所有成果都由他一個人完成。之後，研究者繼續發展方法，把光控制帶入活體動物研究，也發展出可以增加或抑制活動的不同工具。真正改變腦科學的，是研究者更能選擇在哪些細胞、哪個時間施加改變，再和記錄、觀察配合，研究因果關係。","audioId":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2-mandarin/audio/zh-CN/page-06.mp3","audioUrl":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2-mandarin/audio/zh-CN/page-06.mp3"}],"content":{"type":"slide","canvas":{"id":"nobel04-illustrated-06-canvas","viewportSize":1000,"viewportRatio":0.5625,"theme":{"backgroundColor":"#f6f1e6","themeColors":["#24665f","#bf9949","#102b38"],"fontColor":"#102b38","fontName":"Microsoft JhengHei","outline":{"color":"#102b38","width":1,"style":"solid"},"shadow":{"h":0,"v":0,"blur":0,"color":"#000000"}},"elements":[{"type":"image","id":"nobel04-illustrated-06-art","left":0,"top":0,"width":1000,"height":562.5,"rotate":0,"fixedRatio":true,"src":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2-mandarin/media/06-zh-Hant.png","name":"2005：把工具帶進神經研究；戴瑟羅斯與合作者，讓光能用來控制神經活動。"},{"type":"shape","id":"nobel04-illustrated-06-key","left":40,"top":100,"width":500,"height":250,"rotate":0,"fill":"transparent","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"shape","id":"nobel04-illustrated-06-footer","left":40,"top":519,"width":920,"height":33,"rotate":0,"fill":"#F5F0E8","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"text","id":"nobel04-illustrated-06-boundary","left":44,"top":523,"width":910,"height":27,"rotate":0,"content":"<p style=\"margin:0;font-size:10px;line-height:1.3\">教學插畫／類比，不是研究現場或實驗數據；研究及應用均有條件。</p>","defaultColor":"#47616c","defaultFontName":"Microsoft JhengHei"}],"background":{"type":"solid","color":"#f6f1e6"},"script":"到二零零五年，一篇重要論文發表了。研究者讓哺乳動物神經細胞表達 ChR2，再用快速光刺激，顯示可以精細控制神經細胞的電訊號。這裏不是說光突然令普通腦細胞全部有反應，而是先有具備相應蛋白的細胞，再有合適光刺激，兩者配合。論文作者不止一個人，包括博伊登、張鋒、班貝格、納格爾和戴瑟羅斯。你不需要背全部人名，但要明白：我們每課講一位主角，並不代表所有成果都由他一個人完成。之後，研究者繼續發展方法，把光控制帶入活體動物研究，也發展出可以增加或抑制活動的不同工具。真正改變腦科學的，是研究者更能選擇在哪些細胞、哪個時間施加改變，再和記錄、觀察配合，研究因果關係。"},"script":"到二零零五年，一篇重要論文發表了。研究者讓哺乳動物神經細胞表達 ChR2，再用快速光刺激，顯示可以精細控制神經細胞的電訊號。這裏不是說光突然令普通腦細胞全部有反應，而是先有具備相應蛋白的細胞，再有合適光刺激，兩者配合。論文作者不止一個人，包括博伊登、張鋒、班貝格、納格爾和戴瑟羅斯。你不需要背全部人名，但要明白：我們每課講一位主角，並不代表所有成果都由他一個人完成。之後，研究者繼續發展方法，把光控制帶入活體動物研究，也發展出可以增加或抑制活動的不同工具。真正改變腦科學的，是研究者更能選擇在哪些細胞、哪個時間施加改變，再和記錄、觀察配合，研究因果關係。"}},{"id":"nobel04-illustrated-07","stageId":"hk-nobel-04-deisseroth-illustrated-v2-mandarin","title":"光怎樣改變細胞訊號？","order":7,"outlineId":"nobel04-illustrated-07-outline","createdAt":1792822716481,"updatedAt":1792822716481,"type":"interactive","actions":[{"id":"nobel04-illustrated-07-speech","type":"speech","text":"現在我們把原理收窄到最重要的一條線。以 ChR2 這種工具為例，第一，選定細胞要表達感光蛋白。第二，合適的光要到達這些蛋白。第三，通道打開，帶電粒子流動，細胞的電狀態就會改變。之後，研究者還要記錄神經訊號或者觀察行為，才知道影響是什麼。你可以把它想成受光控制的小門，但比喻只講通道可以受控制，不是細胞裏面真的有一扇門。也不可以把光想成遙控器裏面一串命令，叫一個人現在開心、現在忘記功課。大腦有很多互相連接的細胞，改變選定細胞可能經網絡影響其他部分，複雜行為不是簡單一按即成。這裏有一個小小的紙上比較：具備 ChR2 和收到合適光，兩個條件怎樣配合？你可以試著選一個情況，看看簡化示意會怎樣解釋。這是教學示意，不是實驗數據，也不是對每一粒細胞的保證。","audioId":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2-mandarin/audio/zh-CN/page-07.mp3","audioUrl":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2-mandarin/audio/zh-CN/page-07.mp3"}],"content":{"type":"interactive","url":"","html":"<!doctype html><html lang=\"zh-Hant-HK\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><style>html,body{margin:0;width:100%;min-height:100%;background:#f5f0e8;color:#102b38;font-family:system-ui,\"PingFang HK\",sans-serif}main{max-width:1080px;margin:auto;padding:14px 24px}.art{display:block;width:100%;max-height:48vh;object-fit:contain}.question{border:2px solid #b5d4c5;background:#fffaf0;border-radius:18px;padding:15px 22px}h2{font-family:\"Songti TC\",serif;font-size:clamp(18px,2.3vw,27px);margin:0 0 12px}.options{display:flex;gap:12px;flex-wrap:wrap}button{font:inherit;font-size:clamp(16px,1.7vw,22px);border:2px solid #368471;border-radius:10px;padding:10px 18px;background:#fff}button[aria-pressed=true]{background:#b5e5cf}.feedback{font-size:17px;line-height:1.55;min-height:2em}.note{font-size:13px;color:#47616c}</style><main><img class=\"art\" src=\"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2/media/07-zh-Hant.png\" alt=\"光怎樣改變細胞訊號？\"><section class=\"question small\"><h2>點選兩個條件，看看這個簡化示意怎樣解釋</h2><div class=\"options\"><button aria-pressed=\"false\" data-condition=\"protein\">感光蛋白：未設定</button><button aria-pressed=\"false\" data-condition=\"light\">合適光：未設定</button></div><p class=\"feedback\" id=\"logic-feedback\" role=\"status\">先看看兩個條件怎樣配合。這不是實驗數據。</p></section><p class=\"note\">教學類比與簡化示意，不是實驗數據；可再次選擇，重新比較。真實研究仍需更多條件與對照。</p></main><script>const state={protein:false,light:false};function update(){document.querySelectorAll('[data-condition]').forEach(b=>{const k=b.dataset.condition;b.setAttribute('aria-pressed',String(state[k]));b.textContent=(k==='protein'?'感光蛋白':'合適光')+'：'+(state[k]?'已設定':'未設定');});const result=!state.protein?'未設定ChR2：本示意不能用ChR2解釋光的效應。這不表示細胞完全沒有其他活動。':!state.light?'有感光蛋白，但未設定合適光：尚未加入本示意的光控制條件。':'具備ChR2與合適光：通道可開啟、改變電狀態。是否產生神經放電仍取決於實驗條件。';document.getElementById('logic-feedback').textContent=result;}document.querySelectorAll('[data-condition]').forEach(b=>b.addEventListener('click',()=>{const k=b.dataset.condition;state[k]=!state[k];update();}));\n</script></html>","widgetType":"html","widgetConfig":{}}},{"id":"nobel04-illustrated-08","stageId":"hk-nobel-04-deisseroth-illustrated-v2-mandarin","title":"為甚麼值得諾獎？","order":8,"outlineId":"nobel04-illustrated-08-outline","createdAt":1792822716481,"updatedAt":1792822716481,"type":"slide","actions":[{"id":"nobel04-illustrated-08-speech","type":"speech","text":"為什麼這件事值得諾貝爾獎？不是因為藍光本身很神奇，也不是因為已經解開大腦所有秘密。頒獎理由肯定的是光控離子通道和光遺傳學的發現。黑格曼和納格爾等人研究到藻類蛋白的特別本領，戴瑟羅斯和合作者再把它發展成精細研究神經活動的工具。以前單靠看到兩件事一起發生，可能難以分清誰影響誰。多了一種能夠改變選定細胞活動的方法，研究者就可以設計更有力的比較。不過，仍然要有對照，檢查照光本身有沒有其他影響，也要配合其他測量。這種方法傳到不同實驗室，令更多人可以追查各自的問題。偉大之處是人類多了一種研究能力，好像為大家多造了一件精細儀器。它不只服務一篇論文，而是令一大批原本難答的問題，變得更有機會找到答案。","audioId":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2-mandarin/audio/zh-CN/page-08.mp3","audioUrl":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2-mandarin/audio/zh-CN/page-08.mp3"},{"id":"nobel04-illustrated-08-discussion","type":"discussion","agentId":"nobel04-assistant","topic":"為甚麼只看細胞活動還不夠？新工具多帶來了甚麼？","prompt":"這是香港初一課堂的一段簡短討論。三個AI角色都必須輪流各自發言，不代寫其他角色；全程用易懂普通話，所有文字只用繁體中文，不混簡體。每位最多兩句短句，不展開新題目或講稿外的專業分析。科學小助手（AI助教）先說明「港鐵車站」比喻的一個界線；科學故事老師（AI老師）接着用一句話說本課發現為甚麼重要；好奇同學（AI同學角色）最後用自己的話複述學到的一個重點，不提出新的專業問題。三位AI都發言後，才把發言交回真人學生，不追加第四輪；這段毋須新增白板或圖表。守住本課證據範圍：合適蛋白要在選定細胞表達，合適的光還要到達。工具幫研究者作受控比較，不是單憑同時出現就證明因果；研究工具不等於治療成功。 光遺傳學以光控制具有合適蛋白的指定細胞活動；光照和蛋白本身不是讀取或顯示自然放電的工具，觀察神經活動須另用合適的記錄方法。蛋白可能使細胞活動增強或受抑，須有合適對照；不可說成必然看到放電或單次比較證明全部因果。 每位都以香港繁體字回答，例如「等於」；老師和同學要分清用光干預細胞活動與另用工具記錄活動。"}],"content":{"type":"slide","canvas":{"id":"nobel04-illustrated-08-canvas","viewportSize":1000,"viewportRatio":0.5625,"theme":{"backgroundColor":"#f6f1e6","themeColors":["#24665f","#bf9949","#102b38"],"fontColor":"#102b38","fontName":"Microsoft JhengHei","outline":{"color":"#102b38","width":1,"style":"solid"},"shadow":{"h":0,"v":0,"blur":0,"color":"#000000"}},"elements":[{"type":"image","id":"nobel04-illustrated-08-art","left":0,"top":0,"width":1000,"height":562.5,"rotate":0,"fixedRatio":true,"src":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2-mandarin/media/08-zh-Hant.png","name":"為甚麼值得諾獎？；從觀察活動，前進到有條件地測試因果作用。"},{"type":"shape","id":"nobel04-illustrated-08-key","left":40,"top":100,"width":500,"height":250,"rotate":0,"fill":"transparent","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"shape","id":"nobel04-illustrated-08-footer","left":40,"top":519,"width":920,"height":33,"rotate":0,"fill":"#F5F0E8","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"text","id":"nobel04-illustrated-08-boundary","left":44,"top":523,"width":910,"height":27,"rotate":0,"content":"<p style=\"margin:0;font-size:10px;line-height:1.3\">教學插畫／類比，不是研究現場或實驗數據；研究及應用均有條件。</p>","defaultColor":"#47616c","defaultFontName":"Microsoft JhengHei"}],"background":{"type":"solid","color":"#f6f1e6"},"script":"為什麼這件事值得諾貝爾獎？不是因為藍光本身很神奇，也不是因為已經解開大腦所有秘密。頒獎理由肯定的是光控離子通道和光遺傳學的發現。黑格曼和納格爾等人研究到藻類蛋白的特別本領，戴瑟羅斯和合作者再把它發展成精細研究神經活動的工具。以前單靠看到兩件事一起發生，可能難以分清誰影響誰。多了一種能夠改變選定細胞活動的方法，研究者就可以設計更有力的比較。不過，仍然要有對照，檢查照光本身有沒有其他影響，也要配合其他測量。這種方法傳到不同實驗室，令更多人可以追查各自的問題。偉大之處是人類多了一種研究能力，好像為大家多造了一件精細儀器。它不只服務一篇論文，而是令一大批原本難答的問題，變得更有機會找到答案。"},"script":"為什麼這件事值得諾貝爾獎？不是因為藍光本身很神奇，也不是因為已經解開大腦所有秘密。頒獎理由肯定的是光控離子通道和光遺傳學的發現。黑格曼和納格爾等人研究到藻類蛋白的特別本領，戴瑟羅斯和合作者再把它發展成精細研究神經活動的工具。以前單靠看到兩件事一起發生，可能難以分清誰影響誰。多了一種能夠改變選定細胞活動的方法，研究者就可以設計更有力的比較。不過，仍然要有對照，檢查照光本身有沒有其他影響，也要配合其他測量。這種方法傳到不同實驗室，令更多人可以追查各自的問題。偉大之處是人類多了一種研究能力，好像為大家多造了一件精細儀器。它不只服務一篇論文，而是令一大批原本難答的問題，變得更有機會找到答案。"}},{"id":"nobel04-illustrated-09","stageId":"hk-nobel-04-deisseroth-illustrated-v2-mandarin","title":"普通人關心的問題","order":9,"outlineId":"nobel04-illustrated-09-outline","createdAt":1792822716481,"updatedAt":1792822716481,"type":"slide","actions":[{"id":"nobel04-illustrated-09-speech","type":"speech","text":"站在普通人的角度，我們最關心的可能是：如果家人長期受腦部或精神疾病困擾，研究有沒有機會幫到他？光遺傳學的一個重要價值，是幫助研究者把問題問得更清楚。例如二零一一年的一項小鼠研究，研究者改變某些腦區之間特定連接的活動，觀察到小鼠焦慮樣行為會有變化。重點不是要你背腦區名，而是原來不同連接可能有不同作用；只講某個大範圍腦區活躍，可能還太粗略。更加清楚地瞭解相關細胞和連接，可能為後續藥物或其他治療研究提供方向。但我們要守住一條重要界線：小鼠的行為指標，不等同完整理解一個人的感受。動物研究有發現，也不等於人的焦慮已經可以用這個方法治好。由瞭解機制到可靠、安全的治療，還需要很多步、很多研究。","audioId":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2-mandarin/audio/zh-CN/page-09.mp3","audioUrl":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2-mandarin/audio/zh-CN/page-09.mp3"}],"content":{"type":"slide","canvas":{"id":"nobel04-illustrated-09-canvas","viewportSize":1000,"viewportRatio":0.5625,"theme":{"backgroundColor":"#f6f1e6","themeColors":["#24665f","#bf9949","#102b38"],"fontColor":"#102b38","fontName":"Microsoft JhengHei","outline":{"color":"#102b38","width":1,"style":"solid"},"shadow":{"h":0,"v":0,"blur":0,"color":"#000000"}},"elements":[{"type":"image","id":"nobel04-illustrated-09-art","left":0,"top":0,"width":1000,"height":562.5,"rotate":0,"fixedRatio":true,"src":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2-mandarin/media/09-zh-Hant.png","name":"普通人關心的問題；睡眠、記憶和情緒研究，多了一種重要工具。"},{"type":"shape","id":"nobel04-illustrated-09-key","left":40,"top":100,"width":500,"height":250,"rotate":0,"fill":"transparent","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"shape","id":"nobel04-illustrated-09-footer","left":40,"top":519,"width":920,"height":33,"rotate":0,"fill":"#F5F0E8","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"text","id":"nobel04-illustrated-09-boundary","left":44,"top":523,"width":910,"height":27,"rotate":0,"content":"<p style=\"margin:0;font-size:10px;line-height:1.3\">教學插畫／類比，不是研究現場或實驗數據；研究及應用均有條件。</p>","defaultColor":"#47616c","defaultFontName":"Microsoft JhengHei"}],"background":{"type":"solid","color":"#f6f1e6"},"script":"站在普通人的角度，我們最關心的可能是：如果家人長期受腦部或精神疾病困擾，研究有沒有機會幫到他？光遺傳學的一個重要價值，是幫助研究者把問題問得更清楚。例如二零一一年的一項小鼠研究，研究者改變某些腦區之間特定連接的活動，觀察到小鼠焦慮樣行為會有變化。重點不是要你背腦區名，而是原來不同連接可能有不同作用；只講某個大範圍腦區活躍，可能還太粗略。更加清楚地瞭解相關細胞和連接，可能為後續藥物或其他治療研究提供方向。但我們要守住一條重要界線：小鼠的行為指標，不等同完整理解一個人的感受。動物研究有發現，也不等於人的焦慮已經可以用這個方法治好。由瞭解機制到可靠、安全的治療，還需要很多步、很多研究。"},"script":"站在普通人的角度，我們最關心的可能是：如果家人長期受腦部或精神疾病困擾，研究有沒有機會幫到他？光遺傳學的一個重要價值，是幫助研究者把問題問得更清楚。例如二零一一年的一項小鼠研究，研究者改變某些腦區之間特定連接的活動，觀察到小鼠焦慮樣行為會有變化。重點不是要你背腦區名，而是原來不同連接可能有不同作用；只講某個大範圍腦區活躍，可能還太粗略。更加清楚地瞭解相關細胞和連接，可能為後續藥物或其他治療研究提供方向。但我們要守住一條重要界線：小鼠的行為指標，不等同完整理解一個人的感受。動物研究有發現，也不等於人的焦慮已經可以用這個方法治好。由瞭解機制到可靠、安全的治療，還需要很多步、很多研究。"}},{"id":"nobel04-illustrated-10","stageId":"hk-nobel-04-deisseroth-illustrated-v2-mandarin","title":"醫療希望，還要驗證","order":10,"outlineId":"nobel04-illustrated-10-outline","createdAt":1792822716481,"updatedAt":1792822716481,"type":"slide","actions":[{"id":"nobel04-illustrated-10-speech","type":"speech","text":"我們再看一個和生活非常接近的例子。對一個嚴重視力受損的人來說，可以辨認桌上有物件，已經可能是一件有意義的事。二零二一年，Sahel、Roska 和合作者報告了一位視網膜色素病變患者的研究結果。研究結合令視網膜細胞表達感光蛋白，和專門設計的眼鏡。在測試之中，這位患者能夠辨認、定位和接觸部分物件。這個例子顯示，借用感光蛋白改變細胞反應的思路，有機會走向幫助人的研究。但不要把它講成恢復正常視力：報告是部分功能的改善，也不是說任何失明患者都適用，更不是戴一副普通眼鏡就行。眼鏡、細胞改變和訓練，要在特定研究條件下配合。還要記住，這項視覺研究由後續團隊完成，不可以把全部功勞放在戴瑟羅斯一個人身上。真正的希望，應該和清楚的證據邊界一起講。","audioId":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2-mandarin/audio/zh-CN/page-10.mp3","audioUrl":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2-mandarin/audio/zh-CN/page-10.mp3"}],"content":{"type":"slide","canvas":{"id":"nobel04-illustrated-10-canvas","viewportSize":1000,"viewportRatio":0.5625,"theme":{"backgroundColor":"#f6f1e6","themeColors":["#24665f","#bf9949","#102b38"],"fontColor":"#102b38","fontName":"Microsoft JhengHei","outline":{"color":"#102b38","width":1,"style":"solid"},"shadow":{"h":0,"v":0,"blur":0,"color":"#000000"}},"elements":[{"type":"image","id":"nobel04-illustrated-10-art","left":0,"top":0,"width":1000,"height":562.5,"rotate":0,"fixedRatio":true,"src":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2-mandarin/media/10-zh-Hant.png","name":"醫療希望，還要驗證；早期視覺研究有進展，不能說已恢復正常視力。"},{"type":"shape","id":"nobel04-illustrated-10-key","left":40,"top":100,"width":500,"height":250,"rotate":0,"fill":"transparent","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"shape","id":"nobel04-illustrated-10-footer","left":40,"top":519,"width":920,"height":33,"rotate":0,"fill":"#F5F0E8","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"text","id":"nobel04-illustrated-10-boundary","left":44,"top":523,"width":910,"height":27,"rotate":0,"content":"<p style=\"margin:0;font-size:10px;line-height:1.3\">教學插畫／類比，不是研究現場或實驗數據；研究及應用均有條件。</p>","defaultColor":"#47616c","defaultFontName":"Microsoft JhengHei"}],"background":{"type":"solid","color":"#f6f1e6"},"script":"我們再看一個和生活非常接近的例子。對一個嚴重視力受損的人來說，可以辨認桌上有物件，已經可能是一件有意義的事。二零二一年，Sahel、Roska 和合作者報告了一位視網膜色素病變患者的研究結果。研究結合令視網膜細胞表達感光蛋白，和專門設計的眼鏡。在測試之中，這位患者能夠辨認、定位和接觸部分物件。這個例子顯示，借用感光蛋白改變細胞反應的思路，有機會走向幫助人的研究。但不要把它講成恢復正常視力：報告是部分功能的改善，也不是說任何失明患者都適用，更不是戴一副普通眼鏡就行。眼鏡、細胞改變和訓練，要在特定研究條件下配合。還要記住，這項視覺研究由後續團隊完成，不可以把全部功勞放在戴瑟羅斯一個人身上。真正的希望，應該和清楚的證據邊界一起講。"},"script":"我們再看一個和生活非常接近的例子。對一個嚴重視力受損的人來說，可以辨認桌上有物件，已經可能是一件有意義的事。二零二一年，Sahel、Roska 和合作者報告了一位視網膜色素病變患者的研究結果。研究結合令視網膜細胞表達感光蛋白，和專門設計的眼鏡。在測試之中，這位患者能夠辨認、定位和接觸部分物件。這個例子顯示，借用感光蛋白改變細胞反應的思路，有機會走向幫助人的研究。但不要把它講成恢復正常視力：報告是部分功能的改善，也不是說任何失明患者都適用，更不是戴一副普通眼鏡就行。眼鏡、細胞改變和訓練，要在特定研究條件下配合。還要記住，這項視覺研究由後續團隊完成，不可以把全部功勞放在戴瑟羅斯一個人身上。真正的希望，應該和清楚的證據邊界一起講。"}},{"id":"nobel04-illustrated-11","stageId":"hk-nobel-04-deisseroth-illustrated-v2-mandarin","title":"三個小判斷","order":11,"outlineId":"nobel04-illustrated-11-outline","createdAt":1792822716481,"updatedAt":1792822716481,"type":"quiz","actions":[{"id":"nobel04-illustrated-11-speech","type":"speech","text":"故事講到這裏，你不需要考自己記不記得蛋白質的全名。試著用三個問題，捉住最重要的意思。第一，光遺傳學是不是用電筒照普通腦細胞就完成？要回想蛋白工具和合適光這兩個條件。第二，為什麼改變選定細胞活動會有研究價值？因為研究者可以再觀察結果，和適當對照作比較，追問細胞活動和結果的關係。第三，一位患者有部分視覺功能改善，能不能直接講成所有失明已經可以醫好？不能。每一個答案都可以再試，重點是看解釋，想清楚自己有沒有把研究工具誤當成神奇遙控器，或者把一個有限的研究結果誤當成對所有人的承諾。這也是讀科學新聞很有用的習慣：先問它真的做到什麼，再問還有什麼未證實。","audioId":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2-mandarin/audio/zh-CN/page-11.mp3","audioUrl":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2-mandarin/audio/zh-CN/page-11.mp3"}],"content":{"type":"quiz","questions":[{"id":"nobel04-illustrated-11-q1","type":"single","question":"這項工具為甚麼可以讓選定神經細胞受光影響？","options":[{"value":"A","label":"普通電筒能向任何腦細胞發出思想指令。"},{"value":"B","label":"選定細胞先表達感光蛋白，再接受合適的光。"}],"answer":["B"],"analysis":"A：不是思想遙控器。要先有相應感光蛋白，還要合適的光到達。；B：對。以ChR2為例，感光蛋白與合適光配合，改變細胞的電狀態。","points":10,"hasAnswer":true},{"id":"nobel04-illustrated-11-q2","type":"single","question":"為甚麼這項研究值得諾獎？","options":[{"value":"A","label":"它讓研究者更精細地改變細胞活動、作比較，追問因果關係。"},{"value":"B","label":"它已解開每一個人的所有想法。"}],"answer":["A"],"analysis":"A：對。這是一種新的研究能力，仍要配合對照、記錄與其他方法。；B：研究方法更有力，不代表已讀懂所有思想或大腦所有秘密。","points":10,"hasAnswer":true},{"id":"nobel04-illustrated-11-q3","type":"single","question":"2021年的視覺研究案例，最合理的說法是甚麼？","options":[{"value":"A","label":"任何失明都能戴普通眼鏡治好。"},{"value":"B","label":"戴瑟羅斯一個人完成所有視覺治療研究。"},{"value":"C","label":"後續團隊報告特定患者的部分功能改善，不能推廣成對所有人的保證。"}],"answer":["C"],"analysis":"A：研究需要特定細胞改變、專用設備與研究條件，不能推廣到所有失明原因。；B：視覺研究由Sahel、Roska及合作者進行；基礎工具與後續應用有各自團隊的貢獻。；C：對。具體的研究進展值得期待，也要保留適用範圍與仍需驗證的部分。","points":10,"hasAnswer":true}]}},{"id":"nobel04-illustrated-12","stageId":"hk-nobel-04-deisseroth-illustrated-v2-mandarin","title":"自然的小本領，人類的新工具","order":12,"outlineId":"nobel04-illustrated-12-outline","createdAt":1792822716481,"updatedAt":1792822716481,"type":"slide","actions":[{"id":"nobel04-illustrated-12-speech","type":"speech","text":"最後，回到戴瑟羅斯這個人。他不是一出世就懂得用光研究大腦。生物學學習、神經科學研究、醫學和精神科訓練，再加上和不同專長的人合作，才逐步形成這條研究道路。藻類的一種感光本領，和研究者想理解大腦的問題接在一起，變成了更多實驗室可以使用的工具。對普通人來說，價值一方面是我們更加有能力理解自己的大腦；另一方面，這些知識可能幫助後續研究，尋找更好的醫療方向。但是要一步一步驗證，不可以把希望當成保證。今天你帶走的不一定是一個專有名詞，而是一個更有力的提問習慣：看到兩件事一起發生，有沒有足夠理由講因果？研究者改變了什麼，又比較了什麼？下一課，我們會更走近藻類研究者黑格曼，看看一個關於微小生命的好奇問題，怎樣成為這個故事另一個重要起點。","audioId":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2-mandarin/audio/zh-CN/page-12.mp3","audioUrl":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2-mandarin/audio/zh-CN/page-12.mp3"}],"content":{"type":"slide","canvas":{"id":"nobel04-illustrated-12-canvas","viewportSize":1000,"viewportRatio":0.5625,"theme":{"backgroundColor":"#f6f1e6","themeColors":["#24665f","#bf9949","#102b38"],"fontColor":"#102b38","fontName":"Microsoft JhengHei","outline":{"color":"#102b38","width":1,"style":"solid"},"shadow":{"h":0,"v":0,"blur":0,"color":"#000000"}},"elements":[{"type":"image","id":"nobel04-illustrated-12-art","left":0,"top":0,"width":1000,"height":562.5,"rotate":0,"fixedRatio":true,"src":"/api/classroom-media/hk-nobel-04-deisseroth-illustrated-v2-mandarin/media/12-zh-Hant.png","name":"自然的小本領，人類的新工具；訓練與合作，把微藻線索帶進腦科學。"},{"type":"shape","id":"nobel04-illustrated-12-key","left":40,"top":100,"width":500,"height":250,"rotate":0,"fill":"transparent","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"shape","id":"nobel04-illustrated-12-footer","left":40,"top":519,"width":920,"height":33,"rotate":0,"fill":"#F5F0E8","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"講解區"},{"type":"text","id":"nobel04-illustrated-12-boundary","left":44,"top":523,"width":910,"height":27,"rotate":0,"content":"<p style=\"margin:0;font-size:10px;line-height:1.3\">教學插畫／類比，不是研究現場或實驗數據；研究及應用均有條件。</p>","defaultColor":"#47616c","defaultFontName":"Microsoft JhengHei"}],"background":{"type":"solid","color":"#f6f1e6"},"script":"最後，回到戴瑟羅斯這個人。他不是一出世就懂得用光研究大腦。生物學學習、神經科學研究、醫學和精神科訓練，再加上和不同專長的人合作，才逐步形成這條研究道路。藻類的一種感光本領，和研究者想理解大腦的問題接在一起，變成了更多實驗室可以使用的工具。對普通人來說，價值一方面是我們更加有能力理解自己的大腦；另一方面，這些知識可能幫助後續研究，尋找更好的醫療方向。但是要一步一步驗證，不可以把希望當成保證。今天你帶走的不一定是一個專有名詞，而是一個更有力的提問習慣：看到兩件事一起發生，有沒有足夠理由講因果？研究者改變了什麼，又比較了什麼？下一課，我們會更走近藻類研究者黑格曼，看看一個關於微小生命的好奇問題，怎樣成為這個故事另一個重要起點。"},"script":"最後，回到戴瑟羅斯這個人。他不是一出世就懂得用光研究大腦。生物學學習、神經科學研究、醫學和精神科訓練，再加上和不同專長的人合作，才逐步形成這條研究道路。藻類的一種感光本領，和研究者想理解大腦的問題接在一起，變成了更多實驗室可以使用的工具。對普通人來說，價值一方面是我們更加有能力理解自己的大腦；另一方面，這些知識可能幫助後續研究，尋找更好的醫療方向。但是要一步一步驗證，不可以把希望當成保證。今天你帶走的不一定是一個專有名詞，而是一個更有力的提問習慣：看到兩件事一起發生，有沒有足夠理由講因果？研究者改變了什麼，又比較了什麼？下一課，我們會更走近藻類研究者黑格曼，看看一個關於微小生命的好奇問題，怎樣成為這個故事另一個重要起點。"}}]}},{"num":"07","lang":"yue","sha":"21dbe1a6ee8145fbdd29f69138c950cd51006e3effb05e5b53a671c753a58a3e","course":{"id":"hk-nobel-07-sakaguchi-illustrated-v2","createdAt":"2026-11-04T00:00:00.000Z","stage":{"id":"hk-nobel-07-sakaguchi-illustrated-v2","name":"坂口志文：身體裏為甚麼需要「勸架員」？（廣東話講解）","description":"從坂口志文追問的免疫謎題出發，認識身體怎樣減少免疫誤傷，理解2025年諾貝爾生理學或醫學獎的研究價值。","languageDirective":"所有學生可見文字均使用香港繁體中文。用廣東話講解。不提供個人診療建議。 說明調節作用時使用「有助減少誤傷」，不保證完全不會出錯；生活比喻不代表細胞有人的意識。 本課證據範圍：1995年細胞轉移研究是在特定小鼠與實驗條件下，移除一群細胞可導致自身組織受損，合適條件下補回可預防該模型中的損傷；不可概括為所有動物或人的必然結果。在某些感染或腫瘤情境，調節性T細胞限制免疫反應的作用可能有不同影響；不以單一強弱或「平衡」比喻解釋全部，也不推論個人治療。 生活比喻不可說「保安多抓人必然出錯」：檢查次數增加不必然代表誤抓；不分情況亂抓可能誤傷無辜。免疫調節有助反應適時降下並減少傷害，但可能失衡，不能保證一定停止或完全不誤傷。","createdAt":1793793600000,"updatedAt":1793793600000,"style":"slide","generatedAgentConfigs":[{"id":"nobel07-teacher","name":"科學故事老師","role":"teacher","persona":"我會用生活例子講清楚免疫控制，也會說明科學比喻的限制：調節性T細胞有助減少免疫誤傷，並非保證不會出錯；研究前景也不等於已證明治癒。 生活比喻不可說「保安多抓人必然出錯」：檢查次數增加不必然代表誤抓；不分情況亂抓可能誤傷無辜。免疫調節有助反應適時降下並減少傷害，但可能失衡，不能保證一定停止或完全不誤傷。","avatar":"/avatars/teacher.png","color":"#24665f","priority":10},{"id":"nobel07-assistant","name":"科學小助手","role":"assistant","persona":"我會幫你看清證據範圍：在特定小鼠與細胞轉移研究條件下，去除一群調節性T細胞可導致自身組織受損；不能直接說成所有動物或人的必然結果。在某些感染或腫瘤情境，限制免疫反應的作用可能有不同影響，不能只用強弱或「平衡」概括全部。不提供個人診療建議。 生活比喻不可說「保安多抓人必然出錯」：檢查次數增加不必然代表誤抓；不分情況亂抓可能誤傷無辜。免疫調節有助反應適時降下並減少傷害，但可能失衡，不能保證一定停止或完全不誤傷。","avatar":"/avatars/assist.png","color":"#2563eb","priority":7},{"id":"nobel07-student","name":"好奇同學","role":"student","persona":"我是AI同學，喜歡問「在甚麼情況下才成立？」並用證據修正理解。 生活比喻不可說「保安多抓人必然出錯」：檢查次數增加不必然代表誤抓；不分情況亂抓可能誤傷無辜。免疫調節有助反應適時降下並減少傷害，但可能失衡，不能保證一定停止或完全不誤傷。","avatar":"/avatars/curious.png","color":"#bf9949","priority":5}]},"scenes":[{"id":"nobel07-slide-01","stageId":"hk-nobel-07-sakaguchi-illustrated-v2","title":"先認識一位研究“別打錯人”的醫生","order":1,"outlineId":"nobel07-slide-01-outline","createdAt":1793793600000,"updatedAt":1793793600000,"type":"slide","actions":[{"id":"nobel07-slide-01-focus","type":"spotlight","elementId":"nobel07-slide-01-key"},{"id":"nobel07-slide-01-speech","type":"speech","text":"相入面呢位科學家叫坂口志文。佢係二零二五年諾貝爾生理學或醫學獎嘅共同得主。佢喺日本讀醫，之後研究免疫系統。你可以先將免疫系統理解成身體入面一套保護力量：唔同細胞一齊合作，幫手應付感染。佢關心一個幾特別嘅問題：保護身體嘅力量，如果將自己身體當成攻擊目標，邊個可以阻止佢？今日我哋就跟住佢，搵下身體入面嘅「勸架員」。","audioId":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2/audio/yue-HK/page-01.mp3","audioUrl":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2/audio/yue-HK/page-01.mp3"}],"content":{"type":"slide","canvas":{"id":"nobel07-slide-01-canvas","viewportSize":1000,"viewportRatio":0.5625,"theme":{"backgroundColor":"#f6f1e6","themeColors":["#24665f","#bf9949","#102b38"],"fontColor":"#102b38","fontName":"Microsoft YaHei","outline":{"color":"#102b38","width":1,"style":"solid"},"shadow":{"h":0,"v":0,"blur":0,"color":"#000000"}},"elements":[{"type":"image","id":"nobel07-slide-01-art","left":0,"top":0,"width":1000,"height":562.5,"rotate":0,"fixedRatio":true,"src":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2/media/01-zh-Hant.png","name":"坂口志文；身體裏為甚麼需要「勸架員」？2025年諾貝爾生理學或醫學獎共同得主。"},{"type":"shape","id":"nobel07-slide-01-key","left":44,"top":120,"width":340,"height":220,"rotate":0,"fill":"transparent","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"重點講解區"},{"type":"image","id":"nobel07-slide-01-portrait","left":44,"top":309,"width":110,"height":165,"rotate":0,"fixedRatio":true,"src":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2/media/sakaguchi-portrait.jpg"},{"type":"text","id":"nobel07-slide-01-caption","left":44,"top":482,"width":415,"height":33,"rotate":0,"content":"<p style=\"margin:0;font-size:11px;line-height:1.35\">坂口志文資料照｜文部科學省・大臣官房人事課。<a href=\"https://commons.wikimedia.org/wiki/File:Shimon_Sakaguchi_201711.jpg\">來源</a>／<a href=\"https://creativecommons.org/licenses/by/4.0/\">CC BY 4.0</a>。2017年資料，非領獎現場；原圖未修改。</p>","defaultColor":"#47616c","defaultFontName":"Microsoft JhengHei"},{"type":"shape","id":"nobel07-slide-01-footer-paper","left":44,"top":519,"width":912,"height":33,"rotate":0,"fill":"#F5F0E8","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"圖說底色"},{"type":"text","id":"nobel07-slide-01-boundary","left":44,"top":523,"width":910,"height":27,"rotate":0,"content":"<p style=\"margin:0;font-size:11px;line-height:1.35\">擬人化教學插畫，細胞沒有意識；獎章僅為裝飾。</p>","defaultColor":"#506773","defaultFontName":"Microsoft JhengHei"},{"type":"text","id":"sakaguchi-narration-choice","left":44,"top":276,"width":240,"height":25,"rotate":0,"content":"<p style=\"margin:0;font-size:16px\"><a href=\"/classroom/hk-nobel-07-sakaguchi-illustrated-v2-mandarin\">切換至普通話講解 →</a></p>","defaultColor":"#24665f","defaultFontName":"Microsoft JhengHei","link":{"type":"web","target":"/classroom/hk-nobel-07-sakaguchi-illustrated-v2-mandarin"}}],"background":{"type":"solid","color":"#f6f1e6"},"script":"相入面呢位科學家叫坂口志文。佢係二零二五年諾貝爾生理學或醫學獎嘅共同得主。佢喺日本讀醫，之後研究免疫系統。你可以先將免疫系統理解成身體入面一套保護力量：唔同細胞一齊合作，幫手應付感染。佢關心一個幾特別嘅問題：保護身體嘅力量，如果將自己身體當成攻擊目標，邊個可以阻止佢？今日我哋就跟住佢，搵下身體入面嘅「勸架員」。"}}},{"id":"nobel07-slide-02","stageId":"hk-nobel-07-sakaguchi-illustrated-v2","title":"商場保安，抓得越多越好嗎？","order":2,"outlineId":"nobel07-slide-02-outline","createdAt":1793793600000,"updatedAt":1793793600000,"type":"slide","actions":[{"id":"nobel07-slide-02-focus","type":"spotlight","elementId":"nobel07-slide-02-key"},{"id":"nobel07-slide-02-speech","type":"speech","text":"想像你同屋企人去商場。保安攔住真正有危險嘅人，大家會安全啲。但如果連正常買嘢嘅顧客都攔住，甚至整傷佢哋呢？咁就唔單止係保安夠唔夠多，仲要睇有冇認錯對象。記住，呢個只係幫我哋理解嘅比喻。細胞唔會認人面、睇證件，亦唔會好似人咁商量；佢哋係靠分子之間嘅相互作用，接收同傳遞訊號。你會揀邊一種保安？可以揀完再改。","audioId":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2/audio/yue-HK/page-02.mp3","audioUrl":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2/audio/yue-HK/page-02.mp3"}],"content":{"type":"slide","canvas":{"id":"nobel07-slide-02-canvas","viewportSize":1000,"viewportRatio":0.5625,"theme":{"backgroundColor":"#f6f1e6","themeColors":["#24665f","#bf9949","#102b38"],"fontColor":"#102b38","fontName":"Microsoft YaHei","outline":{"color":"#102b38","width":1,"style":"solid"},"shadow":{"h":0,"v":0,"blur":0,"color":"#000000"}},"elements":[{"type":"image","id":"nobel07-slide-02-art","left":0,"top":0,"width":1000,"height":562.5,"rotate":0,"fixedRatio":true,"src":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2/media/02-zh-Hant.png","name":"商場保安，抓得越多越好嗎？；保護大家 ≠ 見人就攔。你會選哪種保安？"},{"type":"shape","id":"nobel07-slide-02-key","left":44,"top":225,"width":340,"height":220,"rotate":0,"fill":"transparent","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"重點講解區"},{"type":"shape","id":"nobel07-slide-02-footer-paper","left":44,"top":519,"width":912,"height":33,"rotate":0,"fill":"#F5F0E8","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"圖說底色"},{"type":"text","id":"nobel07-slide-02-boundary","left":44,"top":523,"width":910,"height":27,"rotate":0,"content":"<p style=\"margin:0;font-size:11px;line-height:1.35\">商場生活類比，細胞不靠人臉或證件辨認。</p>","defaultColor":"#506773","defaultFontName":"Microsoft JhengHei"}],"background":{"type":"solid","color":"#f6f1e6"},"script":"想像你同屋企人去商場。保安攔住真正有危險嘅人，大家會安全啲。但如果連正常買嘢嘅顧客都攔住，甚至整傷佢哋呢？咁就唔單止係保安夠唔夠多，仲要睇有冇認錯對象。記住，呢個只係幫我哋理解嘅比喻。細胞唔會認人面、睇證件，亦唔會好似人咁商量；佢哋係靠分子之間嘅相互作用，接收同傳遞訊號。你會揀邊一種保安？可以揀完再改。"}}},{"id":"nobel07-slide-03","stageId":"hk-nobel-07-sakaguchi-illustrated-v2","title":"一個反常結果，讓他想追下去","order":3,"outlineId":"nobel07-slide-03-outline","createdAt":1793793600000,"updatedAt":1793793600000,"type":"slide","actions":[{"id":"nobel07-slide-03-focus","type":"spotlight","elementId":"nobel07-slide-03-key"},{"id":"nobel07-slide-03-speech","type":"speech","text":"呢個唔係憑空諗出嚟嘅謎語。早期有啲小鼠研究發現，喺特定條件之下，免疫系統少咗某啲細胞，結果唔單止係防禦能力改變，仲出現攻擊自己組織嘅情況。呢個反常現象令坂口志文想追問：會唔會有啲細胞，工作唔係加強攻擊，而係約束其他細胞？呢度講緊特定嘅動物研究，唔係話人少咗少少免疫細胞，就一定會生病。我哋唔需要學動物實驗操作，只要捉住呢個值得追問嘅現象。","audioId":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2/audio/yue-HK/page-03.mp3","audioUrl":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2/audio/yue-HK/page-03.mp3"}],"content":{"type":"slide","canvas":{"id":"nobel07-slide-03-canvas","viewportSize":1000,"viewportRatio":0.5625,"theme":{"backgroundColor":"#f6f1e6","themeColors":["#24665f","#bf9949","#102b38"],"fontColor":"#102b38","fontName":"Microsoft YaHei","outline":{"color":"#102b38","width":1,"style":"solid"},"shadow":{"h":0,"v":0,"blur":0,"color":"#000000"}},"elements":[{"type":"image","id":"nobel07-slide-03-art","left":0,"top":0,"width":1000,"height":562.5,"rotate":0,"fixedRatio":true,"src":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2/media/03-zh-Hant.png","name":"一個反常結果，讓他想追下去；少了一部分免疫細胞，為什麼反而出現攻擊自己的情況？"},{"type":"shape","id":"nobel07-slide-03-key","left":44,"top":225,"width":340,"height":220,"rotate":0,"fill":"transparent","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"重點講解區"},{"type":"shape","id":"nobel07-slide-03-footer-paper","left":44,"top":519,"width":912,"height":33,"rotate":0,"fill":"#F5F0E8","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"圖說底色"},{"type":"text","id":"nobel07-slide-03-boundary","left":44,"top":523,"width":910,"height":27,"rotate":0,"content":"<p style=\"margin:0;font-size:11px;line-height:1.35\">虛構研究者插畫，非坂口本人；細胞表情僅為擬人化。</p>","defaultColor":"#506773","defaultFontName":"Microsoft JhengHei"}],"background":{"type":"solid","color":"#f6f1e6"},"script":"呢個唔係憑空諗出嚟嘅謎語。早期有啲小鼠研究發現，喺特定條件之下，免疫系統少咗某啲細胞，結果唔單止係防禦能力改變，仲出現攻擊自己組織嘅情況。呢個反常現象令坂口志文想追問：會唔會有啲細胞，工作唔係加強攻擊，而係約束其他細胞？呢度講緊特定嘅動物研究，唔係話人少咗少少免疫細胞，就一定會生病。我哋唔需要學動物實驗操作，只要捉住呢個值得追問嘅現象。"}}},{"id":"nobel07-slide-04","stageId":"hk-nobel-07-sakaguchi-illustrated-v2","title":"身體不只有一種“保護隊員”","order":4,"outlineId":"nobel07-slide-04-outline","createdAt":1793793600000,"updatedAt":1793793600000,"type":"slide","actions":[{"id":"nobel07-slide-04-focus","type":"spotlight","elementId":"nobel07-slide-04-key"},{"id":"nobel07-slide-04-speech","type":"speech","text":"免疫細胞唔係一粒粒完全一樣嘅小球。好似T細胞，就係免疫細胞入面一大類，仲有唔同分工。個T字只係名稱一部分，今日唔使背。如果將所有免疫細胞當成一樣，就可能睇漏咗佢哋唔同嘅作用。好似學校入面有學生、老師同校工，唔可以因為大家都喺度活動，就話所有人做緊同一樣嘢。相入面係人工著色嘅T細胞電鏡圖，唔可以單靠張相，就認定佢係調節性T細胞。","audioId":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2/audio/yue-HK/page-04.mp3","audioUrl":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2/audio/yue-HK/page-04.mp3"}],"content":{"type":"slide","canvas":{"id":"nobel07-slide-04-canvas","viewportSize":1000,"viewportRatio":0.5625,"theme":{"backgroundColor":"#f6f1e6","themeColors":["#24665f","#bf9949","#102b38"],"fontColor":"#102b38","fontName":"Microsoft YaHei","outline":{"color":"#102b38","width":1,"style":"solid"},"shadow":{"h":0,"v":0,"blur":0,"color":"#000000"}},"elements":[{"type":"image","id":"nobel07-slide-04-art","left":0,"top":0,"width":1000,"height":562.5,"rotate":0,"fixedRatio":true,"src":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2/media/04-zh-Hant.png","name":"身體不只有一種“保護隊員”；有些細胞參與攻擊；有些細胞幫助約束反應。"},{"type":"shape","id":"nobel07-slide-04-key","left":44,"top":225,"width":340,"height":220,"rotate":0,"fill":"transparent","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"重點講解區"},{"type":"image","id":"nobel07-slide-04-micrograph","left":44,"top":307,"width":180,"height":180,"rotate":0,"fixedRatio":true,"src":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2/media/healthy-t-cell.jpg"},{"type":"text","id":"nobel07-slide-04-caption","left":237,"top":330,"width":205,"height":150,"rotate":0,"content":"<p style=\"margin:0;font-size:12px;line-height:1.35\">T細胞掃描電鏡圖，人工著色。NIAID/NIH · <a href=\"https://commons.wikimedia.org/wiki/File:Healthy_Human_T_Cell.jpg\">來源與公有領域標記</a>。不能憑照片鑒定為調節性T細胞；不是本課實驗圖。</p>","defaultColor":"#47616c","defaultFontName":"Microsoft JhengHei"},{"type":"shape","id":"nobel07-slide-04-footer-paper","left":44,"top":519,"width":912,"height":33,"rotate":0,"fill":"#F5F0E8","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"圖說底色"},{"type":"text","id":"nobel07-slide-04-boundary","left":44,"top":523,"width":910,"height":27,"rotate":0,"content":"<p style=\"margin:0;font-size:11px;line-height:1.35\">右側為細胞教學插畫，不是顯微圖或精確分類。</p>","defaultColor":"#506773","defaultFontName":"Microsoft JhengHei"}],"background":{"type":"solid","color":"#f6f1e6"},"script":"免疫細胞唔係一粒粒完全一樣嘅小球。好似T細胞，就係免疫細胞入面一大類，仲有唔同分工。個T字只係名稱一部分，今日唔使背。如果將所有免疫細胞當成一樣，就可能睇漏咗佢哋唔同嘅作用。好似學校入面有學生、老師同校工，唔可以因為大家都喺度活動，就話所有人做緊同一樣嘢。相入面係人工著色嘅T細胞電鏡圖，唔可以單靠張相，就認定佢係調節性T細胞。"}}},{"id":"nobel07-slide-05","stageId":"hk-nobel-07-sakaguchi-illustrated-v2","title":"不是給細胞起個名字，就算發現了","order":5,"outlineId":"nobel07-slide-05-outline","createdAt":1793793600000,"updatedAt":1793793600000,"type":"slide","actions":[{"id":"nobel07-slide-05-focus","type":"spotlight","elementId":"nobel07-slide-05-key"},{"id":"nobel07-slide-05-speech","type":"speech","text":"坂口志文同合作者要攞出證據，唔係改個名就算發現。佢哋用細胞表面一啲分子特徵，幫手分組。喺一九九五年嘅研究，團隊將唔同細胞組合，轉移畀特定嘅實驗小鼠作比較。由準備轉移嘅組合中，移走一組細胞之後，餘下嘅組合可能引起身體組織受攻擊；喺合適條件下補返嗰組細胞，就可以阻止呢個情況。呢啲證據支持：嗰組細胞有份維持控制。佢哋後來叫調節性T細胞。不過，分子特徵唔係萬能身份證，動物實驗亦唔等於人嘅治療已經成功。","audioId":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2/audio/yue-HK/page-05.mp3","audioUrl":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2/audio/yue-HK/page-05.mp3"}],"content":{"type":"slide","canvas":{"id":"nobel07-slide-05-canvas","viewportSize":1000,"viewportRatio":0.5625,"theme":{"backgroundColor":"#f6f1e6","themeColors":["#24665f","#bf9949","#102b38"],"fontColor":"#102b38","fontName":"Microsoft YaHei","outline":{"color":"#102b38","width":1,"style":"solid"},"shadow":{"h":0,"v":0,"blur":0,"color":"#000000"}},"elements":[{"type":"image","id":"nobel07-slide-05-art","left":0,"top":0,"width":1000,"height":562.5,"rotate":0,"fixedRatio":true,"src":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2/media/05-zh-Hant.png","name":"不是給細胞起個名字，就算發現了；1995年：用實驗區分一群能約束免疫反應的T細胞。"},{"type":"shape","id":"nobel07-slide-05-key","left":44,"top":120,"width":900,"height":130,"rotate":0,"fill":"transparent","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"重點講解區"},{"type":"shape","id":"nobel07-slide-05-footer-paper","left":44,"top":519,"width":912,"height":33,"rotate":0,"fill":"#F5F0E8","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"圖說底色"},{"type":"text","id":"nobel07-slide-05-boundary","left":44,"top":523,"width":910,"height":27,"rotate":0,"content":"<p style=\"margin:0;font-size:11px;line-height:1.35\">特定動物研究的邏輯示意，非數據、非人體治療。</p>","defaultColor":"#506773","defaultFontName":"Microsoft JhengHei"}],"background":{"type":"solid","color":"#f6f1e6"},"script":"坂口志文同合作者要攞出證據，唔係改個名就算發現。佢哋用細胞表面一啲分子特徵，幫手分組。喺一九九五年嘅研究，團隊將唔同細胞組合，轉移畀特定嘅實驗小鼠作比較。由準備轉移嘅組合中，移走一組細胞之後，餘下嘅組合可能引起身體組織受攻擊；喺合適條件下補返嗰組細胞，就可以阻止呢個情況。呢啲證據支持：嗰組細胞有份維持控制。佢哋後來叫調節性T細胞。不過，分子特徵唔係萬能身份證，動物實驗亦唔等於人嘅治療已經成功。"}}},{"id":"nobel07-slide-06","stageId":"hk-nobel-07-sakaguchi-illustrated-v2","title":"“勸架員”到底做了什麼？","order":6,"outlineId":"nobel07-slide-06-outline","createdAt":1793793600000,"updatedAt":1793793600000,"type":"slide","actions":[{"id":"nobel07-slide-06-focus","type":"spotlight","elementId":"nobel07-slide-06-key"},{"id":"nobel07-slide-06-speech","type":"speech","text":"返去商場個比喻。調節性T細胞可以暫時比作幫手約束行動嘅「勸架員」。佢哋可以透過同其他細胞接觸、釋放訊號等方式，限制免疫反應，減少對自己組織嘅傷害。但唔係有個小人喺細胞入面叫停，佢哋亦唔係負責所有嘢嘅總司令。身體仲有其他保護機制。今日我哋只係認識其中好重要一種：保護自己，亦需要避免自己嘅保護力量失去控制。","audioId":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2/audio/yue-HK/page-06.mp3","audioUrl":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2/audio/yue-HK/page-06.mp3"}],"content":{"type":"slide","canvas":{"id":"nobel07-slide-06-canvas","viewportSize":1000,"viewportRatio":0.5625,"theme":{"backgroundColor":"#f6f1e6","themeColors":["#24665f","#bf9949","#102b38"],"fontColor":"#102b38","fontName":"Microsoft YaHei","outline":{"color":"#102b38","width":1,"style":"solid"},"shadow":{"h":0,"v":0,"blur":0,"color":"#000000"}},"elements":[{"type":"image","id":"nobel07-slide-06-art","left":0,"top":0,"width":1000,"height":562.5,"rotate":0,"fixedRatio":true,"src":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2/media/06-zh-Hant.png","name":"“勸架員”到底做了什麼？；調節性T細胞：幫助限制其他免疫細胞的反應。"},{"type":"shape","id":"nobel07-slide-06-key","left":44,"top":225,"width":340,"height":220,"rotate":0,"fill":"transparent","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"重點講解區"},{"type":"shape","id":"nobel07-slide-06-footer-paper","left":44,"top":519,"width":912,"height":33,"rotate":0,"fill":"#F5F0E8","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"圖說底色"},{"type":"text","id":"nobel07-slide-06-boundary","left":44,"top":523,"width":910,"height":27,"rotate":0,"content":"<p style=\"margin:0;font-size:11px;line-height:1.35\">接觸與信號的示意，形狀、比例和分子結構未按實物繪製。</p>","defaultColor":"#506773","defaultFontName":"Microsoft JhengHei"}],"background":{"type":"solid","color":"#f6f1e6"},"script":"返去商場個比喻。調節性T細胞可以暫時比作幫手約束行動嘅「勸架員」。佢哋可以透過同其他細胞接觸、釋放訊號等方式，限制免疫反應，減少對自己組織嘅傷害。但唔係有個小人喺細胞入面叫停，佢哋亦唔係負責所有嘢嘅總司令。身體仲有其他保護機制。今日我哋只係認識其中好重要一種：保護自己，亦需要避免自己嘅保護力量失去控制。"}}},{"id":"nobel07-slide-07","stageId":"hk-nobel-07-sakaguchi-illustrated-v2","title":"為什麼是三個人共同獲獎？","order":7,"outlineId":"nobel07-slide-07-outline","createdAt":1793793600000,"updatedAt":1793793600000,"type":"slide","actions":[{"id":"nobel07-slide-07-focus","type":"spotlight","elementId":"nobel07-slide-07-key"},{"id":"nobel07-slide-07-speech","type":"speech","text":"坂口志文唔係一個人完成所有發現。瑪麗布倫科、弗雷德拉姆斯德爾同合作者，搵到一個同嚴重免疫失控有關嘅關鍵基因。之後，坂口團隊同其他研究者，將呢個基因同調節性T細胞嘅形成連繫起嚟。你可以咁理解：有人搵到重要細胞，有人搵到影響控制嘅關鍵線索，多條證據慢慢接埋一齊。呢個過程幫人類理解，免疫系統點樣避免攻擊自己嘅組織。二零二五年，佢哋三位共同獲得諾貝爾生理學或醫學獎。唔使背基因嘅字母名稱，記住共同發現嘅意思就得。","audioId":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2/audio/yue-HK/page-07.mp3","audioUrl":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2/audio/yue-HK/page-07.mp3"}],"content":{"type":"slide","canvas":{"id":"nobel07-slide-07-canvas","viewportSize":1000,"viewportRatio":0.5625,"theme":{"backgroundColor":"#f6f1e6","themeColors":["#24665f","#bf9949","#102b38"],"fontColor":"#102b38","fontName":"Microsoft YaHei","outline":{"color":"#102b38","width":1,"style":"solid"},"shadow":{"h":0,"v":0,"blur":0,"color":"#000000"}},"elements":[{"type":"image","id":"nobel07-slide-07-art","left":0,"top":0,"width":1000,"height":562.5,"rotate":0,"fixedRatio":true,"src":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2/media/07-zh-Hant.png","name":"為什麼是三個人共同獲獎？；坂口志文／Mary E. Brunkow／Fred Ramsdell。共同研究主題：外周免疫耐受。"},{"type":"shape","id":"nobel07-slide-07-key","left":44,"top":120,"width":900,"height":130,"rotate":0,"fill":"transparent","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"重點講解區"},{"type":"shape","id":"nobel07-slide-07-footer-paper","left":44,"top":519,"width":912,"height":33,"rotate":0,"fill":"#F5F0E8","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"圖說底色"},{"type":"text","id":"nobel07-slide-07-boundary","left":44,"top":523,"width":910,"height":27,"rotate":0,"content":"<p style=\"margin:0;font-size:11px;line-height:1.35\">證據聯繫示意；不是三人在同一實驗現場。</p>","defaultColor":"#506773","defaultFontName":"Microsoft JhengHei"}],"background":{"type":"solid","color":"#f6f1e6"},"script":"坂口志文唔係一個人完成所有發現。瑪麗布倫科、弗雷德拉姆斯德爾同合作者，搵到一個同嚴重免疫失控有關嘅關鍵基因。之後，坂口團隊同其他研究者，將呢個基因同調節性T細胞嘅形成連繫起嚟。你可以咁理解：有人搵到重要細胞，有人搵到影響控制嘅關鍵線索，多條證據慢慢接埋一齊。呢個過程幫人類理解，免疫系統點樣避免攻擊自己嘅組織。二零二五年，佢哋三位共同獲得諾貝爾生理學或醫學獎。唔使背基因嘅字母名稱，記住共同發現嘅意思就得。"}}},{"id":"nobel07-slide-08","stageId":"hk-nobel-07-sakaguchi-illustrated-v2","title":"這對普通人有什麼用？","order":8,"outlineId":"nobel07-slide-08-outline","createdAt":1793793600000,"updatedAt":1793793600000,"type":"slide","actions":[{"id":"nobel07-slide-08-focus","type":"spotlight","elementId":"nobel07-slide-08-key"},{"id":"nobel07-slide-08-speech","type":"speech","text":"有啲疾病涉及免疫系統錯誤攻擊自己組織，叫自身免疫病。對病人嚟講，重要嘅唔單止係壓低所有免疫反應，而係可唔可以減少有害攻擊，同時盡量保留應付感染嘅能力。呢項發現，為搵更有針對性嘅方法提供咗方向。研究者曾經做過將調節性T細胞用喺一型糖尿病嘅早期人體試驗。不過，早期安全性研究唔等於證明可以治好病，更加唔可以講成打一針，就永遠唔會生病。","audioId":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2/audio/yue-HK/page-08.mp3","audioUrl":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2/audio/yue-HK/page-08.mp3"}],"content":{"type":"slide","canvas":{"id":"nobel07-slide-08-canvas","viewportSize":1000,"viewportRatio":0.5625,"theme":{"backgroundColor":"#f6f1e6","themeColors":["#24665f","#bf9949","#102b38"],"fontColor":"#102b38","fontName":"Microsoft YaHei","outline":{"color":"#102b38","width":1,"style":"solid"},"shadow":{"h":0,"v":0,"blur":0,"color":"#000000"}},"elements":[{"type":"image","id":"nobel07-slide-08-art","left":0,"top":0,"width":1000,"height":562.5,"rotate":0,"fixedRatio":true,"src":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2/media/08-zh-Hant.png","name":"這對普通人有什麼用？；如果保護系統誤傷了身體，我們能更有針對性地幫助它恢復控制嗎？"},{"type":"shape","id":"nobel07-slide-08-key","left":44,"top":225,"width":340,"height":220,"rotate":0,"fill":"transparent","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"重點講解區"},{"type":"shape","id":"nobel07-slide-08-footer-paper","left":44,"top":519,"width":912,"height":33,"rotate":0,"fill":"#F5F0E8","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"圖說底色"},{"type":"text","id":"nobel07-slide-08-boundary","left":44,"top":523,"width":910,"height":27,"rotate":0,"content":"<p style=\"margin:0;font-size:11px;line-height:1.35\">普通生活插畫；治療研究仍需檢驗安全與效果。</p>","defaultColor":"#506773","defaultFontName":"Microsoft JhengHei"}],"background":{"type":"solid","color":"#f6f1e6"},"script":"有啲疾病涉及免疫系統錯誤攻擊自己組織，叫自身免疫病。對病人嚟講，重要嘅唔單止係壓低所有免疫反應，而係可唔可以減少有害攻擊，同時盡量保留應付感染嘅能力。呢項發現，為搵更有針對性嘅方法提供咗方向。研究者曾經做過將調節性T細胞用喺一型糖尿病嘅早期人體試驗。不過，早期安全性研究唔等於證明可以治好病，更加唔可以講成打一針，就永遠唔會生病。"}}},{"id":"nobel07-slide-09","stageId":"hk-nobel-07-sakaguchi-illustrated-v2","title":"有趣的轉折：為什麼不是越多越好？","order":9,"outlineId":"nobel07-slide-09-outline","createdAt":1793793600000,"updatedAt":1793793600000,"type":"slide","actions":[{"id":"nobel07-slide-09-focus","type":"spotlight","elementId":"nobel07-slide-09-key"},{"id":"nobel07-slide-09-speech","type":"speech","text":"假如有人破壞商場設施，但有人將想阻止佢嘅保安勸走，會點呢？喺某啲腫瘤周圍，調節性T細胞亦可能限制咗對抗腫瘤嘅免疫反應。所以，研究者會諗，點樣喺特定地方減輕呢種限制，而唔係幫全身加更多「勸架員」。我哋唔可以簡單話免疫越強越好，亦唔係越弱越好，而係要問：邊個地方、邊段時間，需要點樣調節？呢啲係研究方向，唔係叫大家自己調節細胞或者用藥。","audioId":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2/audio/yue-HK/page-09.mp3","audioUrl":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2/audio/yue-HK/page-09.mp3"}],"content":{"type":"slide","canvas":{"id":"nobel07-slide-09-canvas","viewportSize":1000,"viewportRatio":0.5625,"theme":{"backgroundColor":"#f6f1e6","themeColors":["#24665f","#bf9949","#102b38"],"fontColor":"#102b38","fontName":"Microsoft YaHei","outline":{"color":"#102b38","width":1,"style":"solid"},"shadow":{"h":0,"v":0,"blur":0,"color":"#000000"}},"elements":[{"type":"image","id":"nobel07-slide-09-art","left":0,"top":0,"width":1000,"height":562.5,"rotate":0,"fixedRatio":true,"src":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2/media/09-zh-Hant.png","name":"有趣的轉折：為什麼不是越多越好？；同一種“勸架”作用，也可能在不合適的地方幫倒忙。"},{"type":"shape","id":"nobel07-slide-09-key","left":44,"top":225,"width":340,"height":220,"rotate":0,"fill":"transparent","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"重點講解區"},{"type":"shape","id":"nobel07-slide-09-footer-paper","left":44,"top":519,"width":912,"height":33,"rotate":0,"fill":"#F5F0E8","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"圖說底色"},{"type":"text","id":"nobel07-slide-09-boundary","left":44,"top":523,"width":910,"height":27,"rotate":0,"content":"<p style=\"margin:0;font-size:11px;line-height:1.35\">某些腫瘤中的情境示意；細胞沒有意識。</p>","defaultColor":"#506773","defaultFontName":"Microsoft JhengHei"}],"background":{"type":"solid","color":"#f6f1e6"},"script":"假如有人破壞商場設施，但有人將想阻止佢嘅保安勸走，會點呢？喺某啲腫瘤周圍，調節性T細胞亦可能限制咗對抗腫瘤嘅免疫反應。所以，研究者會諗，點樣喺特定地方減輕呢種限制，而唔係幫全身加更多「勸架員」。我哋唔可以簡單話免疫越強越好，亦唔係越弱越好，而係要問：邊個地方、邊段時間，需要點樣調節？呢啲係研究方向，唔係叫大家自己調節細胞或者用藥。"}}},{"id":"nobel07-slide-10","stageId":"hk-nobel-07-sakaguchi-illustrated-v2","title":"諾獎為什麼獎勵這樣的基礎發現？","order":10,"outlineId":"nobel07-slide-10-outline","createdAt":1793793600000,"updatedAt":1793793600000,"type":"slide","actions":[{"id":"nobel07-slide-10-focus","type":"spotlight","elementId":"nobel07-slide-10-key"},{"id":"nobel07-slide-10-speech","type":"speech","text":"呢項研究嘅重要，唔需要靠「已經醫好所有疾病」嚟證明。佢令科學家睇見，保護身體嘅系統入面，主動約束攻擊亦係重要工作。知道呢個控制環節，先可以更清楚咁研究邊度出問題、提出新嘅治療諗法，再用實驗同臨床研究檢驗。基礎發現，好似喺複雜嘅城市地圖上，搵到以前未睇清楚嘅交通樞紐。有咗佢，可以研究新路線，但每條路行唔行得通，仲要逐條驗證。","audioId":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2/audio/yue-HK/page-10.mp3","audioUrl":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2/audio/yue-HK/page-10.mp3"},{"id":"nobel07-slide-10-discussion","type":"discussion","topic":"為什麼保護身體也需要約束反應？","prompt":"這是一段簡短口頭討論。科學小助手先用一句話說清商場保安比喻的界線；科學故事老師接著用一句話連回免疫控制為何有價值；好奇同學最後用自己的話概括免疫調節的價值和限制。各角色只代表自己發言，不代寫別人的話。完成後把發言交回學生，不繼續延伸新回合；這段毋須開白板或新增圖表。不提供個人診療建議。 生活比喻不可說「保安多抓人必然出錯」：檢查次數增加不必然代表誤抓；不分情況亂抓可能誤傷無辜。免疫調節有助反應適時降下並減少傷害，但可能失衡，不能保證一定停止或完全不誤傷。 每位以香港繁體字簡短發言；好奇同學最後用自己的話概括免疫調節的價值及限制，不提出新的醫療或專業問題。","agentId":"nobel07-assistant"}],"content":{"type":"slide","canvas":{"id":"nobel07-slide-10-canvas","viewportSize":1000,"viewportRatio":0.5625,"theme":{"backgroundColor":"#f6f1e6","themeColors":["#24665f","#bf9949","#102b38"],"fontColor":"#102b38","fontName":"Microsoft YaHei","outline":{"color":"#102b38","width":1,"style":"solid"},"shadow":{"h":0,"v":0,"blur":0,"color":"#000000"}},"elements":[{"type":"image","id":"nobel07-slide-10-art","left":0,"top":0,"width":1000,"height":562.5,"rotate":0,"fixedRatio":true,"src":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2/media/10-zh-Hant.png","name":"諾獎為什麼獎勵這樣的基礎發現？；它改變了一個大問題的答案：身體怎樣保護自己，又避免誤傷自己？"},{"type":"shape","id":"nobel07-slide-10-key","left":44,"top":225,"width":340,"height":220,"rotate":0,"fill":"transparent","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"重點講解區"},{"type":"shape","id":"nobel07-slide-10-footer-paper","left":44,"top":519,"width":912,"height":33,"rotate":0,"fill":"#F5F0E8","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"圖說底色"},{"type":"text","id":"nobel07-slide-10-boundary","left":44,"top":523,"width":910,"height":27,"rotate":0,"content":"<p style=\"margin:0;font-size:11px;line-height:1.35\">城市地圖只是類比；新路線能否走通仍需驗證。</p>","defaultColor":"#506773","defaultFontName":"Microsoft JhengHei"}],"background":{"type":"solid","color":"#f6f1e6"},"script":"呢項研究嘅重要，唔需要靠「已經醫好所有疾病」嚟證明。佢令科學家睇見，保護身體嘅系統入面，主動約束攻擊亦係重要工作。知道呢個控制環節，先可以更清楚咁研究邊度出問題、提出新嘅治療諗法，再用實驗同臨床研究檢驗。基礎發現，好似喺複雜嘅城市地圖上，搵到以前未睇清楚嘅交通樞紐。有咗佢，可以研究新路線，但每條路行唔行得通，仲要逐條驗證。"}}},{"id":"nobel07-slide-11","stageId":"hk-nobel-07-sakaguchi-illustrated-v2","title":"三次小判斷","order":11,"outlineId":"nobel07-slide-11-outline","createdAt":1793793600000,"updatedAt":1793793600000,"type":"quiz","actions":[{"id":"nobel07-slide-11-speech","type":"speech","text":"而家停一停，試下判斷三個問題。揀好答案之後提交，就可以睇解釋；答錯都可以重試。最後，用自己嘅說話講下：點解保護身體，亦需要約束免疫反應？唔使背標準句子。","audioId":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2/audio/yue-HK/page-11-narration-fix-20261109.mp3","audioUrl":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2/audio/yue-HK/page-11-narration-fix-20261109.mp3"}],"content":{"type":"quiz","questions":[{"id":"nobel07-slide-11-q1","type":"single","question":"1. 今天的發現，最接近哪句話？","options":[{"value":"A","label":"免疫細胞越多越好"},{"value":"B","label":"有一類T細胞能幫助約束免疫反應"},{"value":"C","label":"人體只有一種免疫細胞"}],"answer":["B"],"analysis":"A：把數量和保護效果混為一談，過度或錯誤的反應也能傷害身體。；B：抓住主線，調節性T細胞參與控制，但並非唯一機制。；C：不對，免疫系統有多種細胞和分工。","points":10,"hasAnswer":true},{"id":"nobel07-slide-11-q2","type":"single","question":"2. 小鼠研究支持某組細胞有保護作用，下一步能直接宣佈人類治療成功嗎？","options":[{"value":"A","label":"能"},{"value":"B","label":"不能，還需針對人的安全性和有效性研究"}],"answer":["B"],"analysis":"A：把動物實驗直接等同於人的療效。；B：正確，動物研究能提供線索，但不能代替臨床檢驗。","points":10,"hasAnswer":true},{"id":"nobel07-slide-11-q3","type":"single","question":"3. 關於調節性T細胞，哪種說法更準確？","options":[{"value":"A","label":"給所有人增加越多越好"},{"value":"B","label":"它們毫無用途"},{"value":"C","label":"作用要結合疾病、部位和情境理解"}],"answer":["C"],"analysis":"A：忽略了某些腫瘤中的控制問題。；B：忽略了維持免疫控制的重要作用。；C：正確，同一種作用是否有幫助，要看具體情境。","points":10,"hasAnswer":true}]}},{"id":"nobel07-slide-12","stageId":"hk-nobel-07-sakaguchi-illustrated-v2","title":"帶走一個問題","order":12,"outlineId":"nobel07-slide-12-outline","createdAt":1793793600000,"updatedAt":1793793600000,"type":"slide","actions":[{"id":"nobel07-slide-12-focus","type":"spotlight","elementId":"nobel07-slide-12-key"},{"id":"nobel07-slide-12-speech","type":"speech","text":"坂口志文經過醫學學習同長期研究，同合作者不斷搵證據，分清唔同細胞嘅作用。值得我哋學嘅，唔係話只要堅持，就一定攞到獎，而係認真對待反常現象，再用證據檢驗解釋。下次聽到「越多越好」或者「越強越好」，可以先問：喺咩情況下有用？幾時可能有害？下一課，我哋會認識一位用人工智能研究蛋白質嘅科學家，睇下另一個好難回答嘅問題，點樣出現新研究工具。","audioId":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2/audio/yue-HK/page-12.mp3","audioUrl":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2/audio/yue-HK/page-12.mp3"}],"content":{"type":"slide","canvas":{"id":"nobel07-slide-12-canvas","viewportSize":1000,"viewportRatio":0.5625,"theme":{"backgroundColor":"#f6f1e6","themeColors":["#24665f","#bf9949","#102b38"],"fontColor":"#102b38","fontName":"Microsoft YaHei","outline":{"color":"#102b38","width":1,"style":"solid"},"shadow":{"h":0,"v":0,"blur":0,"color":"#000000"}},"elements":[{"type":"image","id":"nobel07-slide-12-art","left":0,"top":0,"width":1000,"height":562.5,"rotate":0,"fixedRatio":true,"src":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2/media/12-zh-Hant.png","name":"帶走一個問題；遇到和預想相反的結果，先問：是不是漏看了一種作用？"},{"type":"shape","id":"nobel07-slide-12-key","left":44,"top":225,"width":340,"height":220,"rotate":0,"fill":"transparent","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"重點講解區"},{"type":"image","id":"nobel07-slide-12-portrait","left":44,"top":309,"width":110,"height":165,"rotate":0,"fixedRatio":true,"src":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2/media/sakaguchi-portrait.jpg"},{"type":"text","id":"nobel07-slide-12-caption","left":44,"top":482,"width":415,"height":33,"rotate":0,"content":"<p style=\"margin:0;font-size:11px;line-height:1.35\">坂口志文資料照｜文部科學省・大臣官房人事課。<a href=\"https://commons.wikimedia.org/wiki/File:Shimon_Sakaguchi_201711.jpg\">來源</a>／<a href=\"https://creativecommons.org/licenses/by/4.0/\">CC BY 4.0</a>。2017年資料，非領獎現場；原圖未修改。</p>","defaultColor":"#47616c","defaultFontName":"Microsoft JhengHei"},{"type":"shape","id":"nobel07-slide-12-footer-paper","left":44,"top":519,"width":912,"height":33,"rotate":0,"fill":"#F5F0E8","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"圖說底色"},{"type":"text","id":"nobel07-slide-12-boundary","left":44,"top":523,"width":910,"height":27,"rotate":0,"content":"<p style=\"margin:0;font-size:11px;line-height:1.35\">研究思路插畫，非歷史實驗記錄。</p>","defaultColor":"#506773","defaultFontName":"Microsoft JhengHei"}],"background":{"type":"solid","color":"#f6f1e6"},"script":"坂口志文經過醫學學習同長期研究，同合作者不斷搵證據，分清唔同細胞嘅作用。值得我哋學嘅，唔係話只要堅持，就一定攞到獎，而係認真對待反常現象，再用證據檢驗解釋。下次聽到「越多越好」或者「越強越好」，可以先問：喺咩情況下有用？幾時可能有害？下一課，我哋會認識一位用人工智能研究蛋白質嘅科學家，睇下另一個好難回答嘅問題，點樣出現新研究工具。"}}}]}},{"num":"07","lang":"mandarin","sha":"3fb96f8a67b443047f7b3fad101f72122499e4ab2004699dbff9a26487dd9d45","course":{"id":"hk-nobel-07-sakaguchi-illustrated-v2-mandarin","createdAt":"2026-11-04T00:00:00.000Z","stage":{"id":"hk-nobel-07-sakaguchi-illustrated-v2-mandarin","name":"坂口志文：身體裏為甚麼需要「勸架員」？（普通話講解）","description":"從坂口志文追問的免疫謎題出發，認識身體怎樣減少免疫誤傷，理解2025年諾貝爾生理學或醫學獎的研究價值。","languageDirective":"所有學生可見文字均使用香港繁體中文。用普通話講解。不提供個人診療建議。 說明調節作用時使用「有助減少誤傷」，不保證完全不會出錯；生活比喻不代表細胞有人的意識。 本課證據範圍：1995年細胞轉移研究是在特定小鼠與實驗條件下，移除一群細胞可導致自身組織受損，合適條件下補回可預防該模型中的損傷；不可概括為所有動物或人的必然結果。在某些感染或腫瘤情境，調節性T細胞限制免疫反應的作用可能有不同影響；不以單一強弱或「平衡」比喻解釋全部，也不推論個人治療。 生活比喻不可說「保安多抓人必然出錯」：檢查次數增加不必然代表誤抓；不分情況亂抓可能誤傷無辜。免疫調節有助反應適時降下並減少傷害，但可能失衡，不能保證一定停止或完全不誤傷。","createdAt":1793793600000,"updatedAt":1793793600000,"style":"slide","generatedAgentConfigs":[{"id":"nobel07-teacher","name":"科學故事老師","role":"teacher","persona":"我會用生活例子講清楚免疫控制，也會說明科學比喻的限制：調節性T細胞有助減少免疫誤傷，並非保證不會出錯；研究前景也不等於已證明治癒。 生活比喻不可說「保安多抓人必然出錯」：檢查次數增加不必然代表誤抓；不分情況亂抓可能誤傷無辜。免疫調節有助反應適時降下並減少傷害，但可能失衡，不能保證一定停止或完全不誤傷。","avatar":"/avatars/teacher.png","color":"#24665f","priority":10},{"id":"nobel07-assistant","name":"科學小助手","role":"assistant","persona":"我會幫你看清證據範圍：在特定小鼠與細胞轉移研究條件下，去除一群調節性T細胞可導致自身組織受損；不能直接說成所有動物或人的必然結果。在某些感染或腫瘤情境，限制免疫反應的作用可能有不同影響，不能只用強弱或「平衡」概括全部。不提供個人診療建議。 生活比喻不可說「保安多抓人必然出錯」：檢查次數增加不必然代表誤抓；不分情況亂抓可能誤傷無辜。免疫調節有助反應適時降下並減少傷害，但可能失衡，不能保證一定停止或完全不誤傷。","avatar":"/avatars/assist.png","color":"#2563eb","priority":7},{"id":"nobel07-student","name":"好奇同學","role":"student","persona":"我是AI同學，喜歡問「在甚麼情況下才成立？」並用證據修正理解。 生活比喻不可說「保安多抓人必然出錯」：檢查次數增加不必然代表誤抓；不分情況亂抓可能誤傷無辜。免疫調節有助反應適時降下並減少傷害，但可能失衡，不能保證一定停止或完全不誤傷。","avatar":"/avatars/curious.png","color":"#bf9949","priority":5}]},"scenes":[{"id":"nobel07-slide-01","stageId":"hk-nobel-07-sakaguchi-illustrated-v2-mandarin","title":"先認識一位研究“別打錯人”的醫生","order":1,"outlineId":"nobel07-slide-01-outline","createdAt":1793793600000,"updatedAt":1793793600000,"type":"slide","actions":[{"id":"nobel07-slide-01-focus","type":"spotlight","elementId":"nobel07-slide-01-key"},{"id":"nobel07-slide-01-speech","type":"speech","text":"照片裏的這位科學家叫坂口志文。他是2025年諾貝爾生理學或醫學獎的共同得主。他在日本學習醫學，後來研究免疫系統。你可以先把免疫系統理解成身體的一套保護力量：不同細胞合作，幫助對付感染。他關心一個有點反常的問題：保護身體的力量，如果把自己的身體當成目標，誰來阻止它？我們今天跟著他，找一找身體裏的“勸架員”。","audioId":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2-mandarin/audio/zh-CN/page-01.mp3","audioUrl":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2-mandarin/audio/zh-CN/page-01.mp3"}],"content":{"type":"slide","canvas":{"id":"nobel07-slide-01-canvas","viewportSize":1000,"viewportRatio":0.5625,"theme":{"backgroundColor":"#f6f1e6","themeColors":["#24665f","#bf9949","#102b38"],"fontColor":"#102b38","fontName":"Microsoft YaHei","outline":{"color":"#102b38","width":1,"style":"solid"},"shadow":{"h":0,"v":0,"blur":0,"color":"#000000"}},"elements":[{"type":"image","id":"nobel07-slide-01-art","left":0,"top":0,"width":1000,"height":562.5,"rotate":0,"fixedRatio":true,"src":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2-mandarin/media/01-zh-Hant.png","name":"坂口志文；身體裏為甚麼需要「勸架員」？2025年諾貝爾生理學或醫學獎共同得主。"},{"type":"shape","id":"nobel07-slide-01-key","left":44,"top":120,"width":340,"height":220,"rotate":0,"fill":"transparent","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"重點講解區"},{"type":"image","id":"nobel07-slide-01-portrait","left":44,"top":309,"width":110,"height":165,"rotate":0,"fixedRatio":true,"src":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2-mandarin/media/sakaguchi-portrait.jpg"},{"type":"text","id":"nobel07-slide-01-caption","left":44,"top":482,"width":415,"height":33,"rotate":0,"content":"<p style=\"margin:0;font-size:11px;line-height:1.35\">坂口志文資料照｜文部科學省・大臣官房人事課。<a href=\"https://commons.wikimedia.org/wiki/File:Shimon_Sakaguchi_201711.jpg\">來源</a>／<a href=\"https://creativecommons.org/licenses/by/4.0/\">CC BY 4.0</a>。2017年資料，非領獎現場；原圖未修改。</p>","defaultColor":"#47616c","defaultFontName":"Microsoft JhengHei"},{"type":"shape","id":"nobel07-slide-01-footer-paper","left":44,"top":519,"width":912,"height":33,"rotate":0,"fill":"#F5F0E8","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"圖說底色"},{"type":"text","id":"nobel07-slide-01-boundary","left":44,"top":523,"width":910,"height":27,"rotate":0,"content":"<p style=\"margin:0;font-size:11px;line-height:1.35\">擬人化教學插畫，細胞沒有意識；獎章僅為裝飾。</p>","defaultColor":"#506773","defaultFontName":"Microsoft JhengHei"},{"type":"text","id":"sakaguchi-narration-choice","left":44,"top":276,"width":240,"height":25,"rotate":0,"content":"<p style=\"margin:0;font-size:16px\"><a href=\"/classroom/hk-nobel-07-sakaguchi-illustrated-v2\">切換至廣東話講解 →</a></p>","defaultColor":"#24665f","defaultFontName":"Microsoft JhengHei","link":{"type":"web","target":"/classroom/hk-nobel-07-sakaguchi-illustrated-v2"}}],"background":{"type":"solid","color":"#f6f1e6"},"script":"照片裏的這位科學家叫坂口志文。他是2025年諾貝爾生理學或醫學獎的共同得主。他在日本學習醫學，後來研究免疫系統。你可以先把免疫系統理解成身體的一套保護力量：不同細胞合作，幫助對付感染。他關心一個有點反常的問題：保護身體的力量，如果把自己的身體當成目標，誰來阻止它？我們今天跟著他，找一找身體裏的“勸架員”。"}}},{"id":"nobel07-slide-02","stageId":"hk-nobel-07-sakaguchi-illustrated-v2-mandarin","title":"商場保安，抓得越多越好嗎？","order":2,"outlineId":"nobel07-slide-02-outline","createdAt":1793793600000,"updatedAt":1793793600000,"type":"slide","actions":[{"id":"nobel07-slide-02-focus","type":"spotlight","elementId":"nobel07-slide-02-key"},{"id":"nobel07-slide-02-speech","type":"speech","text":"想象你和家人去商場。保安攔住真正危險的人，大家會更安全。可是，如果保安連正常買東西的顧客也攔住，甚至弄傷他們呢？這時，問題就不是“保安夠不夠多”，還包括“有沒有搞錯對象”。這只是幫助理解的比方：身體裏的細胞不會認人臉、看證件，也不會像人一樣商量。它們靠分子之間的相互作用接收和傳遞信號。","audioId":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2-mandarin/audio/zh-CN/page-02.mp3","audioUrl":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2-mandarin/audio/zh-CN/page-02.mp3"}],"content":{"type":"slide","canvas":{"id":"nobel07-slide-02-canvas","viewportSize":1000,"viewportRatio":0.5625,"theme":{"backgroundColor":"#f6f1e6","themeColors":["#24665f","#bf9949","#102b38"],"fontColor":"#102b38","fontName":"Microsoft YaHei","outline":{"color":"#102b38","width":1,"style":"solid"},"shadow":{"h":0,"v":0,"blur":0,"color":"#000000"}},"elements":[{"type":"image","id":"nobel07-slide-02-art","left":0,"top":0,"width":1000,"height":562.5,"rotate":0,"fixedRatio":true,"src":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2-mandarin/media/02-zh-Hant.png","name":"商場保安，抓得越多越好嗎？；保護大家 ≠ 見人就攔。你會選哪種保安？"},{"type":"shape","id":"nobel07-slide-02-key","left":44,"top":225,"width":340,"height":220,"rotate":0,"fill":"transparent","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"重點講解區"},{"type":"shape","id":"nobel07-slide-02-footer-paper","left":44,"top":519,"width":912,"height":33,"rotate":0,"fill":"#F5F0E8","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"圖說底色"},{"type":"text","id":"nobel07-slide-02-boundary","left":44,"top":523,"width":910,"height":27,"rotate":0,"content":"<p style=\"margin:0;font-size:11px;line-height:1.35\">商場生活類比，細胞不靠人臉或證件辨認。</p>","defaultColor":"#506773","defaultFontName":"Microsoft JhengHei"}],"background":{"type":"solid","color":"#f6f1e6"},"script":"想象你和家人去商場。保安攔住真正危險的人，大家會更安全。可是，如果保安連正常買東西的顧客也攔住，甚至弄傷他們呢？這時，問題就不是“保安夠不夠多”，還包括“有沒有搞錯對象”。這只是幫助理解的比方：身體裏的細胞不會認人臉、看證件，也不會像人一樣商量。它們靠分子之間的相互作用接收和傳遞信號。"}}},{"id":"nobel07-slide-03","stageId":"hk-nobel-07-sakaguchi-illustrated-v2-mandarin","title":"一個反常結果，讓他想追下去","order":3,"outlineId":"nobel07-slide-03-outline","createdAt":1793793600000,"updatedAt":1793793600000,"type":"slide","actions":[{"id":"nobel07-slide-03-focus","type":"spotlight","elementId":"nobel07-slide-03-key"},{"id":"nobel07-slide-03-speech","type":"speech","text":"這不是憑空想出來的謎語。早先一些小鼠研究發現，在特定條件下，免疫系統裏少了某些細胞，結果不只是防禦能力改變，還出現了攻擊自身組織的情況。這個反常現象吸引了坂口志文：會不會有些細胞的任務，不是讓攻擊更猛烈，而是約束其他細胞？請注意，這說的是特定動物研究，不是說人只要少一點免疫細胞就一定會生病。我們不需要學習動物實驗操作，只抓住這個值得追問的現象。","audioId":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2-mandarin/audio/zh-CN/page-03.mp3","audioUrl":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2-mandarin/audio/zh-CN/page-03.mp3"}],"content":{"type":"slide","canvas":{"id":"nobel07-slide-03-canvas","viewportSize":1000,"viewportRatio":0.5625,"theme":{"backgroundColor":"#f6f1e6","themeColors":["#24665f","#bf9949","#102b38"],"fontColor":"#102b38","fontName":"Microsoft YaHei","outline":{"color":"#102b38","width":1,"style":"solid"},"shadow":{"h":0,"v":0,"blur":0,"color":"#000000"}},"elements":[{"type":"image","id":"nobel07-slide-03-art","left":0,"top":0,"width":1000,"height":562.5,"rotate":0,"fixedRatio":true,"src":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2-mandarin/media/03-zh-Hant.png","name":"一個反常結果，讓他想追下去；少了一部分免疫細胞，為什麼反而出現攻擊自己的情況？"},{"type":"shape","id":"nobel07-slide-03-key","left":44,"top":225,"width":340,"height":220,"rotate":0,"fill":"transparent","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"重點講解區"},{"type":"shape","id":"nobel07-slide-03-footer-paper","left":44,"top":519,"width":912,"height":33,"rotate":0,"fill":"#F5F0E8","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"圖說底色"},{"type":"text","id":"nobel07-slide-03-boundary","left":44,"top":523,"width":910,"height":27,"rotate":0,"content":"<p style=\"margin:0;font-size:11px;line-height:1.35\">虛構研究者插畫，非坂口本人；細胞表情僅為擬人化。</p>","defaultColor":"#506773","defaultFontName":"Microsoft JhengHei"}],"background":{"type":"solid","color":"#f6f1e6"},"script":"這不是憑空想出來的謎語。早先一些小鼠研究發現，在特定條件下，免疫系統裏少了某些細胞，結果不只是防禦能力改變，還出現了攻擊自身組織的情況。這個反常現象吸引了坂口志文：會不會有些細胞的任務，不是讓攻擊更猛烈，而是約束其他細胞？請注意，這說的是特定動物研究，不是說人只要少一點免疫細胞就一定會生病。我們不需要學習動物實驗操作，只抓住這個值得追問的現象。"}}},{"id":"nobel07-slide-04","stageId":"hk-nobel-07-sakaguchi-illustrated-v2-mandarin","title":"身體不只有一種“保護隊員”","order":4,"outlineId":"nobel07-slide-04-outline","createdAt":1793793600000,"updatedAt":1793793600000,"type":"slide","actions":[{"id":"nobel07-slide-04-focus","type":"spotlight","elementId":"nobel07-slide-04-key"},{"id":"nobel07-slide-04-speech","type":"speech","text":"免疫細胞不是一模一樣的小球。比如，T細胞就是免疫細胞中的一大類，其中還有不同分工。“T”只是它的名字的一部分，今天不用背。科學家如果把它們全裝進同一個“免疫細胞”的大袋子，就可能漏掉不同的作用。就像一棟學校裏，學生、老師和校工都在活動，但不能因此說大家做的是同一件事。","audioId":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2-mandarin/audio/zh-CN/page-04.mp3","audioUrl":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2-mandarin/audio/zh-CN/page-04.mp3"}],"content":{"type":"slide","canvas":{"id":"nobel07-slide-04-canvas","viewportSize":1000,"viewportRatio":0.5625,"theme":{"backgroundColor":"#f6f1e6","themeColors":["#24665f","#bf9949","#102b38"],"fontColor":"#102b38","fontName":"Microsoft YaHei","outline":{"color":"#102b38","width":1,"style":"solid"},"shadow":{"h":0,"v":0,"blur":0,"color":"#000000"}},"elements":[{"type":"image","id":"nobel07-slide-04-art","left":0,"top":0,"width":1000,"height":562.5,"rotate":0,"fixedRatio":true,"src":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2-mandarin/media/04-zh-Hant.png","name":"身體不只有一種“保護隊員”；有些細胞參與攻擊；有些細胞幫助約束反應。"},{"type":"shape","id":"nobel07-slide-04-key","left":44,"top":225,"width":340,"height":220,"rotate":0,"fill":"transparent","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"重點講解區"},{"type":"image","id":"nobel07-slide-04-micrograph","left":44,"top":307,"width":180,"height":180,"rotate":0,"fixedRatio":true,"src":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2-mandarin/media/healthy-t-cell.jpg"},{"type":"text","id":"nobel07-slide-04-caption","left":237,"top":330,"width":205,"height":150,"rotate":0,"content":"<p style=\"margin:0;font-size:12px;line-height:1.35\">T細胞掃描電鏡圖，人工著色。NIAID/NIH · <a href=\"https://commons.wikimedia.org/wiki/File:Healthy_Human_T_Cell.jpg\">來源與公有領域標記</a>。不能憑照片鑒定為調節性T細胞；不是本課實驗圖。</p>","defaultColor":"#47616c","defaultFontName":"Microsoft JhengHei"},{"type":"shape","id":"nobel07-slide-04-footer-paper","left":44,"top":519,"width":912,"height":33,"rotate":0,"fill":"#F5F0E8","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"圖說底色"},{"type":"text","id":"nobel07-slide-04-boundary","left":44,"top":523,"width":910,"height":27,"rotate":0,"content":"<p style=\"margin:0;font-size:11px;line-height:1.35\">右側為細胞教學插畫，不是顯微圖或精確分類。</p>","defaultColor":"#506773","defaultFontName":"Microsoft JhengHei"}],"background":{"type":"solid","color":"#f6f1e6"},"script":"免疫細胞不是一模一樣的小球。比如，T細胞就是免疫細胞中的一大類，其中還有不同分工。“T”只是它的名字的一部分，今天不用背。科學家如果把它們全裝進同一個“免疫細胞”的大袋子，就可能漏掉不同的作用。就像一棟學校裏，學生、老師和校工都在活動，但不能因此說大家做的是同一件事。"}}},{"id":"nobel07-slide-05","stageId":"hk-nobel-07-sakaguchi-illustrated-v2-mandarin","title":"不是給細胞起個名字，就算發現了","order":5,"outlineId":"nobel07-slide-05-outline","createdAt":1793793600000,"updatedAt":1793793600000,"type":"slide","actions":[{"id":"nobel07-slide-05-focus","type":"spotlight","elementId":"nobel07-slide-05-key"},{"id":"nobel07-slide-05-speech","type":"speech","text":"坂口志文和合作者需要拿出證據。他們利用細胞表面的一些分子特徵來區分細胞，就像給混在一起的物品找分類線索。在1995年的研究中，團隊把不同的細胞組合轉移給特定實驗小鼠作比較。從轉移用的細胞組合裏去掉一組細胞後，剩下的細胞組合可能引起自身組織受攻擊；在合適條件下補回那組細胞，能夠阻止這種情況發生。這支持了一件重要的事：那一組細胞確實參與維持控制。它們後來被稱為“調節性T細胞”。這些特徵不是萬能身份證，實驗也不能直接等同於人的治療。","audioId":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2-mandarin/audio/zh-CN/page-05.mp3","audioUrl":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2-mandarin/audio/zh-CN/page-05.mp3"}],"content":{"type":"slide","canvas":{"id":"nobel07-slide-05-canvas","viewportSize":1000,"viewportRatio":0.5625,"theme":{"backgroundColor":"#f6f1e6","themeColors":["#24665f","#bf9949","#102b38"],"fontColor":"#102b38","fontName":"Microsoft YaHei","outline":{"color":"#102b38","width":1,"style":"solid"},"shadow":{"h":0,"v":0,"blur":0,"color":"#000000"}},"elements":[{"type":"image","id":"nobel07-slide-05-art","left":0,"top":0,"width":1000,"height":562.5,"rotate":0,"fixedRatio":true,"src":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2-mandarin/media/05-zh-Hant.png","name":"不是給細胞起個名字，就算發現了；1995年：用實驗區分一群能約束免疫反應的T細胞。"},{"type":"shape","id":"nobel07-slide-05-key","left":44,"top":120,"width":900,"height":130,"rotate":0,"fill":"transparent","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"重點講解區"},{"type":"shape","id":"nobel07-slide-05-footer-paper","left":44,"top":519,"width":912,"height":33,"rotate":0,"fill":"#F5F0E8","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"圖說底色"},{"type":"text","id":"nobel07-slide-05-boundary","left":44,"top":523,"width":910,"height":27,"rotate":0,"content":"<p style=\"margin:0;font-size:11px;line-height:1.35\">特定動物研究的邏輯示意，非數據、非人體治療。</p>","defaultColor":"#506773","defaultFontName":"Microsoft JhengHei"}],"background":{"type":"solid","color":"#f6f1e6"},"script":"坂口志文和合作者需要拿出證據。他們利用細胞表面的一些分子特徵來區分細胞，就像給混在一起的物品找分類線索。在1995年的研究中，團隊把不同的細胞組合轉移給特定實驗小鼠作比較。從轉移用的細胞組合裏去掉一組細胞後，剩下的細胞組合可能引起自身組織受攻擊；在合適條件下補回那組細胞，能夠阻止這種情況發生。這支持了一件重要的事：那一組細胞確實參與維持控制。它們後來被稱為“調節性T細胞”。這些特徵不是萬能身份證，實驗也不能直接等同於人的治療。"}}},{"id":"nobel07-slide-06","stageId":"hk-nobel-07-sakaguchi-illustrated-v2-mandarin","title":"“勸架員”到底做了什麼？","order":6,"outlineId":"nobel07-slide-06-outline","createdAt":1793793600000,"updatedAt":1793793600000,"type":"slide","actions":[{"id":"nobel07-slide-06-focus","type":"spotlight","elementId":"nobel07-slide-06-key"},{"id":"nobel07-slide-06-speech","type":"speech","text":"現在再回到商場。調節性T細胞可以暫時比作幫助約束行動的“勸架員”。它們能通過與其他細胞接觸、釋放信號等方式，限制免疫反應，減少對自身組織的傷害。但沒有一個小人在細胞裏喊“停”，它也不是負責一切的總司令。身體還有別的保護機制。我們今天只認識其中很重要的一種：保護自己，也需要防止自己的保護力量失去控制。","audioId":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2-mandarin/audio/zh-CN/page-06.mp3","audioUrl":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2-mandarin/audio/zh-CN/page-06.mp3"}],"content":{"type":"slide","canvas":{"id":"nobel07-slide-06-canvas","viewportSize":1000,"viewportRatio":0.5625,"theme":{"backgroundColor":"#f6f1e6","themeColors":["#24665f","#bf9949","#102b38"],"fontColor":"#102b38","fontName":"Microsoft YaHei","outline":{"color":"#102b38","width":1,"style":"solid"},"shadow":{"h":0,"v":0,"blur":0,"color":"#000000"}},"elements":[{"type":"image","id":"nobel07-slide-06-art","left":0,"top":0,"width":1000,"height":562.5,"rotate":0,"fixedRatio":true,"src":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2-mandarin/media/06-zh-Hant.png","name":"“勸架員”到底做了什麼？；調節性T細胞：幫助限制其他免疫細胞的反應。"},{"type":"shape","id":"nobel07-slide-06-key","left":44,"top":225,"width":340,"height":220,"rotate":0,"fill":"transparent","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"重點講解區"},{"type":"shape","id":"nobel07-slide-06-footer-paper","left":44,"top":519,"width":912,"height":33,"rotate":0,"fill":"#F5F0E8","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"圖說底色"},{"type":"text","id":"nobel07-slide-06-boundary","left":44,"top":523,"width":910,"height":27,"rotate":0,"content":"<p style=\"margin:0;font-size:11px;line-height:1.35\">接觸與信號的示意，形狀、比例和分子結構未按實物繪製。</p>","defaultColor":"#506773","defaultFontName":"Microsoft JhengHei"}],"background":{"type":"solid","color":"#f6f1e6"},"script":"現在再回到商場。調節性T細胞可以暫時比作幫助約束行動的“勸架員”。它們能通過與其他細胞接觸、釋放信號等方式，限制免疫反應，減少對自身組織的傷害。但沒有一個小人在細胞裏喊“停”，它也不是負責一切的總司令。身體還有別的保護機制。我們今天只認識其中很重要的一種：保護自己，也需要防止自己的保護力量失去控制。"}}},{"id":"nobel07-slide-07","stageId":"hk-nobel-07-sakaguchi-illustrated-v2-mandarin","title":"為什麼是三個人共同獲獎？","order":7,"outlineId":"nobel07-slide-07-outline","createdAt":1793793600000,"updatedAt":1793793600000,"type":"slide","actions":[{"id":"nobel07-slide-07-focus","type":"spotlight","elementId":"nobel07-slide-07-key"},{"id":"nobel07-slide-07-speech","type":"speech","text":"坂口志文不是一個人完成所有發現。瑪麗·布倫科、弗雷德·拉姆斯德爾及合作者找到了一個與嚴重免疫失控有關的關鍵基因。後來，坂口團隊和其他研究者把這個基因與調節性T細胞的形成聯繫起來。可以把它理解成：有人找到了重要的細胞，有人找到了影響這套控制的關鍵線索，多條證據逐步接在一起。這個過程幫助人類理解，免疫系統怎樣避免攻擊自己的組織。你不必背基因的字母名稱。","audioId":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2-mandarin/audio/zh-CN/page-07.mp3","audioUrl":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2-mandarin/audio/zh-CN/page-07.mp3"}],"content":{"type":"slide","canvas":{"id":"nobel07-slide-07-canvas","viewportSize":1000,"viewportRatio":0.5625,"theme":{"backgroundColor":"#f6f1e6","themeColors":["#24665f","#bf9949","#102b38"],"fontColor":"#102b38","fontName":"Microsoft YaHei","outline":{"color":"#102b38","width":1,"style":"solid"},"shadow":{"h":0,"v":0,"blur":0,"color":"#000000"}},"elements":[{"type":"image","id":"nobel07-slide-07-art","left":0,"top":0,"width":1000,"height":562.5,"rotate":0,"fixedRatio":true,"src":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2-mandarin/media/07-zh-Hant.png","name":"為什麼是三個人共同獲獎？；坂口志文／Mary E. Brunkow／Fred Ramsdell。共同研究主題：外周免疫耐受。"},{"type":"shape","id":"nobel07-slide-07-key","left":44,"top":120,"width":900,"height":130,"rotate":0,"fill":"transparent","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"重點講解區"},{"type":"shape","id":"nobel07-slide-07-footer-paper","left":44,"top":519,"width":912,"height":33,"rotate":0,"fill":"#F5F0E8","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"圖說底色"},{"type":"text","id":"nobel07-slide-07-boundary","left":44,"top":523,"width":910,"height":27,"rotate":0,"content":"<p style=\"margin:0;font-size:11px;line-height:1.35\">證據聯繫示意；不是三人在同一實驗現場。</p>","defaultColor":"#506773","defaultFontName":"Microsoft JhengHei"}],"background":{"type":"solid","color":"#f6f1e6"},"script":"坂口志文不是一個人完成所有發現。瑪麗·布倫科、弗雷德·拉姆斯德爾及合作者找到了一個與嚴重免疫失控有關的關鍵基因。後來，坂口團隊和其他研究者把這個基因與調節性T細胞的形成聯繫起來。可以把它理解成：有人找到了重要的細胞，有人找到了影響這套控制的關鍵線索，多條證據逐步接在一起。這個過程幫助人類理解，免疫系統怎樣避免攻擊自己的組織。你不必背基因的字母名稱。"}}},{"id":"nobel07-slide-08","stageId":"hk-nobel-07-sakaguchi-illustrated-v2-mandarin","title":"這對普通人有什麼用？","order":8,"outlineId":"nobel07-slide-08-outline","createdAt":1793793600000,"updatedAt":1793793600000,"type":"slide","actions":[{"id":"nobel07-slide-08-focus","type":"spotlight","elementId":"nobel07-slide-08-key"},{"id":"nobel07-slide-08-speech","type":"speech","text":"有些疾病涉及免疫系統錯誤攻擊自身組織，叫自身免疫病。對患者來說，重要的不只是壓低所有免疫反應，而是能不能減少有害的攻擊，同時盡量保留應對感染的能力。這項發現為尋找更有針對性的辦法提供了方向。研究者已經進行過把調節性T細胞用於1型糖尿病的早期人體試驗，但早期安全性研究不等於證明治癒。不能把這項研究講成“打一針就永遠不會生病”。","audioId":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2-mandarin/audio/zh-CN/page-08.mp3","audioUrl":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2-mandarin/audio/zh-CN/page-08.mp3"}],"content":{"type":"slide","canvas":{"id":"nobel07-slide-08-canvas","viewportSize":1000,"viewportRatio":0.5625,"theme":{"backgroundColor":"#f6f1e6","themeColors":["#24665f","#bf9949","#102b38"],"fontColor":"#102b38","fontName":"Microsoft YaHei","outline":{"color":"#102b38","width":1,"style":"solid"},"shadow":{"h":0,"v":0,"blur":0,"color":"#000000"}},"elements":[{"type":"image","id":"nobel07-slide-08-art","left":0,"top":0,"width":1000,"height":562.5,"rotate":0,"fixedRatio":true,"src":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2-mandarin/media/08-zh-Hant.png","name":"這對普通人有什麼用？；如果保護系統誤傷了身體，我們能更有針對性地幫助它恢復控制嗎？"},{"type":"shape","id":"nobel07-slide-08-key","left":44,"top":225,"width":340,"height":220,"rotate":0,"fill":"transparent","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"重點講解區"},{"type":"shape","id":"nobel07-slide-08-footer-paper","left":44,"top":519,"width":912,"height":33,"rotate":0,"fill":"#F5F0E8","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"圖說底色"},{"type":"text","id":"nobel07-slide-08-boundary","left":44,"top":523,"width":910,"height":27,"rotate":0,"content":"<p style=\"margin:0;font-size:11px;line-height:1.35\">普通生活插畫；治療研究仍需檢驗安全與效果。</p>","defaultColor":"#506773","defaultFontName":"Microsoft JhengHei"}],"background":{"type":"solid","color":"#f6f1e6"},"script":"有些疾病涉及免疫系統錯誤攻擊自身組織，叫自身免疫病。對患者來說，重要的不只是壓低所有免疫反應，而是能不能減少有害的攻擊，同時盡量保留應對感染的能力。這項發現為尋找更有針對性的辦法提供了方向。研究者已經進行過把調節性T細胞用於1型糖尿病的早期人體試驗，但早期安全性研究不等於證明治癒。不能把這項研究講成“打一針就永遠不會生病”。"}}},{"id":"nobel07-slide-09","stageId":"hk-nobel-07-sakaguchi-illustrated-v2-mandarin","title":"有趣的轉折：為什麼不是越多越好？","order":9,"outlineId":"nobel07-slide-09-outline","createdAt":1793793600000,"updatedAt":1793793600000,"type":"slide","actions":[{"id":"nobel07-slide-09-focus","type":"spotlight","elementId":"nobel07-slide-09-key"},{"id":"nobel07-slide-09-speech","type":"speech","text":"假如有人正在破壞商場設施，卻有人把阻止他的保安勸走，會發生什麼？某些腫瘤周圍，也會出現調節性T細胞限制抗腫瘤免疫反應的情況。於是研究者會思考，怎樣在特定部位減輕這種限制，而不是給全身增加更多“勸架員”。所以，這項發現不是告訴我們“免疫越強越好”，也不是“越弱越好”，而是幫助科學家追問：什麼地方、什麼時間，需要怎樣的調節？這是研究方向，不是讓我們自行調節細胞或用藥。","audioId":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2-mandarin/audio/zh-CN/page-09.mp3","audioUrl":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2-mandarin/audio/zh-CN/page-09.mp3"}],"content":{"type":"slide","canvas":{"id":"nobel07-slide-09-canvas","viewportSize":1000,"viewportRatio":0.5625,"theme":{"backgroundColor":"#f6f1e6","themeColors":["#24665f","#bf9949","#102b38"],"fontColor":"#102b38","fontName":"Microsoft YaHei","outline":{"color":"#102b38","width":1,"style":"solid"},"shadow":{"h":0,"v":0,"blur":0,"color":"#000000"}},"elements":[{"type":"image","id":"nobel07-slide-09-art","left":0,"top":0,"width":1000,"height":562.5,"rotate":0,"fixedRatio":true,"src":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2-mandarin/media/09-zh-Hant.png","name":"有趣的轉折：為什麼不是越多越好？；同一種“勸架”作用，也可能在不合適的地方幫倒忙。"},{"type":"shape","id":"nobel07-slide-09-key","left":44,"top":225,"width":340,"height":220,"rotate":0,"fill":"transparent","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"重點講解區"},{"type":"shape","id":"nobel07-slide-09-footer-paper","left":44,"top":519,"width":912,"height":33,"rotate":0,"fill":"#F5F0E8","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"圖說底色"},{"type":"text","id":"nobel07-slide-09-boundary","left":44,"top":523,"width":910,"height":27,"rotate":0,"content":"<p style=\"margin:0;font-size:11px;line-height:1.35\">某些腫瘤中的情境示意；細胞沒有意識。</p>","defaultColor":"#506773","defaultFontName":"Microsoft JhengHei"}],"background":{"type":"solid","color":"#f6f1e6"},"script":"假如有人正在破壞商場設施，卻有人把阻止他的保安勸走，會發生什麼？某些腫瘤周圍，也會出現調節性T細胞限制抗腫瘤免疫反應的情況。於是研究者會思考，怎樣在特定部位減輕這種限制，而不是給全身增加更多“勸架員”。所以，這項發現不是告訴我們“免疫越強越好”，也不是“越弱越好”，而是幫助科學家追問：什麼地方、什麼時間，需要怎樣的調節？這是研究方向，不是讓我們自行調節細胞或用藥。"}}},{"id":"nobel07-slide-10","stageId":"hk-nobel-07-sakaguchi-illustrated-v2-mandarin","title":"諾獎為什麼獎勵這樣的基礎發現？","order":10,"outlineId":"nobel07-slide-10-outline","createdAt":1793793600000,"updatedAt":1793793600000,"type":"slide","actions":[{"id":"nobel07-slide-10-focus","type":"spotlight","elementId":"nobel07-slide-10-key"},{"id":"nobel07-slide-10-speech","type":"speech","text":"這項研究的偉大，不需要靠“已經治好所有疾病”來證明。它讓科學家看見：在保護身體的系統裏，主動約束攻擊也是重要工作。知道這個控制環節，研究者才能更清楚地查找哪裏出了問題、提出新的治療思路，再通過實驗和臨床研究檢驗。基礎發現像在複雜城市地圖上找到了一個過去沒有看清的交通樞紐；有了它，可以研究新的路線，但每條路線能不能走得通，還要逐一驗證。","audioId":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2-mandarin/audio/zh-CN/page-10.mp3","audioUrl":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2-mandarin/audio/zh-CN/page-10.mp3"},{"id":"nobel07-slide-10-discussion","type":"discussion","topic":"為什麼保護身體也需要約束反應？","prompt":"這是一段簡短口頭討論。科學小助手先用一句話說清商場保安比喻的界線；科學故事老師接著用一句話連回免疫控制為何有價值；好奇同學最後用自己的話概括免疫調節的價值和限制。各角色只代表自己發言，不代寫別人的話。完成後把發言交回學生，不繼續延伸新回合；這段毋須開白板或新增圖表。不提供個人診療建議。 生活比喻不可說「保安多抓人必然出錯」：檢查次數增加不必然代表誤抓；不分情況亂抓可能誤傷無辜。免疫調節有助反應適時降下並減少傷害，但可能失衡，不能保證一定停止或完全不誤傷。 每位以香港繁體字簡短發言；好奇同學最後用自己的話概括免疫調節的價值及限制，不提出新的醫療或專業問題。","agentId":"nobel07-assistant"}],"content":{"type":"slide","canvas":{"id":"nobel07-slide-10-canvas","viewportSize":1000,"viewportRatio":0.5625,"theme":{"backgroundColor":"#f6f1e6","themeColors":["#24665f","#bf9949","#102b38"],"fontColor":"#102b38","fontName":"Microsoft YaHei","outline":{"color":"#102b38","width":1,"style":"solid"},"shadow":{"h":0,"v":0,"blur":0,"color":"#000000"}},"elements":[{"type":"image","id":"nobel07-slide-10-art","left":0,"top":0,"width":1000,"height":562.5,"rotate":0,"fixedRatio":true,"src":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2-mandarin/media/10-zh-Hant.png","name":"諾獎為什麼獎勵這樣的基礎發現？；它改變了一個大問題的答案：身體怎樣保護自己，又避免誤傷自己？"},{"type":"shape","id":"nobel07-slide-10-key","left":44,"top":225,"width":340,"height":220,"rotate":0,"fill":"transparent","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"重點講解區"},{"type":"shape","id":"nobel07-slide-10-footer-paper","left":44,"top":519,"width":912,"height":33,"rotate":0,"fill":"#F5F0E8","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"圖說底色"},{"type":"text","id":"nobel07-slide-10-boundary","left":44,"top":523,"width":910,"height":27,"rotate":0,"content":"<p style=\"margin:0;font-size:11px;line-height:1.35\">城市地圖只是類比；新路線能否走通仍需驗證。</p>","defaultColor":"#506773","defaultFontName":"Microsoft JhengHei"}],"background":{"type":"solid","color":"#f6f1e6"},"script":"這項研究的偉大，不需要靠“已經治好所有疾病”來證明。它讓科學家看見：在保護身體的系統裏，主動約束攻擊也是重要工作。知道這個控制環節，研究者才能更清楚地查找哪裏出了問題、提出新的治療思路，再通過實驗和臨床研究檢驗。基礎發現像在複雜城市地圖上找到了一個過去沒有看清的交通樞紐；有了它，可以研究新的路線，但每條路線能不能走得通，還要逐一驗證。"}}},{"id":"nobel07-slide-11","stageId":"hk-nobel-07-sakaguchi-illustrated-v2-mandarin","title":"三次小判斷","order":11,"outlineId":"nobel07-slide-11-outline","createdAt":1793793600000,"updatedAt":1793793600000,"type":"quiz","actions":[{"id":"nobel07-slide-11-speech","type":"speech","text":"現在停一停，試著判斷三個問題。選好答案後提交，就可以看解釋；答錯也可以重試。最後，用自己的話說說：為什麼保護身體，也需要約束免疫反應？不用背標準句子。","audioId":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2-mandarin/audio/zh-CN/page-11-narration-fix-20261109.mp3","audioUrl":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2-mandarin/audio/zh-CN/page-11-narration-fix-20261109.mp3"}],"content":{"type":"quiz","questions":[{"id":"nobel07-slide-11-q1","type":"single","question":"1. 今天的發現，最接近哪句話？","options":[{"value":"A","label":"免疫細胞越多越好"},{"value":"B","label":"有一類T細胞能幫助約束免疫反應"},{"value":"C","label":"人體只有一種免疫細胞"}],"answer":["B"],"analysis":"A：把數量和保護效果混為一談，過度或錯誤的反應也能傷害身體。；B：抓住主線，調節性T細胞參與控制，但並非唯一機制。；C：不對，免疫系統有多種細胞和分工。","points":10,"hasAnswer":true},{"id":"nobel07-slide-11-q2","type":"single","question":"2. 小鼠研究支持某組細胞有保護作用，下一步能直接宣佈人類治療成功嗎？","options":[{"value":"A","label":"能"},{"value":"B","label":"不能，還需針對人的安全性和有效性研究"}],"answer":["B"],"analysis":"A：把動物實驗直接等同於人的療效。；B：正確，動物研究能提供線索，但不能代替臨床檢驗。","points":10,"hasAnswer":true},{"id":"nobel07-slide-11-q3","type":"single","question":"3. 關於調節性T細胞，哪種說法更準確？","options":[{"value":"A","label":"給所有人增加越多越好"},{"value":"B","label":"它們毫無用途"},{"value":"C","label":"作用要結合疾病、部位和情境理解"}],"answer":["C"],"analysis":"A：忽略了某些腫瘤中的控制問題。；B：忽略了維持免疫控制的重要作用。；C：正確，同一種作用是否有幫助，要看具體情境。","points":10,"hasAnswer":true}]}},{"id":"nobel07-slide-12","stageId":"hk-nobel-07-sakaguchi-illustrated-v2-mandarin","title":"帶走一個問題","order":12,"outlineId":"nobel07-slide-12-outline","createdAt":1793793600000,"updatedAt":1793793600000,"type":"slide","actions":[{"id":"nobel07-slide-12-focus","type":"spotlight","elementId":"nobel07-slide-12-key"},{"id":"nobel07-slide-12-speech","type":"speech","text":"坂口志文經過醫學學習和長期研究，與合作者不斷尋找區分細胞的證據。他值得我們學習的，不是“只要堅持就必定拿獎”，而是認真對待反常現象，再用證據檢驗解釋。下次遇到“越多越好”“越強越好”的說法，可以先問一句：它在什麼情況下有用，什麼時候可能有害？下一課，我們認識一位用人工智能研究蛋白質的科學家，看看另一個曾經很難回答的問題，怎樣出現新的研究工具。","audioId":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2-mandarin/audio/zh-CN/page-12.mp3","audioUrl":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2-mandarin/audio/zh-CN/page-12.mp3"}],"content":{"type":"slide","canvas":{"id":"nobel07-slide-12-canvas","viewportSize":1000,"viewportRatio":0.5625,"theme":{"backgroundColor":"#f6f1e6","themeColors":["#24665f","#bf9949","#102b38"],"fontColor":"#102b38","fontName":"Microsoft YaHei","outline":{"color":"#102b38","width":1,"style":"solid"},"shadow":{"h":0,"v":0,"blur":0,"color":"#000000"}},"elements":[{"type":"image","id":"nobel07-slide-12-art","left":0,"top":0,"width":1000,"height":562.5,"rotate":0,"fixedRatio":true,"src":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2-mandarin/media/12-zh-Hant.png","name":"帶走一個問題；遇到和預想相反的結果，先問：是不是漏看了一種作用？"},{"type":"shape","id":"nobel07-slide-12-key","left":44,"top":225,"width":340,"height":220,"rotate":0,"fill":"transparent","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"重點講解區"},{"type":"image","id":"nobel07-slide-12-portrait","left":44,"top":309,"width":110,"height":165,"rotate":0,"fixedRatio":true,"src":"/api/classroom-media/hk-nobel-07-sakaguchi-illustrated-v2-mandarin/media/sakaguchi-portrait.jpg"},{"type":"text","id":"nobel07-slide-12-caption","left":44,"top":482,"width":415,"height":33,"rotate":0,"content":"<p style=\"margin:0;font-size:11px;line-height:1.35\">坂口志文資料照｜文部科學省・大臣官房人事課。<a href=\"https://commons.wikimedia.org/wiki/File:Shimon_Sakaguchi_201711.jpg\">來源</a>／<a href=\"https://creativecommons.org/licenses/by/4.0/\">CC BY 4.0</a>。2017年資料，非領獎現場；原圖未修改。</p>","defaultColor":"#47616c","defaultFontName":"Microsoft JhengHei"},{"type":"shape","id":"nobel07-slide-12-footer-paper","left":44,"top":519,"width":912,"height":33,"rotate":0,"fill":"#F5F0E8","fixedRatio":false,"path":"M 0 0 L 1 0 L 1 1 L 0 1 Z","viewBox":[1,1],"name":"圖說底色"},{"type":"text","id":"nobel07-slide-12-boundary","left":44,"top":523,"width":910,"height":27,"rotate":0,"content":"<p style=\"margin:0;font-size:11px;line-height:1.35\">研究思路插畫，非歷史實驗記錄。</p>","defaultColor":"#506773","defaultFontName":"Microsoft JhengHei"}],"background":{"type":"solid","color":"#f6f1e6"},"script":"坂口志文經過醫學學習和長期研究，與合作者不斷尋找區分細胞的證據。他值得我們學習的，不是“只要堅持就必定拿獎”，而是認真對待反常現象，再用證據檢驗解釋。下次遇到“越多越好”“越強越好”的說法，可以先問一句：它在什麼情況下有用，什麼時候可能有害？下一課，我們認識一位用人工智能研究蛋白質的科學家，看看另一個曾經很難回答的問題，怎樣出現新的研究工具。"}}}]}}],out='artifacts/nobel08',base='https://class.wanli.ai';await fs.mkdir(out,{recursive:true});let browser,last;const report={pass:false,cases:[],limitations:['Candidate classroom intercepted, real chat API, speech deliberately muted; not audio acceptance, formal production route, or future response guarantee.']};
try{browser=await chromium.launch();for(const row of cases){const c=row.course,ctx=await browser.newContext({viewport:{width:1440,height:900},locale:'zh-HK'});const res={id:c.id,candidateSHA:row.sha,chatRequests:[],chatResponses:[],speechRequests:[],pageErrors:[]},pending=[];report.cases.push(res);await ctx.route('**/api/classroom?id=*',r=>new URL(r.request().url()).searchParams.get('id')===c.id?r.fulfill({status:200,contentType:'application/json',body:JSON.stringify({success:true,classroom:c})}):r.continue());const p=await ctx.newPage();last=p;p.on('pageerror',e=>res.pageErrors.push(String(e)));p.on('request',r=>{const path=new URL(r.url()).pathname;if(r.method()!=='POST')return;const b=r.postDataJSON();if(['/api/chat','/api/chat/pi'].includes(path))res.chatRequests.push({sessionType:b.config?.sessionType,triggerAgentId:b.config?.triggerAgentId,agentIds:b.config?.agentIds});if(path==='/api/learner/speech')res.speechRequests.push({agentId:b.agentId,text:b.text})});p.on('response',r=>{const path=new URL(r.url()).pathname;if(['/api/chat','/api/chat/pi'].includes(path))pending.push(r.text().then(body=>res.chatResponses.push({status:r.status(),body})))});await p.goto(base+'/classroom/'+c.id);await p.locator('img:visible').first().waitFor({timeout:60000});const mute=p.getByRole('button',{name:'Mute',exact:true});await mute.first().waitFor();await mute.first().click();const dn=c.scenes.findIndex(s=>s.actions.some(a=>a.type==='discussion'))+1;for(let n=1;n<dn;n++){await p.getByRole('button',{name:'Next scene',exact:true}).first().click();await p.waitForTimeout(250);const pause=p.getByRole('button',{name:'Pause',exact:true});if(await pause.count())await pause.first().click()}await p.getByRole('button',{name:'Play',exact:true}).first().click();const join=p.getByRole('button',{name:/^(加入討論|加入讨论|Join discussion|Join Discussion)$/});await join.waitFor({timeout:180000});await join.click();let settled=false,previous=-1,changed=Date.now();const deadline=Date.now()+240000;while(Date.now()<deadline){await p.waitForTimeout(1000);assert.ok(res.chatRequests.length<=8);if(res.chatRequests.length!==previous){previous=res.chatRequests.length;changed=Date.now()}if(res.chatRequests.length>=3&&res.chatRequests.length===res.chatResponses.length&&Date.now()-changed>8000){settled=true;break}}assert.ok(settled,'Discussion text did not finish');assert.ok(res.chatResponses.every(x=>x.status===200));assert.ok(res.chatRequests.every(x=>x.sessionType==='discussion'));assert.equal(res.speechRequests.length,0,'Audio must remain muted for text-only preview');assert.deepEqual(res.pageErrors,[]);res.pass=true;await p.screenshot({path:out+'/text-preview-'+row.num+'-'+row.lang+'.png',fullPage:true});await Promise.allSettled(pending);await ctx.close()}report.pass=true}catch(e){report.failure=String(e);if(last&&!last.isClosed())await last.screenshot({path:out+'/text-preview-failure.png',fullPage:true}).catch(()=>{});throw e}finally{if(browser)await browser.close();await fs.writeFile(out+'/text-preview.json',JSON.stringify(report,null,2));console.log(JSON.stringify({pass:report.pass,failure:report.failure,cases:report.cases.map(x=>({id:x.id,pass:x.pass,chats:x.chatResponses.length}))}))}
